/* PROCESS STUDIO — 학습 커리큘럼 확장 (2.151)
   ══════════════════════════════════════════════════════════════════════════════
   왜 이 파일이 따로 있나
     `learn-curriculum.js`(2.010)는 선수·코치 두 트랙을 담고 잘 돌고 있다. 거기에 손을 대면
     36모듈이 한꺼번에 위험해진다. 이 파일은 **뒤에 실려 `window.LR_CUR` 를 넓히기만** 한다 —
     `LR_CUR.modules` 는 원본 배열 그대로라 `push` 하면 `byTrack()` 이 바로 본다.

   무엇을 더하나 (사용자 요청: "피지컬, 분석, AT 교육 · 기존 것도 프로세스화 · 같은 언어로 · 중복되지 않게")
     ① **PROCESS 척추** — 커뮤니티가 이미 쓰는 분석 프레임 P·R·O·C·E·S·S 를 학습의 공통 뼈대로 세운다.
        (출처: PROCESS CLASS 8주 과정 · PROCESS 축구 분석 교재. 커뮤니티 내부 자료를 그 구조만 가져왔다.)
     ② **트랙 셋** — 피지컬 · 분석 · AT. 각 3단계 × 6영역, 기존과 **똑같은 문법**.
     ③ **중복을 막는 방식** — 트랙마다 6영역을 새로 지어 내면 '피지컬의 부하 관리'와
        '코치의 훈련 설계'가 겹친다. 그래서 **영역마다 PROCESS 단계를 하나씩 물린다**.
        같은 주제를 두 트랙이 다뤄도 **어느 단계의 · 누구 관점인지**가 붙어 있어 겹침이 아니라 관점 차이가 된다.
     ④ **프로세스화** — 모든 모듈에 `flow` 한 줄: "배운 것을 앱의 어디서 하는가".
        기존 36모듈에도 아래 FLOW 표로 붙인다(원본 파일은 안 건드린다).

   ⚠ 원문은 옮기지 않았다. 기준 기관의 요지를 우리말로 다시 썼다.
   ⚠ 의학·응급 내용(AT 트랙)은 **교육용 정리이지 의료 지시가 아니다.** 각 모듈에 그 경계를 적었다. */
(function(){
if(!window.LR_CUR){ try{console.warn('learn-curriculum-pro: LR_CUR 없음');}catch(_){} return; }
var C=window.LR_CUR;

/* ══ ① PROCESS 척추 ══════════════════════════════════════════════════════════ */
C.process=[
  {k:"P", ko:"관찰",   en:"Perceive",      q:"무엇을 보았는가 — 해석을 섞지 않고"},
  {k:"R", ko:"원인",   en:"Reason",        q:"왜 그렇게 됐는가 — 의도·정보·판단"},
  {k:"O", ko:"구조",   en:"Organize",      q:"어떤 원칙·구조와 이어지는가"},
  {k:"C", ko:"대안",   en:"Create",        q:"다른 방법은 무엇이었나"},
  {k:"E", ko:"실험",   en:"Experiment",    q:"훈련에서 무엇을 시험하는가"},
  {k:"S", ko:"전달",   en:"Share",         q:"선수에게 어떻게 전하는가"},
  {k:"S2",ko:"재관찰", en:"Study again",   q:"다음에 무엇을 다시 보는가"}
];
C.stage=function(k){ return C.process.filter(function(s){return s.k===k;})[0]||null; };

/* ══ ② 트랙 셋의 영역 — 6영역이 PROCESS 7단계에 하나씩 물린다 ══════════════════ */
C.areas.physical=[
  {id:"grow",   ko:"성장과 성숙",   en:"Growth & maturation",     icon:"↗", stage:"P"},
  {id:"load",   ko:"부하 읽기",     en:"Reading load",            icon:"◐", stage:"R"},
  {id:"move",   ko:"움직임 기초",   en:"Movement foundations",    icon:"⤢", stage:"O"},
  {id:"design", ko:"체력 훈련 설계", en:"Physical training design",icon:"✎", stage:"E"},
  {id:"recover",ko:"회복",          en:"Recovery",                icon:"☾", stage:"C"},
  {id:"measure",ko:"측정과 기록",   en:"Testing & monitoring",    icon:"⌗", stage:"S2"}
];
C.areas.analysis=[
  {id:"see",    ko:"사실과 해석",   en:"Fact vs interpretation",  icon:"◎", stage:"P"},
  {id:"cause",  ko:"행동의 원인",   en:"Reverse-engineering",     icon:"⌕", stage:"R"},
  {id:"struct", ko:"구조 읽기",     en:"Reading structure",       icon:"⬢", stage:"O"},
  {id:"oppo",   ko:"상대 분석",     en:"Opposition analysis",     icon:"⚔", stage:"C"},
  {id:"toTrain",ko:"훈련으로 변환", en:"Analysis into training",  icon:"✎", stage:"E"},
  {id:"report", ko:"전달과 영상",   en:"Reporting & video",       icon:"❝", stage:"S"}
];
C.areas.at=[
  {id:"risk",   ko:"위험 신호",     en:"Spotting risk",           icon:"◎", stage:"P"},
  {id:"emerg",  ko:"응급 상황",     en:"Emergency care",          icon:"✚", stage:"R"},
  {id:"assess", ko:"부상 평가",     en:"Injury assessment",       icon:"⌕", stage:"O"},
  {id:"rehab",  ko:"재활 단계",     en:"Rehabilitation",          icon:"↻", stage:"C"},
  {id:"rtp",    ko:"복귀 판단",     en:"Return to play",          icon:"⚑", stage:"E"},
  {id:"record", ko:"기록과 소통",   en:"Documentation",           icon:"❝", stage:"S"}
];

/* 기존 두 트랙의 영역에도 단계를 물린다 — 다섯 트랙이 같은 척추를 쓴다 */
(function(){
  var MAP={
    player:{game:"P",role:"O",lang:"S",laws:"O",body:"R",team:"S2"},
    coach:{game:"P",design:"E",behav:"S",player:"R",match:"C",self:"S2"}
  };
  Object.keys(MAP).forEach(function(t){
    (C.areas[t]||[]).forEach(function(a){ if(!a.stage)a.stage=MAP[t][a.id]||"P"; });
  });
})();

/* 단계별 사람 — 새 트랙의 '누가 듣는가' */
(C.levels||[]).forEach(function(lv){
  lv.who=lv.who||{};
  if(lv.id===1){ lv.who.physical="선수 몸을 처음 맡은 코치 · 피지컬을 곁에서 돕는 스태프";
                 lv.who.analysis="경기를 처음 기록해 보는 코치 · 분석을 맡게 된 스태프";
                 lv.who.at="팀에 하나뿐인 트레이너 · 응급과 재활을 혼자 맡는 스태프"; }
  if(lv.id===2){ lv.who.physical="주간 부하를 직접 짜는 코치 · 시즌을 한 번 돌려 본 스태프";
                 lv.who.analysis="우리 경기와 상대를 정기적으로 보는 분석 담당";
                 lv.who.at="재활 단계를 설계하고 복귀를 판단하는 트레이너"; }
  if(lv.id===3){ lv.who.physical="주기화와 개인화를 설계하는 피지컬 코치";
                 lv.who.analysis="분석을 게임모델·훈련으로 잇는 분석 리드";
                 lv.who.at="예방 프로그램과 스태프 협업을 이끄는 의무 리드"; }
});

/* ══ 출처 — 기존 SOURCES 에 더한다 ═══════════════════════════════════════════ */
var S={
  ypd:{ko:"NSCA · 유소년 저항 훈련과 장기 발달",url:"https://www.nsca.com/about-us/position-statements/youth-training-and-long-term-athletic-development/ltad-youth-resistance-training-and-early-sport-specialization-what-it-all-means/"},
  fifamed:{ko:"FIFA 건강·의학 자료",url:"https://inside.fifa.com/health-and-medical"},
  concussion:{ko:"국제 스포츠 뇌진탕 합의(암스테르담 2022, 2023 발표) · SCAT6",url:"https://bjsm.bmj.com/content/57/11/695"},
  rpe:{ko:"Foster 등 · 세션 RPE 모니터링",url:"https://pubmed.ncbi.nlm.nih.gov/11708692/"},
  ioc:{ko:"IOC 유소년 선수 발달 합의문",url:"https://bjsm.bmj.com/content/49/13/843"},
  process:{ko:"PROCESS STUDIO 자체 분석·관찰 틀",url:""},
  bepro:{ko:"BEPRO — 경기 영상·데이터",url:"https://bepro.ai/ko/"}
};
Object.keys(S).forEach(function(k){ if(!C.sources[k])C.sources[k]=S[k]; });

/* ══ ④ 프로세스화 — 기존 36모듈에 "앱의 어디서 하는가" 한 줄 ═════════════════
   ⚠ 원본 파일을 고치지 않는다. 여기서 id 로 찾아 `flow` 만 얹는다.
   ⚠ 없는 id 는 조용히 건너뛴다 — 원본이 바뀌어도 이 파일 때문에 깨지지 않는다. */
var FLOW={
  /* 선수 트랙 */
  "p1-game":"IDP › 학습 › 경기 읽기에서 국면 이름을 익히고, 코치가 준 경기 준비 화면에서 같은 말을 본다",
  "p1-role":"IDP › 나 › 프로필의 포지션과 팀 › 선수단의 자리 이름이 같은 말이 된다",
  "p1-lang":"팀 › 게임모델 › 팀의 공통 언어에 우리 말을 적어 두면 훈련·경기에서 같은 이름으로 부른다",
  "p1-laws":"IDP › 학습 › 경기 규칙에서 조항을 찾고, 경기 리뷰에서 그 장면을 다시 본다",
  "p1-body":"IDP › 오늘 › 컨디션 체크인에 매일 남기면 팀 › 오늘의 훈련 인원으로 모인다",
  "p1-team":"IDP › 성장 › 분기 목표와 성찰에 남긴다",
  "p2-game":"경기 준비 › 게임플랜의 국면 네 줄을 읽고 내 자리에서 할 일을 찾는다",
  "p2-role":"팀 › 게임모델 › 포지션별 기준에서 내 자리에 요구되는 것을 본다",
  "p2-lang":"팀 › 공용어에서 우리 팀 말과 표준 말을 나란히 본다",
  "p2-laws":"경기 리뷰의 장면과 규칙 조항을 함께 적는다",
  "p2-body":"IDP › 오늘 › 컨디션과 일정의 세션 강도(RPE)를 같이 본다",
  "p2-team":"IDP › 성장 › 코치 리뷰와 면담 기록에서 이어 간다",
  "p3-game":"경기 › 경기 리뷰 › 국면 평가에 내 관점을 남긴다",
  "p3-role":"IDP › 평가 › 유형 지도에서 내가 어느 유형에 가까운지 본다",
  "p3-lang":"팀 › 공용어를 팀 전체가 같은 이름으로 쓰는지 확인한다",
  "p3-laws":"경기 리뷰에서 판정 장면을 규칙으로 설명해 본다",
  "p3-body":"IDP › 성장 › 6주 리뷰에서 몸 상태와 경기력을 함께 본다",
  "p3-team":"IDP › 성장 › 내 무기(강점)와 분기 목표로 잇는다",
  /* 코치 트랙 */
  "c1-game":"팀 › 게임모델 › 국면에서 이 언어를 세우고, 경기 › 경기 준비 › 게임플랜에서 같은 말로 쓴다",
  "c1-design":"일정 › 세션 카드의 주제·강도·훈련 칩으로 그 날 설계가 남는다",
  "c1-behav":"경기 › 경기 리뷰 › 다음 행동에 코치 자신의 개입을 적는다",
  "c1-player":"팀 › 선수단과 IDP › 선수 화면에서 한 명씩 본다",
  "c1-match":"경기 › 경기 준비 › 명단·라인업, 경기 후 › 결과·기록",
  "c1-self":"IDP › 학습 › 학습 로그와 이 학습 과정의 진행률",
  "c2-game":"팀 › 게임모델 › 이번 주기 강조가 IDP 평가의 자리 요구를 만든다",
  "c2-design":"일정 › 주간에서 주제 배분과 국면 배분을 함께 본다",
  "c2-behav":"경기 › 경기 리뷰 › 영상·장면과 선수 개인 피드백",
  "c2-player":"팀 › 평가표와 IDP › 평가에서 자리별 요구와 지금 수준을 맞춰 본다",
  "c2-match":"경기 › 경기 준비 › 상대 분석 · 게임플랜",
  "c2-self":"IDP › 학습 › 학습 과정 3단계 진행률",
  "c3-game":"팀 › 게임모델 전체(원리 → 정체성 → 이번 주기 → 국면)",
  "c3-design":"일정 › 월간·연간의 주제·국면 배분으로 주기화를 확인한다",
  "c3-behav":"팀 › 커뮤니티와 경기 리뷰 공개 설정으로 스태프·선수와 나눈다",
  "c3-player":"IDP › 선수별 성장 사이클(목표 → 실행 → 근거 → 성찰)",
  "c3-match":"경기 › 목록의 전적(정식·친선 승무패·득실)으로 시즌을 본다",
  "c3-self":"IDP › 학습 › 코치 자기 진단과 학습 로그"
};
(C.modules||[]).forEach(function(m){ if(m&&FLOW[m.id]&&!m.flow)m.flow=FLOW[m.id]; });

/* ══ 새 모듈 ═══════════════════════════════════════════════════════════════════
   L(id, ko, en, body, points[], act{}, quiz…) — 기존과 같은 모양이되 act 는 트랙 키를 쓴다. */
function L(id,ko,en,body,points,act,q,o,a,why){
  return {id:id,ko:ko,en:en,body:body,points:points,act:act,quiz:{q:q,o:o,a:a,why:why}};
}
function mod(o){ C.modules.push(o); }

/* ═══════════════════════ 피지컬 · 1 입문 ═══════════════════════ */
mod({id:"f1-grow",track:"physical",level:1,area:"grow",ko:"같은 나이, 다른 몸 — 성장과 성숙",en:"Same age, different bodies",src:["ypd","ioc","kfa"],
 flow:"팀 › 선수단에 생년월일과 조를 적어 두면, 오늘 훈련 인원이 조별로 갈린다 — 몸이 다른 아이를 같은 칸에 넣지 않는 첫걸음",
 why:"유소년에서 가장 큰 변수는 훈련법이 아니라 성숙도 차이다. 같은 U13 안에서 뼈나이가 3~4년 벌어지고, 그 차이가 힘·속도·부상 위험을 전부 흔든다. 이걸 모르면 '노력 부족'으로 오해한다.",
 links:{},
 lessons:[
  L("f1-grow-1",
    "달력 나이·성숙도·훈련 경험",
    "Three ages",
    "달력 나이, 생물학적 성숙도와 훈련 경험은 서로 다른 정보다. 같은 학년이어도 성장 시기와 경험이 다를 수 있다.\n\n키나 생일만으로 성숙도·실력·잠재력을 확정하지 않는다. 성숙도 추정도 오차와 적용 한계가 있다.\n\n훈련은 이 정보에 현재 기술·건강·피로·환경과 개인 목표를 함께 반영해 정한다.",
    ["성숙도·훈련 경험·건강과 측정 조건을 함께 확인한다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "같은 학년 선수의 힘 차이를 어떻게 해석하나?",
    ["성숙도 하나가 모든 차이를 설명한다","성숙도·훈련 경험·건강과 측정 조건을 함께 확인한다","키가 작으면 재능이 부족하다","훈련 나이는 생일만 알면 계산된다"],
    1,
    "성숙도·훈련 경험·건강과 측정 조건을 함께 확인한다"),
  L("f1-grow-2",
    "급성장기 — 증상과 반응에 맞춘다",
    "Peak height velocity",
    "빠른 신체 변화기에 일부 선수는 움직임과 부하 반응의 변화를 겪는다. 모든 선수가 어색해지거나 경기력이 떨어지는 것은 아니다.\n\n통증·절뚝임·기능 제한을 성장의 정상 과정이라고 넘기지 않는다. 활동을 조절하거나 중단하고 필요한 의료 평가로 연결한다.\n\n점프·달리기·방향 전환과 전체 활동·회복을 함께 검토한다. 계속 뛰어야 한다거나 충격 동작만 줄이면 된다는 고정 처방을 쓰지 않는다.",
    ["증상과 기능을 확인해 활동을 조절·중단하고 의료 평가를 요청한다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "급성장기 선수가 통증 때문에 움직임이 달라졌다. 적절한 대응은?",
    ["성장 중이니 계속 뛰게 한다","증상과 기능을 확인해 활동을 조절·중단하고 의료 평가를 요청한다","참으면 지나갈 성장통이라고 단정한다","모든 선수에게 같은 양의 점프만 줄인다"],
    1,
    "증상과 기능을 확인해 활동을 조절·중단하고 의료 평가를 요청한다"),
  L("f1-grow-3",
    "상대 나이 효과 — 기회의 분포를 살피기",
    "Relative age effect",
    "같은 연령 집단에서도 선발 기준일과 생일 사이 차이가 경험과 선발 기회에 영향을 줄 수 있다. 이를 상대 나이 효과라고 한다.\n\n생일이 빠른 선수가 반드시 크거나 성숙한 것은 아니다. 생일과 생물학적 성숙을 같은 정보로 취급하지 않는다.\n\n생일 분포를 볼 때 모집 대상 인구·참여자 분포와 선발 기준일을 함께 확인한다. 분기별 25%에서 벗어났다는 사실만으로 편향을 확정할 수 없다.",
    ["모집·참여 분포와 선발 기준일, 실제 기회 배분을 함께 살핀다"],
    "선발 명단과 지원자 명단의 생일 분포를 비교하고 출전·훈련 기회가 어떻게 배분됐는지 본다.",
    "명단에 특정 생일 분기의 선수가 많으면 무엇을 확인하나?",
    ["각 분기가 반드시 25%여야 한다","모집·참여 분포와 선발 기준일, 실제 기회 배분을 함께 살핀다","생일이 빠르면 모두 조기 성숙이다","늦게 태어난 선수는 자동으로 더 잠재력이 높다"],
    1,
    "모집·참여 분포와 선발 기준일, 실제 기회 배분을 함께 살핀다")
 ]});

mod({id:"f1-load",track:"physical",level:1,area:"load",ko:"부하를 눈이 아니라 숫자로 읽는다",en:"Reading load",src:["rpe","fifamed"],
 flow:"일정 › 세션 카드의 강도(RPE) 와 훈련 시간을 적으면 주간·월간 요약에서 부하 흐름이 보인다",
 why:"코치의 눈은 '오늘 세게 했다'까지만 안다. 부하는 강도 × 시간이고, 문제는 하루가 아니라 주 단위 변화폭에서 온다. 숫자로 적어야 지난주와 비교가 된다.",
 links:{},
 lessons:[
  L("f1-load-1",
    "세션 RPE — 선수의 체감 강도 × 시간",
    "Session load",
    "세션 RPE는 선수가 세션 전체를 얼마나 힘들게 느꼈는지 정한 척도로 답하고 운동 시간과 곱하는 방법이다. 7 × 60분이면 420의 임의 단위다.\n\n대표적인 원 프로토콜은 종료 약 30분 뒤 묻는다. 현장에서는 질문·척도·시점을 일관되게 정하고 선수에게 충분히 설명한다. 모든 연령에서 숫자의 의미가 자동으로 같아지지 않는다.\n\n코치의 계획 강도와 선수의 실제 RPE를 구분한다. 이 값은 내부 부하의 한 지표이며 고속 달리기·증상·회복을 대신하지 않는다.",
    ["420이며, 체감 내부 부하의 한 지표로 해석한다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "선수의 세션 RPE가 7이고 운동 시간이 60분이면?",
    ["420이면 부상 여부를 바로 알 수 있다","420이며, 체감 내부 부하의 한 지표로 해석한다","코치가 정한 강도와 선수 RPE는 언제나 같다","RPE만 있으면 운동 종류와 증상은 볼 필요 없다"],
    1,
    "420이며, 체감 내부 부하의 한 지표로 해석한다"),
  L("f1-load-2",
    "부하의 총량과 변화를 함께 본다",
    "Spikes, not totals",
    "훈련 부하를 볼 때 총량·강도·변화폭·운동 종류와 개인의 준비 상태를 함께 살핀다. 총량은 상관없고 변화만 중요하다는 뜻이 아니다.\n\n휴식 뒤 복귀나 일정이 몰린 주에는 계획과 반응을 확인한다. 부하가 늘었다는 사실만으로 그 주의 부상을 예측할 수는 없다.\n\n급성·만성 부하 비율에는 방법론적 한계가 있다. 하나의 비율이나 “안전 구간”을 개인의 부상 확률처럼 쓰지 않는다. 증상·회복·의료 계획을 함께 보고 조절 이유를 남긴다.",
    ["부하 총량·변화폭·종류·개인 반응을 함께. 특정 비율은 부상 예측 공식이 아니다."],
    "휴식 뒤 훈련에 합류한 선수의 실제 노출과 증상을 살피고, 팀 평균만으로 같은 양을 부여하지 않는다.",
    "주간 부하가 지난주보다 높아졌다. 적절한 판단은?",
    ["증가했으므로 이번 주 부상이 확정됐다","증가 이유와 총량·운동 종류·개인 상태를 함께 검토한다","총량은 중요하지 않으므로 무시한다","한 비율이 기준 안이면 모든 선수가 안전하다"],
    1,
    "부하 총량·변화폭·종류·개인 반응을 함께. 특정 비율은 부상 예측 공식이 아니다."),
  L("f1-load-3",
    "팀 계획과 개인 반응을 함께 보기",
    "Same session, different load",
    "같은 세션에 참가해도 실제 이동·출전 시간과 체감 부담은 다를 수 있다. 최근 활동·성장·건강 상태를 함께 살핀다.\n\n전원이 기본 확인 대상이다. 주의가 필요한 선수에게 추가 관찰을 하되 두세 명만 챙기면 나머지가 안전하다고 가정하지 않는다.\n\n계획을 조절한 이유와 활동 뒤 반응을 남겨 다음 판단에 연결한다.",
    ["전원의 기본 상태를 확인하고 필요에 따라 추가 관찰과 조절을 한다"],
    "경기 출전이 많았던 선수와 적었던 선수의 다음날 활동을 나누고 통증·피로와 실제 수행을 다시 확인한다.",
    "개별 부하 관리에서 적절한 방식은?",
    ["위험군 세 명만 보면 충분하다","전원의 기본 상태를 확인하고 필요에 따라 추가 관찰과 조절을 한다","급성장기면 같은 훈련은 항상 부상으로 이어진다","팀 평균과 같으면 개인 확인은 필요 없다"],
    1,
    "전원의 기본 상태를 확인하고 필요에 따라 추가 관찰과 조절을 한다")
 ]});

mod({id:"f1-move",track:"physical",level:1,area:"move",ko:"달리기·멈추기·방향 바꾸기 — 축구의 기본 동작",en:"Run, stop, change direction",src:["ypd","fifamed"],
 flow:"일정 › 세션 카드의 웜업 칩에 이 동작들을 넣으면 매 훈련의 앞 15분이 기초 동작 시간이 된다",
 why:"유소년의 체력은 '더 뛰게 하기'가 아니라 잘 움직이게 하기에서 시작한다. 멈추고 방향을 바꾸는 동작이 서툴면 그 자리에서 부상이 나고, 그 동작이 좋아지면 경기 속도가 같이 올라간다.",
 links:{},
 lessons:[
  L("f1-move-1",
    "가속과 함께 감속·방향 전환을 익힌다",
    "Deceleration first",
    "축구에서는 달리는 능력과 함께 멈추고 방향을 바꾸는 능력이 필요하다. 감속의 요구는 진입 속도·제동 거리·방향과 개인의 능력에 따라 달라진다.\n\n무릎·발목 손상은 착지·감속·방향 전환 등 여러 상황에서 발생할 수 있다. 특정 동작이나 자세만으로 누가 다칠지 예측하지 않는다.\n\n낮은 속도와 단순한 과제에서 시작해 선수의 수행과 반응에 맞춰 속도·방향·상대의 압박을 더한다. 통증이나 불안정이 나타나면 원인을 확인하고 조절한다.",
    ["가속·감속·방향 전환을 함께 훈련하고 속도와 복잡도를 단계적으로 조절한다."],
    "낮은 속도에서 멈추는 위치를 정해 연습한 뒤, 수행이 안정되면 접근 속도와 방향 선택을 조금씩 바꾼다.",
    "빠르게 달리지만 멈출 때 제어가 어려운 선수에게 적절한 과제는?",
    ["최고 속도만 더 올린다","속도와 제동 거리를 조절해 감속 기술을 익히고 점차 경기 요구를 더한다","이 동작 하나로 다음 부상을 확정한다","통증이 있어도 같은 강도를 유지한다"],
    1,
    "가속·감속·방향 전환을 함께 훈련하고 속도와 복잡도를 단계적으로 조절한다."),
  L("f1-move-2",
    "한 발 지지와 다양한 힘 과제를 익힌다",
    "Single-leg control",
    "차기·달리기·방향 전환에는 한 발로 지지하는 구간이 있다. 균형·힘·협응을 여러 과제에서 살피고 연습한다.\n\n슛할 때 디딤발이 흔들린다는 이유로 모든 동작에 같은 문제가 있다고 단정하지 않는다. 과제와 속도에 따라 수행이 달라지고, 한 자세가 부상을 확정하지도 않는다.\n\n유소년 저항 훈련은 지도·기술·적절한 부하가 중요하다. 체중 운동도 어렵거나 무거울 수 있고, 가벼운 외부 저항이 동작 학습에 도움될 수도 있다. “모든 체중 운동을 완벽히 한 뒤에만 외부 저항”이라는 공통 순서는 없다.",
    ["체중·외부 저항의 이름보다 기술과 개인에게 맞는 난도를 기준으로 고른다."],
    "지원물을 잡은 동작과 가벼운 저항 동작을 비교해 편안하고 제어 가능한 과제를 선택한다.",
    "한 발 스쿼트가 어려운 초보 선수의 저항 훈련은?",
    ["한 발 스쿼트가 되기 전에는 어떤 저항 훈련도 못 한다","지도 아래 더 쉬운 동작이나 보조·가벼운 저항으로 적절한 난도를 찾는다","무거운 중량으로만 자세를 교정한다","디딤발 한 번의 흔들림으로 모든 동작을 평가한다"],
    1,
    "체중·외부 저항의 이름보다 기술과 개인에게 맞는 난도를 기준으로 고른다."),
  L("f1-move-3",
    "예방 프로그램을 꾸준히 실행한다",
    "The warm-up is the programme",
    "연령과 대상에 맞는 신경근 워밍업 프로그램을 선택하고 정해진 동작·빈도·진행 방법을 익힌다.\n\n달리기·균형·근력·착지 등 구성 요소를 적절히 수행하고 지속할 수 있도록 일정과 담당자를 정한다. 시간 부족 외에도 이해·기술·환경 등 실행을 막는 요인을 확인한다.\n\n몇 가지 동작을 임의로 섞거나 축약한 프로그램의 효과를 원 프로그램과 같다고 단정하지 않는다. 증상과 선수 반응을 확인하며 필요하면 전문가에게 자세를 점검받는다.",
    ["대상에 맞는 프로그램과 수행 방법을 익히고 지속·반응을 확인하는 것이다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "예방 워밍업을 도입할 때 필요한 것은?",
    ["이름만 FIFA 11+로 붙이면 같은 효과가 난다","대상에 맞는 프로그램과 수행 방법을 익히고 지속·반응을 확인하는 것이다","부상자가 생기기 전에는 예방이 필요 없다","따로 시간이 없으면 동작을 전부 생략한다"],
    1,
    "대상에 맞는 프로그램과 수행 방법을 익히고 지속·반응을 확인하는 것이다")
 ]});

mod({id:"f1-design",track:"physical",level:1,area:"design",ko:"공을 빼지 않고 체력을 올린다",en:"Fitness with the ball",src:["ypd","knvb","ltad"],
 flow:"일정 › 세션 카드의 주제와 강도를 같이 정하면, 그 주 훈련이 전술과 체력을 한 번에 다뤘는지 보인다",
 why:"유소년에게 공 없는 러닝은 시간을 두 번 쓴다. 같은 시간에 축구도 하고 체력도 올리려면 경기 형태 안에서 강도를 만드는 것이 답이다. 크기·인원·규칙이 강도를 정한다.",
 links:{},
 lessons:[
  L("f1-design-1",
    "인원과 공간은 함께 조절한다",
    "Pitch size sets intensity",
    "작은 게임의 부하는 인원 수 하나로 결정되지 않는다. 같은 인원이라도 공간과 규칙에 따라 달리기·가감속·경합 요구가 달라진다.\n\n인원이 적으면 선수의 관여가 늘 수 있지만 최고속도가 반드시 높아지는 것은 아니다. 최고속도에 도달하려면 달릴 공간과 시간이 필요하다.\n\n전체 면적과 1인당 면적, 운동·휴식 시간, 조커·골키퍼 역할과 규칙을 함께 적는다. 의도한 자극과 실제 선수 반응을 비교해 조절한다.",
    ["작은 게임 — 인원만으로 최고속도·강도를 단정하지 않는다"],
    {"현장에서":"인원·전체 및 1인당 면적·운동/휴식·역할·규칙을 기록하고 실제 달리기·가감속·RPE를 확인한다."},
    "인원을 줄이면 어떤 변화가 항상 일어나는가?",
    ["최고속도가 반드시 높아진다","항상 같은 변화는 없다. 공간과 규칙에 따라 확인해야 한다","심박과 모든 외적 부하가 반드시 줄어든다","회복 훈련이 된다"],
    1,
    "인원·전체 및 1인당 면적·운동/휴식·역할·규칙을 기록하고 실제 달리기·가감속·RPE를 확인한다."),
  L("f1-design-2",
    "주간 부하 — 경기와 회복을 함께 설계하기",
    "Hard days and easy days",
    "경기 일정과 선수의 최근 노출을 기준으로 주간 활동을 설계한다. 토요일 한 경기라면 주중에 주요 자극과 회복을 배치할 수 있지만 정답 요일은 고정되지 않는다.\n\n경기 전날은 피로를 남기지 않는 범위에서 짧은 고속·고강도 자극을 포함할 수도 있다. 짧다는 것과 모든 동작의 강도가 낮다는 것은 다르다.\n\n같은 강도 분류가 반복돼도 시간·종류·개인 반응은 다를 수 있다. 저·중·고 표지만으로 적응이나 회복을 단정하지 않는다.",
    ["경기 일정, 활동의 양·종류와 개인 반응을 함께 확인한다"],
    "주중 경기가 추가되면 기존의 강한 날을 그대로 유지하지 않고 출전 시간과 다음 일정에 맞춰 조정한다.",
    "주간 계획을 판단할 때 필요한 것은?",
    ["토요일 경기면 언제나 화요일이 가장 세야 한다","경기 일정, 활동의 양·종류와 개인 반응을 함께 확인한다","경기 전날에는 빠른 동작을 전혀 하면 안 된다","같은 강도 표시면 훈련 효과가 없다"],
    1,
    "경기 일정, 활동의 양·종류와 개인 반응을 함께 확인한다"),
  L("f1-design-3","어린 선수에게 필요한 것은 다양함이다","Variety before specialisation",
   "한 종목만, 한 동작만 반복하면 그 부위가 먼저 닳는다. 국제 권고는 일관되게 다양한 움직임과 늦은 전문화를 말한다. 축구만 시키는 것보다 뛰고 던지고 구르는 폭이 넓은 아이가 결국 더 멀리 갈 가능성이 크다.",
   ["한 동작 반복이 한 부위를 닳게 한다","다양한 움직임 · 늦은 전문화","1년 내내 같은 종목만은 위험 신호"],
   {physical:"웜업에 축구 아닌 움직임(구르기·던지기·기어가기)을 조금 섞어라.",coach:"연중 쉬는 구간을 일정에 실제로 넣어라 — 안 적으면 안 쉰다."},
   "유소년의 장기 발달에 관한 국제 권고에 가장 가까운 것은?",["한 종목 조기 전문화","다양한 움직임과 늦은 전문화","연중 무휴 훈련","성인 프로그램 축소판"],1,
   "다양함이 먼저다. 전문화는 나중에 와도 늦지 않다.")
 ]});

mod({id:"f1-recover",track:"physical",level:1,area:"recover",ko:"회복은 훈련의 일부다 — 잠·먹기·쉬는 날",en:"Recovery is training",src:["fifamed","ioc"],
 flow:"IDP › 오늘 › 컨디션 체크인(수면·피로)이 팀 › 오늘 훈련 인원으로 모이고, 일정 › 휴식(OFF)이 주간 요약에 잡힌다",
 why:"어린 선수의 회복은 마사지나 장비가 아니라 잠·먹기·쉬는 날 셋에서 거의 결정된다. 이 셋을 놓친 채 회복 도구를 논하는 것은 순서가 뒤집힌 것이다.",
 links:{},
 lessons:[
  L("f1-recover-1",
    "잠 — 회복 계획의 기본",
    "Sleep first",
    "충분한 수면 기회와 규칙적인 생활은 회복과 건강을 돕는다. 필요한 시간은 연령과 개인 상황에 따라 다르다.\n\nAASM 권고는 6~12세 9~12시간, 13~18세 8~10시간이다. 선수의 추가 필요와 실제 수면의 질도 함께 살핀다.\n\n늦은 훈련·이동·학업이나 화면 사용 때문에 취침이 밀리는지 확인한다. 마사지·보충제 등이 수면 부족을 자동으로 메우는 것은 아니다.",
    ["하루 8~10시간이며 개인의 필요와 수면의 질도 살핀다"],
    "귀가와 다음날 등교 시각을 함께 적어 충분히 잘 수 있는지 계산하고 늦은 미팅 시간을 조정한다.",
    "13~18세 선수가 수면을 계획할 때 기본 참고 범위는?",
    ["모두 정확히 7시간이면 된다","하루 8~10시간이며 개인의 필요와 수면의 질도 살핀다","마사지로 잠을 대신한다","어린 선수는 항상 회복이 빨라 수면이 덜 필요하다"],
    1,
    "하루 8~10시간이며 개인의 필요와 수면의 질도 살핀다"),
  L("f1-recover-2",
    "경기 뒤 먹는 것이 다음 훈련을 만든다",
    "Refuel",
    "경기 뒤 탄수화물·단백질과 수분 보충을 준비한다. 다음 세션까지 간격이 짧을수록 일찍 회복 섭취를 시작할 수 있도록 일정을 조절한다.\n\n“30분”과 “1~2시간”을 서로 다른 절대 흡수 기한으로 가르치지 않는다. 하루 전체 섭취, 다음 일정, 개인의 소화와 음식 접근성을 함께 고려한다.\n\n팀이 할 수 있는 일은 경기 뒤 긴 미팅·이동 때문에 식사가 계속 밀리지 않도록 시간과 장소를 확보하는 것이다.\n\n유소년은 보호자와 식사 계획을 연결하고 알레르기·개별 필요를 확인한다. 구체적인 영양 처방은 자격을 갖춘 전문가와 정한다.",
    ["회복 식사의 시간과 장소를 일정에 넣는다. 고정된 흡수 기한보다 전체 섭취와 다음 일정."],
    {"현장에서":"원정 귀가 전에 익숙한 식사·간식을 먹을 자리를 정하고, 긴 리뷰 미팅이 이를 밀어내지 않게 한다."},
    "회복 식사를 지원하는 팀의 실무 행동은?",
    ["특정 시간이 지나면 식사를 포기한다","먹을 시간·장소와 개인 필요를 일정에 반영한다","보충제만 준비하면 된다","하루 전체 섭취는 살피지 않는다"],
    1,
    "일찍 먹을 기회를 만들고 실제 섭취와 다음 일정까지 함께 고려한다."),
  L("f1-recover-3","쉬는 날은 계획이다","Rest is planned, not left over",
   "쉬는 날은 '할 게 없어서 쉬는 날'이 아니라 계획된 날이다. 주간에 하루, 시즌에 몇 주를 미리 적어 두지 않으면 그 시간은 언제나 다른 것에 먹힌다. 일정에 OFF 로 적혀야 실제로 쉰다.",
   ["안 적으면 안 쉰다","주간에 하루, 시즌에 구간","쉬는 날에도 잠과 식사는 그대로"],
   {physical:"연간 달력에 쉬는 구간을 먼저 칠하고 나머지를 채워라.",coach:"일정 › 주간에 OFF 를 실제로 찍어라 — 요약의 '휴식' 칸이 0이면 그 주는 안 쉰 것이다."},
   "쉬는 날을 지키는 가장 확실한 방법은?",["선수에게 맡긴다","일정에 미리 적는다","경기 결과를 보고 정한다","날씨를 본다"],1,
   "적히지 않은 휴식은 사라진다.")
 ]});

mod({id:"f1-measure",track:"physical",level:1,area:"measure",ko:"재는 만큼만 보인다 — 그리고 재면 책임이 생긴다",en:"What you measure",src:["rpe","ypd"],
 flow:"팀 › 선수단의 상태(정상·조절·재활·부상)와 일정의 강도 기록이 만나 다시 볼 수 있는 기록이 된다",
 why:"측정의 목적은 순위표가 아니라 변화를 보는 것이다. 유소년에서 한 번의 기록으로 아이를 나누면 성숙도가 그 줄을 대신 세운다. 같은 아이의 어제와 오늘을 비교하는 도구여야 한다.",
 links:{},
 lessons:[
  L("f1-measure-1",
    "유소년 측정 — 발달 맥락을 함께 읽기",
    "Track change, not rank",
    "체력 측정은 현재 수행과 변화에 대한 일부 정보다. 성숙도·경험·측정 오차·동기와 과제 친숙도가 영향을 줄 수 있다.\n\n개인의 변화를 보되 필요한 경우 타당한 비교 집단도 참고한다. 체력 순위 하나로 잠재력이나 선발을 결정하지 않는다.\n\n건강·통증 보고를 벌점으로 쓰지 않고, 수집 목적과 공유 범위를 설명한다. 모든 선수가 반드시 기록을 숨긴다고 단정할 수는 없다.",
    ["개인 변화와 발달·측정 맥락을 보고 여러 근거 중 하나로 사용한다"],
    "이전보다 기록이 좋아진 선수에게 측정 조건과 연습 경험을 확인하고 다음 목표를 함께 정한다.",
    "유소년 체력 결과를 사용할 때 적절한 것은?",
    ["측정 순위만으로 잠재력을 정한다","개인 변화와 발달·측정 맥락을 보고 여러 근거 중 하나로 사용한다","숫자는 어떤 판단에도 쓸 수 없다","성숙도가 같으면 측정 오차가 없다"],
    1,
    "개인 변화와 발달·측정 맥락을 보고 여러 근거 중 하나로 사용한다"),
  L("f1-measure-2",
    "장비 없이 할 수 있는 세 가지",
    "Three things without equipment",
    "장비가 없어도 세 가지만 꾸준히 쌓으면 필요한 대부분이 보인다.\n\n- 매일 — 컨디션 한 줄(잠 · 피로 · 통증)\n\n- 세션마다 — 강도 × 시간\n\n- 정해진 간격 — 키(성장 속도와 측정 목적에 따라 조절)\n\n이 셋이 각각 무엇을 보여 주는지가 명확하다.\n\n- 매일 컨디션 → 위험 신호(통증이 며칠째인지)\n\n- 세션 강도 → 부하 흐름(튀는 주가 있는지)\n\n- 연속된 키 기록 → 성장 변화의 단서(현재 급성장 여부를 한 번에 확정하지 않음)\n\n그리고 이 절의 핵심 주장 — 비싼 장비보다 끊기지 않는 기록이 강하다.\n\nGPS 조끼가 있어도 가끔 쓰면 흐름이 안 보인다. 반대로 컨디션 한 줄을 매일 받으면, 어느 선수가 3일째 무릎이 아프다고 적고 있는지 보인다. 매일 이어지는 단순한 기록이 가끔 하는 정밀 측정을 이긴다.\n\n다만 조건이 하나 있다 — 코치가 먼저 매일 적어야 한다. 코치가 비우면 팀도 비운다.",
    ["매일 컨디션 한 줄 · 세션마다 강도×시간 · 6개월마다 키."],
    "체크인·세션 강도를 코치가 먼저 매일 적어라 — 코치가 비우면 팀도 비운다. 요구하기 전에 하는 것이 유일하게 작동하는 방법이다. 지난 2주의 세션 강도 기록에 빈 칸이 몇 개인지 세어 보라. 빈 칸이 있으면 그 구간은 비교할 수 없다.",
    "장비 없이 가장 큰 정보를 주는 기록은?",
    ["월 1회 체력 측정","매일 컨디션 + 세션 강도","경기당 활동량 추정","연 2회 신체 검사"],
    1,
    "매일 이어지는 단순한 기록이 가끔 하는 정밀 측정을 이긴다."),
  L("f1-measure-3","기록은 판단을 대신하지 않는다","Numbers inform, people decide",
   "숫자는 '무엇을 볼지'를 알려 줄 뿐 '무엇을 할지'는 말하지 않는다. 부하가 높다고 무조건 빼는 것도, 낮다고 더 시키는 것도 자동이 아니다. 숫자를 근거로 사람이 결정하고 그 결정을 남긴다 — 그게 과정이다.",
   ["숫자는 질문을 준다, 답이 아니다","결정은 사람이 하고 이유를 남긴다","같은 숫자에 다른 결정이 있을 수 있다"],
   {physical:"부하를 낮춘 날, 왜 낮췄는지 한 줄을 같이 남겨라.",coach:"세션 메모에 '오늘 왜 이렇게 했나'를 적어라 — 다음 시즌의 당신이 읽는다."},
   "부하 숫자가 높게 나왔을 때 옳은 태도는?",["자동으로 훈련을 뺀다","숫자를 근거로 사람이 판단하고 이유를 남긴다","무시한다","선수에게 알리지 않는다"],1,
   "자동 규칙은 현장을 이기지 못한다. 근거 있는 판단이 남아야 다음에 쓰인다.")
 ]});

/* ═══════════════════════ 분석 · 1 입문 ═══════════════════════
   PROCESS CLASS 8주 과정의 앞 절반을 학습 모듈 문법으로 다시 세웠다. */
mod({id:"a1-see",track:"analysis",level:1,area:"see",ko:"사실 · 해석 · 평가를 나눈다",en:"Fact, interpretation, judgement",src:["process","fifa"],
 flow:"경기 › 경기 리뷰 › 잘된 점·개선할 점에 사실 먼저, 해석은 그다음 순서로 적는다",
 why:"같은 장면을 보고 코치마다 다른 결론을 내는 이유는 눈이 달라서가 아니라 사실과 해석을 섞기 때문이다. PROCESS 분석의 첫 단계 P(관찰)는 해석을 섞지 않고 기록하는 훈련이다.",
 links:{},
 lessons:[
  L("a1-see-1",
    "관찰·해석·평가를 구분한다",
    "Only what the camera saw",
    "관찰은 영상이나 기록에서 확인한 행동이고, 해석은 이유에 대한 가설이며, 평가는 기준에 비춰 내린 판단이다.\n\n영상에도 시야 밖의 선수, 가려진 장면과 원근 왜곡이 있다. 거리를 정확히 측정하지 않았다면 약 5m처럼 추정임을 적는다. 카메라 밖에서 일어난 일을 없었다고 판단하지 않는다.\n\n선수의 의도와 감정은 장면만으로 확정하지 않고 대화·다른 자료로 확인한다. 관찰 가능한 근거와 불확실한 부분을 구분해 기록한다.",
    ["확인할 수 없는 부분으로 남기고 다른 각도나 자료로 확인한다"],
    "성공·실패 장면을 같은 포함 기준으로 모으고 상대·점수·기회 수와 보이지 않는 정보를 함께 적는다. 다음 관찰에서 가설을 다시 확인한다.",
    "영상에 보이지 않은 선수의 행동은 어떻게 기록하나?",
    ["화면에 없으므로 행동도 없었다고 쓴다","확인할 수 없는 부분으로 남기고 다른 각도나 자료로 확인한다","의도를 표정만으로 확정한다","추정 거리를 정밀 측정값처럼 적는다"],
    1,
    "확인할 수 없는 부분으로 남기고 다른 각도나 자료로 확인한다"),
  L("a1-see-2",
    "한 장면으로 팀을 단정하지 않는다",
    "One clip is not a team",
    "인상적인 한 장면은 기억에 오래 남는다. 그런데 기억에 남는 장면과 자주 일어나는 장면은 다르다.\n\n실점으로 이어진 한 번의 실수는 선명하게 남고, 같은 실수가 안 일어난 스무 번은 기억에 없다. 그래서 기억만으로 판단하면 예외를 원칙으로 착각한다.\n\n경향이 되려면 조건이 있다. 같은 유형의 장면을 여러 개 모아 반복되는지 확인해야 한다.\n\n- 반복되면 → 경향이다. 훈련으로 다룬다\n\n- 반복되지 않으면 → 예외일 가능성과 표본 부족을 구분한다. 드물어도 위험이 크면 대비한다\n\n그리고 이 구분을 안 하면 실제로 문제가 생긴다. 예외를 원칙으로 고치려 들면 팀이 흔들린다.\n\n한 번 나온 장면 때문에 팀 원칙을 바꾸면, 다음 경기에 또 다른 한 장면이 나오고 또 바꾸게 된다. 선수는 기준이 매주 바뀌는 팀에서 뛰게 된다.\n\n그래서 실전 규칙은 하나다 — 다음 경기에 같은 장면이 또 나오는지 먼저 본다.",
    ["기억에 남는 장면 ≠ 자주 일어나는 장면 · 반복되지 않으면 예외로 둔다."],
    "리뷰에서 장면 하나로 원칙을 바꾸지 마라 — 다음 경기에 같은 장면이 또 나오는지 먼저 본다. 한 주 기다리는 것으로 대부분의 오판이 걸러진다. 지난 세 경기에서 같은 유형의 장면을 세어 보라. 한 번뿐이면 예외이고, 세 번이면 다음 훈련 주제다.",
    "한 장면만 보고 팀 원칙을 바꾸면 생기는 문제는?",
    ["선수들이 빨리 적응한다","예외를 원칙으로 만들어 팀이 흔들린다","분석 시간이 늘어난다","상대가 대응하기 쉬워진다"],
    1,
    "경향은 반복에서만 나온다. 매주 원칙이 바뀌면 선수는 기준을 잃는다."),
  L("a1-see-3","무엇을 볼지 먼저 정한다","Decide what to watch",
   "그냥 경기를 틀어 놓고 보면 공을 따라가게 되고, 공은 언제나 가장 재미있는 곳에 있다. 보기 전에 오늘 볼 것 하나를 정하면 다른 것이 보인다 — '우리가 공을 잃은 뒤 첫 5초', '상대 첫 압박선'처럼.",
   ["공을 따라가면 공만 보인다","보기 전에 관찰 초점 하나를 정한다","초점은 한 번에 한두 개"],
   {analysis:"경기를 두 번 본다 — 한 번은 우리 소유, 한 번은 우리 비소유만.",coach:"선수에게 영상을 보여 주기 전에 '무엇을 볼지' 한 문장을 먼저 줘라."},
   "경기를 처음부터 그냥 보면 생기는 일은?",["전체가 골고루 보인다","공을 따라가게 되어 공 없는 곳을 놓친다","분석 속도가 빨라진다","해석이 정확해진다"],1,
   "눈은 공을 따라간다. 초점은 미리 정해야 한다.")
 ]});

mod({id:"a1-cause",track:"analysis",level:1,area:"cause",ko:"의도 → 정보 → 판단 → 실행",en:"Intention, information, decision, execution",src:["process","jordet"],
 flow:"IDP › 평가 › 항목별 관찰 문장이 이 네 단계와 같은 언어를 쓴다 — 기술 문제인지 판단 문제인지 나눠 적는다",
 why:"보이는 것은 실행(마지막 단계)뿐인데 원인은 대개 그 앞에 있다. PROCESS 의 R(원인)은 뒤에서부터 되짚는 훈련이다 — 실수를 본 순간 '무엇을 하려 했나 · 무엇이 보였나 · 무엇을 골랐나'를 거슬러 간다.",
 links:{},
 lessons:[
  L("a1-cause-1","실수는 마지막에 보인다","The error you see is the last step",
   "패스 미스를 보면 기술을 탓하기 쉽다. 하지만 그 앞에 무엇을 하려 했는지(의도) · 무엇을 볼 수 있었는지(정보) · 무엇을 골랐는지(판단) 가 있다. 정보가 없었으면 판단이 좋을 수 없고, 판단이 늦으면 기술이 좋아도 늦는다.",
   ["보이는 것은 실행뿐","앞에 의도·정보·판단이 있다","네 단계 중 어디가 문제인지 정한다"],
   {analysis:"실수 장면마다 네 단계 중 어디가 무너졌는지 한 글자로 적어라(의·정·판·실).",coach:"'왜 그렇게 찼어?'보다 '그때 뭐가 보였어?'를 먼저 물어라."},
   "패스가 상대에게 갔다. 가장 먼저 확인할 것은?",["발 모양","패스 직전에 무엇을 볼 수 있었는가","체력","날씨"],1,
   "볼 수 없었던 것을 고를 수는 없다. 정보가 먼저다."),
  L("a1-cause-2",
    "스캔 — 받기 전에 보는 것",
    "Scanning before receiving",
    "공을 받기 전 고개를 돌려 주변을 확인하는 것을 스캐닝(스캔)이라 부른다. 요르뎃 등의 연구에서는 받기 전 스캔이 잦은 선수일수록 패스 성공률이 높고, 상위 수준 선수일수록 더 자주 스캔하는 경향이 보고되었다.\n\n그런데 현장에서 흔한 실패가 있다 — \"더 봐\"라고 말해도 안 는다.\n\n이유는 분명하다. 스캔은 과제·압박·역할의 영향을 받으며, 필요한 정보가 있는 연습으로 기를 수 있다.\n\n훈련 형태에 등 뒤에서 아무 일도 안 일어나면, 선수는 뒤를 볼 이유가 없다. 그 상태에서 백 번 말해도 고개는 안 돌아간다. 돌려 봐야 아무것도 없기 때문이다.\n\n그래서 해법은 말이 아니라 형태다.\n\n- 등 뒤에서 상황이 바뀌는 형태\n\n- 방향이 있는 론도\n\n- 받는 사람 뒤에 수비수가 들어왔다 나갔다 하는 조건\n\n이런 형태에서는 뒤를 안 보면 손해다. 그리고 손해를 보면 선수는 스스로 보기 시작한다.\n\n볼 이유가 없으면 아무리 말해도 안 본다.",
    ["받기 전 고개를 돌리는 횟수 · 훈련으로 는다 · 등 뒤에 정보가 있어야 본다."],
    "등 뒤에서 상황이 바뀌는 형태(방향 있는 론도)를 넣어라. 말로 요구하는 대신 안 보면 손해인 구조를 만든다. 지금 쓰는 훈련 중 등 뒤에 아무 일도 안 일어나는 형태를 찾아보라. 그 훈련에서는 스캔을 요구해도 늘지 않는다.",
    "스캔 횟수를 늘리는 도움이 될 수 있는 방법은?",
    ["매번 '더 봐'라고 반복해서 말한다","등 뒤 정보가 실제로 필요한 훈련 형태를 만든다","볼터치 반복 횟수를 늘린다","목 스트레칭을 늘린다"],
    1,
    "볼 이유가 없으면 아무리 말해도 안 본다."),
  L("a1-cause-3",
    "기술과 판단 — 조건을 비교해 가설 세우기",
    "Skill or decision",
    "훈련에서는 되는데 경기에서 안 되는 행동을 곧바로 판단 문제로 분류하지 않는다. 압박, 사용 가능한 시간, 피로, 공간과 과제가 달라졌을 수 있다.\n\n반대로 훈련에서도 실패했다고 기술 문제만으로 확정할 수 없다. 과제 이해, 지각 정보, 두려움, 환경도 함께 확인한다.\n\n비슷한 조건의 여러 장면을 비교하고 한 조건씩 바꿔 반응을 관찰한다. 기술 실행과 정보 선택을 따로 기록하되 서로 영향을 준다는 점을 유지한다.",
    ["원인 구분 — 성공 여부만으로 단정하지 말고 조건 비교"],
    {"현장에서":"조건이 다르면 같은 기술도 결과가 달라진다. 압박·시간·피로·과제를 비교하고 여러 장면과 선수 설명으로 원인 가설을 확인한다."},
    "연습에서는 성공하지만 압박이 있는 경기에서 패스가 끊긴다. 먼저 할 일은?",
    ["판단 문제라고 확정한다","압박·시간·공간 등 조건과 선수의 선택을 비교한다","기술 문제라고 확정한다","의지가 약하다고 확정한다"],
    1,
    "조건이 다르면 같은 기술도 결과가 달라진다. 압박·시간·피로·과제를 비교하고 여러 장면과 선수 설명으로 원인 가설을 확인한다.")
 ]});

mod({id:"a1-struct",track:"analysis",level:1,area:"struct",ko:"포메이션이 아니라 관계·거리·공간",en:"Relationships, distance, space",src:["process","rfef"],
 flow:"팀 › 게임모델 › 국면의 원칙과 작전판 장면으로 옮겨 적는다 — 그림이 있으면 같은 구조를 같은 이름으로 부른다",
 why:"4-3-3 은 경기 시작 1초의 사진일 뿐이다. 실제로 봐야 하는 것은 선수들이 서로 얼마나 떨어져 있고, 어떤 선을 만들고, 누가 상대를 붙잡고 누가 자유로운가다. PROCESS 의 O(구조)가 이 눈을 만든다.",
 links:{},
 lessons:[
  L("a1-struct-1","폭·깊이·거리","Width, depth, distance",
   "팀이 공을 잘 옮기는지는 세 가지로 거의 설명된다 — 얼마나 넓게 벌렸는가(폭), 앞뒤로 층이 있는가(깊이), 동료 사이가 너무 멀거나 가깝지 않은가(거리). 좁으면 뺏기고, 너무 멀면 이어지지 않는다.",
   ["폭 — 상대를 좌우로 벌린다","깊이 — 앞뒤 층이 있어야 전진한다","거리 — 너무 멀면 끊기고 가까우면 함께 잡힌다"],
   {analysis:"정지 화면 세 장으로 한 팀의 공격 구조를 설명해 보라.",coach:"작전판에 그 세 장을 그려 보관함에 넣어 두면 다음 훈련의 출발점이 된다."},
   "동료 간 거리가 너무 가까울 때 생기는 문제는?",["패스가 쉬워진다","한 번의 압박에 여러 명이 함께 잡힌다","폭이 넓어진다","깊이가 생긴다"],1,
   "가까움은 연결을 쉽게 하지만 함께 잡히게도 한다."),
  L("a1-struct-2","붙잡는 선수와 자유로운 선수","Who is fixed, who is free",
   "좋은 공격은 상대를 붙잡아 두고(고정) 다른 곳에 자유로운 선수를 만든다. 화면에서 상대 수비가 누구를 보고 있는지 따라가면, 아무도 안 보는 선수가 보인다 — 그 선수가 다음 패스의 답인 경우가 많다.",
   ["누군가를 고정해야 다른 곳이 열린다","상대가 누구를 보는지 따라간다","아무도 안 보는 선수가 답일 때가 많다"],
   {analysis:"장면을 멈추고 상대 수비 시선을 화살표로 그려 보라.",coach:"'프리맨을 찾아라' 대신 '누가 너를 안 보고 있나'로 물어라."},
   "상대를 고정한다는 것은?",["상대를 반칙으로 막는다","우리 선수의 위치로 상대 수비를 묶어 다른 곳을 비운다","상대를 압박한다","오프사이드를 유도한다"],1,
   "위치만으로도 상대를 묶을 수 있다."),
  L("a1-struct-3","네 가지 우위","Four kinds of advantage",
   "어느 곳에서 이기고 있는지를 네 가지로 나눠 본다 — 사람이 더 많은가(수적), 더 좋은 자리에 있는가(위치적), 이 선수가 저 선수보다 나은가(질적), 지금 움직임으로 앞서 있는가(동적). 같은 장면도 어떤 우위를 만들려 했는지에 따라 해석이 달라진다.",
   ["수적 · 위치적 · 질적 · 동적","우리가 만들려는 우위를 정한다","우위 없이 전진하면 운에 맡기는 것"],
   {analysis:"빌드업 성공 장면 열 개에서 어떤 우위가 있었는지 세어 보라.",coach:"게임모델의 원칙을 우위 언어로 적어 두면 훈련 조건이 저절로 나온다."},
   "측면에서 1대1로 이기는 윙어를 활용하는 것은 어떤 우위인가?",["수적","위치적","질적","동적"],2,
   "특정 선수의 능력으로 이기는 것이 질적 우위다.")
 ]});

mod({id:"a1-oppo",track:"analysis",level:1,area:"oppo",ko:"상대를 읽되 우리를 잃지 않는다",en:"Reading the opponent",src:["process","fa"],
 flow:"경기 › 경기 준비 › 상대 분석 국면 보드에 상대 패턴을 배치하고, 게임플랜 네 줄로 우리 답을 적는다",
 why:"상대 분석의 목적은 상대를 흉내 내는 것이 아니라 우리 원칙을 유지한 채 어디를 건드릴지 정하는 것이다. PROCESS 의 C(대안)는 '다른 방법'을 만드는 단계이지 우리를 바꾸는 단계가 아니다.",
 links:{},
 lessons:[
  L("a1-oppo-1","표본을 고른다 — 최근 · 비슷한 상대","Choose the sample",
   "상대의 최근 경기 두세 개를, 되도록 우리와 비슷한 스타일의 팀을 상대한 경기로 고른다. 한 경기만 보면 그 날의 예외를 원칙으로 착각하고, 오래된 경기를 보면 이미 바뀐 팀을 분석하게 된다.",
   ["최근 2~3경기","우리와 비슷한 상대를 만난 경기","한 경기만으로 단정하지 않는다"],
   {analysis:"표본 경기와 고른 이유를 보고서 맨 위에 적어라 — 근거가 없으면 결론도 약하다.",coach:"상대 분석을 요청할 때 '어떤 경기를 봤는지'를 함께 받아라."},
   "상대 분석 표본으로 가장 알맞은 것은?",["가장 최근 1경기","최근 2~3경기 중 우리와 비슷한 상대를 만난 경기","작년 맞대결","가장 크게 이긴 경기"],1,
   "반복을 보려면 여러 경기, 비교하려면 비슷한 상대."),
  L("a1-oppo-2",
    "반복 빈도와 기회 수를 함께 본다",
    "Pattern or exception",
    "같은 행동이 반복되는지 볼 때 횟수뿐 아니라 그 행동을 할 기회, 상대·점수·선수 구성과 시점을 함께 기록한다.\n\n세 경기 중 두 번 나왔다는 사실만으로 안정적인 패턴이 입증되지는 않는다. 드문 행동도 위험이 크면 준비할 가치가 있다.\n\n선수에게는 우선순위가 높은 정보를 간결하게 전달하되 표본과 불확실성을 함께 남긴다. 서너 개는 분량 예시이며 기억력의 보편적 한계가 아니다.",
    ["반복의 단서로 보고 기회 수·맥락·다른 장면을 함께 확인한다"],
    "성공·실패 장면을 같은 포함 기준으로 모으고 상대·점수·기회 수와 보이지 않는 정보를 함께 적는다. 다음 관찰에서 가설을 다시 확인한다.",
    "세 경기에서 두 번 나온 행동은 어떻게 해석하나?",
    ["두 번이면 확정된 패턴이다","반복의 단서로 보고 기회 수·맥락·다른 장면을 함께 확인한다","한 번뿐인 위험은 언제나 무시한다","서너 개를 넘는 정보는 인간이 기억할 수 없다"],
    1,
    "반복의 단서로 보고 기회 수·맥락·다른 장면을 함께 확인한다"),
  L("a1-oppo-3",
    "상대 분석에서 우리 팀의 선택으로",
    "Contain, attack, manage",
    "상대의 강점·공략할 공간·위험을 간결하게 정리하면 경기 계획을 논의하기 쉽다. 세 줄은 전달 형식의 예다.\n\n한 경기의 인상만으로 팀 전체 원칙을 바꾸지 않는다. 강조점·역할·위험 관리를 조정할 수 있고, 충분한 근거와 선수 조건에 따라 원칙 수정도 검토한다.\n\n무엇을 바꾸고 유지하는지 이유와 실행 방법을 명확히 전달한다.",
    ["근거와 선수 조건을 보고 유지할 원칙과 조정할 역할·위험 관리를 정한다"],
    "상대의 빠른 전환에 대비해 뒤 공간을 지키는 역할을 조정하고 선수와 실제 장면으로 확인한다.",
    "강한 상대를 만날 때 경기 계획을 어떻게 조정하나?",
    ["매 경기 전체 원칙을 새로 만든다","근거와 선수 조건을 보고 유지할 원칙과 조정할 역할·위험 관리를 정한다","어떤 근거가 있어도 원칙은 바꿀 수 없다","상대 강점만 보고 우리 조건은 무시한다"],
    1,
    "근거와 선수 조건을 보고 유지할 원칙과 조정할 역할·위험 관리를 정한다")
 ]});

mod({id:"a1-toTrain",track:"analysis",level:1,area:"toTrain",ko:"분석을 훈련으로 바꾸는 다리",en:"From analysis to the session",src:["process","knvb","ltad"],
 flow:"보관함 › 훈련 만들기에서 작전판으로 조건을 그리고, 일정 › 세션 카드의 주제와 훈련 칩으로 그 주에 심는다",
 why:"분석이 훈련으로 이어지지 않으면 그건 감상이다. PROCESS 의 E(실험)는 경기 문제 → 원인 가설 → 목표 행동 → 훈련 조건의 네 칸을 채우는 일이다.",
 links:{},
 lessons:[
  L("a1-toTrain-1",
    "네 칸을 채운다",
    "Four boxes",
    "분석을 훈련으로 옮기는 네 칸이 있다.\n\n- ① 문제 — 경기에서 본 것\n\n- ② 가설 — 그 원인에 대한 생각\n\n- ③ 목표 행동 — 대신 나오길 바라는 것\n\n- ④ 조건 — 그 행동을 시도할 기회를 만드는 규칙\n\n이 네 칸이 채워지면 훈련은 저절로 설계된다. 칸이 비어 있으면 '그냥 하던 훈련'이 나온다.\n\n그리고 가장 자주 비는 칸은 ②번, 원인 가설이다.\n\n왜 그럴까. 문제는 눈에 보이고(라인 사이를 못 넘는다) 조건은 익숙하다(론도를 한다). 그래서 그 사이를 건너뛰고 바로 훈련을 고른다.\n\n그런데 가설이 없으면 조건을 고를 근거가 없다. 라인 사이를 못 넘는 이유가 안 보여서인지 받을 자세가 안 돼서인지 줄 사람이 없어서인지에 따라 조건이 완전히 달라진다.\n\n가설이 없으면 훈련이 문제와 무관해진다.",
    ["문제 → 가설 → 목표 행동 → 조건 · 가장 자주 비는 칸은 가설."],
    "세션 주제를 적을 때 '무슨 문제를 고치려는지'를 같이 적어라. 주제만 적으면 몇 주 뒤 왜 그 훈련을 했는지 아무도 모른다. 이번 주 훈련 하나를 네 칸으로 써 보라. 가설 칸에서 막히면 그 훈련은 아직 근거가 없는 것이다.",
    "훈련 설계에서 가장 자주 비는 칸은?",
    ["문제 식별","원인 가설","목표 행동","훈련 조건"],
    1,
    "문제는 보이고 조건은 익숙하지만, 그 사이의 가설이 빠지면 훈련이 문제와 무관해진다."),
  L("a1-toTrain-2",
    "대표성 — 필요한 경기 정보를 남긴다",
    "Representative design",
    "대표성은 목표 행동을 배우는 데 필요한 경기의 정보와 선택을 연습에 얼마나 남겼는지 살피는 관점이다.\n\n상대·방향·시간과 공간 압박은 유용한 점검 항목이다. 모두 넣어야만 학습이 일어나거나, 하나가 없으면 경기 전이가 전혀 없다는 뜻은 아니다.\n\n기술 연습도 목적에 맞게 사용하고, 경기와 비슷한 선택 상황에서 적용되는지 시간을 두고 확인한다. 한 번의 성공·실패만으로 학습을 확정하지 않는다.",
    ["목표 행동에 필요한 경기 정보와 선택이 연습에 담겼는지 확인하는 것이다"],
    "성공·실패 장면을 같은 포함 기준으로 모으고 상대·점수·기회 수와 보이지 않는 정보를 함께 적는다. 다음 관찰에서 가설을 다시 확인한다.",
    "대표성 점검의 목적은?",
    ["상대 없는 모든 연습을 금지하는 것이다","목표 행동에 필요한 경기 정보와 선택이 연습에 담겼는지 확인하는 것이다","한 번 성공하면 완전히 배웠다고 판정하는 것이다","경기와 조금만 다르면 전이가 전혀 없다고 보는 것이다"],
    1,
    "목표 행동에 필요한 경기 정보와 선택이 연습에 담겼는지 확인하는 것이다"),
  L("a1-toTrain-3",
    "조건이 말보다 강하다",
    "Constraints coach for you",
    "'더 빨리 돌아서'라고 백 번 말하는 것보다, 두 번 터치 제한이나 좁은 구역 하나가 그 행동을 더 많이 만든다.\n\n이유는 시간에 있다. 코치의 말은 순간이고 조건은 훈련 내내 작동한다. 말은 들은 사람만, 들은 그 순간만 영향을 준다. 조건은 모든 선수에게, 모든 반복에서 작동한다.\n\n쓸 수 있는 조건들은 이미 정해져 있다.\n\n- 터치 수 · 구역 · 인원 · 시간 · 득점 규칙\n\n그래서 실전 규칙이 하나 나온다 — 같은 말을 세 번 반복하고 있다면 말이 아니라 조건을 바꿔라.\n\n세 번을 기준으로 두는 이유가 있다. 한두 번은 정보 전달이지만, 반복해서 전달되지 않으면 설명·이해·과제 조건을 다시 볼 신호로 삼는다.\n\n그리고 이 절에는 두 번째 규칙이 있다. 조건을 바꿨는데도 원하는 행동이 안 나오면 무엇을 의심해야 하나?\n\n원인 가설이 틀렸을 가능성이다. 조건이 행동 기회를 만들도록 설계됐는데도 안 나온다면, 그 행동이 안 나오던 이유가 처음 생각한 것과 다르다는 뜻이다. 이때는 조건이 아니라 가설로 돌아간다.",
    ["말은 순간, 조건은 내내 · 조건을 바꿔도 안 나오면 가설이 틀린 것."],
    "같은 말을 세 번 반복하고 있다면 말이 아니라 조건을 바꿔라. 세 번째부터는 말로 안 된다는 것이 이미 증명된 것이다. 이번 주에 가장 많이 한 말을 하나 떠올리고, 그것을 조건 하나로 바꿔 보라.",
    "원하는 행동이 조건을 바꿔도 안 나온다. 무엇을 의심하나?",
    ["선수의 이해 부족","원인 가설이 틀렸을 가능성","조건이 아직 약한 것","반복이 부족한 것"],
    1,
    "조건이 맞는데 행동이 없다면, 문제의 원인을 잘못 짚은 것이다.")
 ]});

mod({id:"a1-report",track:"analysis",level:1,area:"report",ko:"짧게, 그림으로, 한 문장으로",en:"Short, visual, one sentence",src:["process","bepro","uefa"],
 flow:"경기 › 경기 리뷰 › 영상·장면과 선수별 개인 피드백. 팀 › 공용어의 우리 말로 부른다",
 why:"분석의 마지막 단계 S(전달)에서 대부분이 무너진다. 코치가 아는 것과 선수에게 남는 것은 다르다 — 남는 것은 짧은 장면 하나와 한 문장이다.",
 links:{},
 lessons:[
  L("a1-report-1","영상 미팅은 10분을 넘기지 않는다","Ten minutes",
   "어린 선수의 집중은 길지 않고, 장면이 늘수록 앞의 것이 지워진다. 장면 3~5개, 10분 안, 그리고 볼 것을 미리 말해 주고 튼다. 미팅의 목적은 설명이 아니라 다음 경기의 행동 하나를 바꾸는 것이다.",
   ["장면 3~5개 · 10분 안","무엇을 볼지 먼저 말한다","목적은 설명이 아니라 행동 하나"],
   {analysis:"장면을 고를 때 '이 장면으로 무엇을 바꾸나'를 못 적으면 빼라.",coach:"미팅 끝에 선수가 한 문장으로 요약하게 하라 — 못하면 전달이 안 된 것이다."},
   "유소년 영상 미팅에서 가장 흔한 실수는?",["장면이 너무 적다","장면이 많고 길어 아무것도 남지 않는다","화질이 나쁘다","음악이 없다"],1,
   "많이 보여 준 것과 남은 것은 다르다."),
  L("a1-report-2","좋은 장면을 먼저 보여 준다","Start with what worked",
   "실수만 모아 보여 주면 선수는 방어부터 한다. 잘된 장면으로 시작하면 '그때 무엇이 달랐나'를 스스로 말하고, 그 언어로 문제 장면을 볼 수 있다. 순서 하나가 미팅의 온도를 바꾼다.",
   ["잘된 장면 → 문제 장면 순서","잘된 이유를 선수가 말하게 한다","같은 언어로 문제 장면을 본다"],
   {analysis:"문제 장면 하나마다 잘된 장면 하나를 짝지어 준비하라.",coach:"개인 피드백에서도 같은 순서를 쓰라 — 무엇이 좋았는지 먼저."},
   "영상 미팅을 실수 장면으로 시작하면?",["집중이 올라간다","선수가 방어적으로 되어 학습이 줄어든다","시간이 절약된다","기억에 오래 남는다"],1,
   "방어 상태에서는 배우기 어렵다."),
  L("a1-report-3","우리 팀 말로 부른다","Say it in our words",
   "'하프스페이스'라고 부르든 '반칸'이라고 부르든 상관없다. 중요한 것은 팀 전체가 같은 이름으로 부르는 것이다. 분석·훈련·경기에서 이름이 달라지면 선수는 매번 번역해야 한다.",
   ["이름은 무엇이든 되지만 하나여야 한다","분석·훈련·경기에서 같은 말","새 용어를 쓰면 공용어에 등록한다"],
   {analysis:"보고서에 쓴 용어가 팀 공용어에 있는지 확인하라.",coach:"팀 › 공용어에 우리 말을 등록하고 미팅에서 그 말만 써라."},
   "분석 보고서에 팀이 안 쓰는 용어를 쓰면?",["전문성이 올라간다","선수가 번역하느라 메시지를 잃는다","문제없다","코치만 이해하면 된다"],1,
   "전달되지 않은 전문성은 전문성이 아니다.")
 ]});

/* ═══════════════════════ AT · 1 입문 ═══════════════════════
   ⚠⚠ 이 트랙은 **현장 스태프를 위한 교육용 정리**다. 진단·치료 지시가 아니며,
      판단이 필요한 순간에는 언제나 자격을 갖춘 의료인에게 보낸다. 각 모듈에 그 경계를 적었다. */
mod({id:"t1-risk",track:"at",level:1,area:"risk",ko:"다치기 전에 보이는 것들",en:"What you can see before it happens",src:["fifamed","ypd"],
 flow:"팀 › 선수단의 상태(정상·조절·재활·부상)와 IDP › 오늘 컨디션 체크인이 만나는 자리",
 why:"급성 부상은 갑자기 오지만 과사용 부상은 몇 주에 걸쳐 신호를 보낸다. 그 신호를 볼 사람이 팀에 하나도 없으면 부상은 언제나 '갑자기' 온다.",
 links:{},
 lessons:[
  L("t1-risk-1",
    "통증과 움직임의 변화를 함께 듣는다",
    "Change comes before pain",
    "통증, 절뚝임, 평소와 다른 움직임이나 참여도는 선수에게 상태를 물어볼 단서다. 통증보다 다른 신호가 항상 먼저 나타나는 것은 아니다. 표정이나 움직임만으로 손상 여부와 정도를 알 수 없다.\n\n선수가 통증을 말하면 그때 확인한다. 평소 모습과 비교하되, 눈에 띄는 변화가 없다는 이유로 보고를 무시하지 않는다. 언제부터, 어느 동작에서, 활동을 얼마나 제한하는지 선수의 말을 기록한다.\n\n절뚝임이나 심해지는 통증이 있으면 활동을 멈추고 적절한 평가로 연결한다. 코치는 진단 대신 관찰·보고·참여 조절을 담당한다.",
    ["통증 보고와 평소의 변화를 함께 확인 — 보이는 신호만으로 손상을 예측하지 않는다."],
    "통증을 말한 선수에게 “걸을 때와 달릴 때 무엇이 다른가요?”를 묻고, 절뚝임이 있으면 훈련을 중단해 평가를 요청한다.",
    "평소처럼 움직이던 선수가 무릎 통증을 말했다. 먼저 할 일은?",
    ["절뚝이지 않으므로 정상 훈련을 계속시킨다","보고를 듣고 발생 상황과 기능 변화를 확인해 평가로 연결한다","통증은 항상 늦은 신호이므로 이미 심한 손상이라고 진단한다","다른 선수가 같은 말을 할 때까지 기다린다"],
    1,
    "통증 보고와 평소의 변화를 함께 확인 — 보이는 신호만으로 손상을 예측하지 않는다."),
  L("t1-risk-2",
    "지난 부상 이력을 현재 계획에 반영한다",
    "Previous injury",
    "지난 부상은 일부 손상에서 다시 다칠 위험과 관련된 중요한 정보다. 그러나 모든 부상의 가장 강한 예측 요인이거나 개인의 다음 부상을 확정하는 정보는 아니다.\n\n부위·손상 종류·치료와 복귀 과정, 현재 증상과 경기 요구를 함께 본다. 같은 부위가 아파도 이전과 같은 손상이라고 단정하지 않는다.\n\n복귀 뒤 관리 기간은 부상별 계획으로 정한다. 기록은 참여를 지원하는 데 필요한 범위에서 공유하고, 이력만으로 선수를 낙인찍지 않는다.",
    ["부상 이력은 현재 상태와 함께 해석하는 정보이며 개인의 재발을 확정하지 않는다."],
    "지난 발목 손상의 복귀 기록과 지금의 경기 요구를 함께 검토해 추가 평가나 훈련 조절이 필요한지 논의한다.",
    "지난 시즌 발목 부상이 있었다는 정보로 알 수 있는 것은?",
    ["이번 시즌에도 반드시 같은 부상을 입는다는 것","현재 기능·증상과 복귀 이력을 더 확인할 필요가 있다는 것","통증이 없으므로 관리가 전혀 필요 없다는 것","부상 이력만으로 모든 경기 출전을 금지해야 한다는 것"],
    1,
    "부상 이력은 현재 상태와 함께 해석하는 정보이며 개인의 재발을 확정하지 않는다."),
  L("t1-risk-3",
    "일찍 말해도 불이익을 걱정하지 않게",
    "Speaking up is prevention",
    "선수는 출전 기회, 동료의 시선, 증상에 대한 이해 부족 등 여러 이유로 불편함을 말하지 않을 수 있다. “말하면 모두 빠진다”는 경험은 보고를 어렵게 만들 수 있다.\n\n통증 보고 자체를 벌주지 않고, 무엇을 확인하고 누가 판단하는지 설명한다. 말한 선수를 계속 뛰게 하는 것이 목표는 아니다. 안전을 위해 제외하거나 의료 평가가 필요한 때에는 이유와 다음 계획을 알려 준다.\n\n숨긴 통증이 특정 기간의 부상으로 반드시 악화된다고 예측하지 않는다. 선수가 일찍 말할 수 있는 통로와 일관된 대응을 만든다.",
    ["통증 보고를 벌주지 않는다. 참여 여부는 증상과 평가에 따라 별도로 결정한다."],
    "“말해 줘서 고맙다. 지금은 확인이 필요해서 빠지고, 평가 뒤 할 수 있는 활동을 함께 정하자”라고 안내한다.",
    "선수가 아프다고 말하면 출전 제외를 두려워한다. 적절한 대응은?",
    ["보고한 선수는 상태와 무관하게 계속 뛰게 한다","보고를 환영하고 평가·참여 조절의 이유와 다음 계획을 설명한다","참아야 프로라고 말한다","보고한 사실을 다른 선수 앞에서 비난한다"],
    1,
    "통증 보고를 벌주지 않는다. 참여 여부는 증상과 평가에 따라 별도로 결정한다.")
 ]});

mod({id:"t1-emerg",track:"at",level:1,area:"emerg",ko:"현장에서 멈춰야 할 순간",en:"When to stop everything",src:["fifamed","concussion"],
 flow:"경기 › 결과·기록의 메모와 팀 › 선수단 상태를 그 자리에서 바꾼다 — 나중에 적으면 사라진다",
 why:"응급의 핵심은 치료 기술이 아니라 멈추는 판단과 부르는 절차다. 팀에 하나뿐인 스태프가 알아야 할 것은 '무엇을 하느냐'보다 '무엇을 하지 않고 누구를 부르느냐'다.",
 links:{},
 lessons:[
  L("t1-emerg-1",
    "뇌진탕이 의심되면 즉시 경기에서 제외",
    "If in doubt, sit them out",
    "머리·목·몸에 충격을 받은 뒤 뇌진탕이 의심되면 즉시 활동에서 제외하고 평가를 받게 한다. 의심이 해소되지 않은 상태로 같은 날 복귀시키지 않는다.\n\n의식 저하·경련·반복 구토·심한 목 통증 등 위험 신호가 있으면 응급의료 도움을 요청한다. 불필요하게 움직이지 않으며 호흡 이상 등 생명 위협은 응급 절차를 우선한다.\n\n겉으로 괜찮아 보여도 자가 판단이나 간단한 질문만으로 복귀를 결정하지 않는다. 이후 활동·복귀는 적절한 의료 평가와 단계별 계획을 따른다.",
    ["즉시 활동에서 제외해 평가하고 위험 신호가 있으면 응급의료 도움을 요청한다"],
    "충돌 뒤 균형이 흔들리는 선수를 활동에서 제외하고 담당자를 부르며 위험 신호와 안전한 이동 필요를 확인한다.",
    "충격 뒤 뇌진탕이 의심되지만 선수가 괜찮다고 말한다. 어떻게 하나?",
    ["몇 분 쉬면 그날 바로 다시 뛴다","즉시 활동에서 제외해 평가하고 위험 신호가 있으면 응급의료 도움을 요청한다","의식이 있으면 뇌진탕은 아니다","자가 보고만으로 복귀시킨다"],
    1,
    "즉시 활동에서 제외해 평가하고 위험 신호가 있으면 응급의료 도움을 요청한다"),
  L("t1-emerg-2",
    "쓰러진 선수 — 안전·119·호흡·AED",
    "Safety, breathing, help",
    "주변 안전을 확인하고 반응이 없으면 즉시 도움을 요청한다. 119에 신고하고 AED를 가져오게 하며 정상 호흡 여부를 신속히 확인한다.\n\n반응이 없고 정상 호흡이 없거나 헐떡임만 있으면 심정지를 의심한다. 119 안내에 따라 가슴압박을 시작하고 AED가 오면 음성 지시를 따른다. 성인은 분당 100~120회, 약 5~6cm 깊이를 기준으로 한다.\n\n목·척추 손상이 의심되면 불필요하게 일으키거나 옮기지 않는다. 다만 현장이 위험하거나 기도 확보·CPR이 필요하면 우선순위에 따라 움직여야 할 수 있다. 공인 응급처치 교육과 현장 응급 계획을 미리 준비한다.",
    ["119·AED를 요청하고 즉시 가슴압박 등 119 안내에 따른 소생술을 시행한다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "반응이 없고 정상 호흡도 없는 선수를 발견했다. 해야 할 일은?",
    ["의료진이 올 때까지 아무것도 하지 않는다","119·AED를 요청하고 즉시 가슴압박 등 119 안내에 따른 소생술을 시행한다","헐떡임이 있으면 정상 호흡으로 본다","일으켜 세워 걷게 해 본다"],
    1,
    "119·AED를 요청하고 즉시 가슴압박 등 119 안내에 따른 소생술을 시행한다"),
  L("t1-emerg-3","급성 부상 직후 — 지금 할 것과 하지 말 것","First hours",
   "부어오르는 급성 손상에서는 보호하고, 통증 없는 범위에서 조금씩 움직이고, 얼음과 압박·거상으로 붓기를 관리하는 것이 일반적인 초기 원칙이다. 다만 뼈나 인대의 큰 손상이 의심되면 그 자리에서 멈추고 의료로 보낸다. 스태프의 일은 진단이 아니다.",
   ["보호 · 통증 없는 범위의 움직임 · 얼음 · 압박 · 올리기","심한 변형·체중 못 실음·큰 소리가 났으면 즉시 의료로","스태프는 진단하지 않는다"],
   {at:"응급 처치 뒤 반드시 '무슨 일이 있었는지' 다섯 줄을 남겨라 — 다음 사람이 읽는다.",coach:"부상 선수를 그 날 안에 팀 › 선수단 상태에서 바꿔 둬라."},
   "발목을 심하게 접질려 체중을 전혀 못 싣는다. 옳은 조치는?",["스트레칭을 시킨다","보호·냉찜질 후 의료 평가로 보낸다","테이핑하고 계속 뛰게 한다","다음 날까지 지켜본다"],1,
   "체중을 못 싣는 것은 의료 평가가 필요한 신호다.")
 ]});

mod({id:"t1-assess",track:"at",level:1,area:"assess",ko:"무엇을 보고 무엇을 넘길 것인가",en:"Look, ask, refer",src:["fifamed"],
 flow:"팀 › 선수단 › 선수 카드의 상태와 메모. IDP › 면담 기록에 선수 본인의 말을 남긴다",
 why:"현장 스태프의 평가는 진단이 아니라 넘길지 말지를 가르는 분류다. 무엇을 보고 무엇을 물을지 순서가 있으면, 애매한 순간에 흔들리지 않는다.",
 links:{},
 lessons:[
  L("t1-assess-1","묻기 — 언제 · 어떻게 · 소리","When, how, sound",
   "언제 아팠는지(갑자기/서서히), 어떤 동작에서였는지, 그때 소리가 났는지, 지금 체중을 실을 수 있는지. 이 네 가지만으로도 급한 것과 지켜볼 것이 상당히 갈린다.",
   ["갑자기인가 서서히인가","어떤 동작에서였나","소리가 났나","지금 체중을 실을 수 있나"],
   {at:"이 네 질문을 카드로 만들어 가방에 넣어 두라 — 당황하면 순서가 사라진다.",coach:"선수의 첫 말을 그대로 적어라. 요약하면 정보가 사라진다."},
   "부상 직후 물어야 할 것으로 가장 중요한 것은?",["누구 잘못인지","갑자기였는지·소리가 났는지·체중을 실을 수 있는지","다음 경기 출전 가능 여부","통증 점수만"],1,
   "발생 방식과 지금 기능이 분류의 핵심이다."),
  L("t1-assess-2",
    "비교는 반대쪽과 한다",
    "Compare with the other side",
    "부상 부위의 붓기·모양·움직임은 그 선수의 평소 기록과 비교하면 변화가 잘 보인다. 반대쪽도 유용한 참고 정보다.\n\n하지만 반대쪽이 언제나 정상 또는 가장 정확한 기준은 아니다. 원래의 좌우 차이, 이전 부상, 양측 문제나 활동 감소의 영향이 있을 수 있다.\n\n기존 평가와 증상, 다친 기전, 기능 변화를 함께 기록하고 의료진이 해석한다. 좌우가 비슷하다는 사실만으로 정상이나 경기 복귀를 판단하지 않는다.",
    ["반대쪽은 참고 기준 중 하나. 평소 기록·증상·기능과 함께 해석한다."],
    {"현장에서":"양쪽 발목에 부상 이력이 있다면 현재 좌우 비교만으로 정상 범위를 정하지 말고 기존 기록과 의료 평가를 함께 본다."},
    "양쪽 다리 모두 부상 이력이 있다. 현재 좌우가 비슷하면?",
    ["모두 정상이라고 판단한다","기존 기록과 증상·기능을 함께 평가한다","반대쪽을 유일한 기준으로 삼는다","의료 평가 없이 경기 복귀한다"],
    1,
    "양쪽 모두 변화했을 가능성이 있어 좌우 비교 하나로 결론낼 수 없다."),
  L("t1-assess-3","넘겨야 하는 신호","Red flags",
   "심한 변형, 체중을 전혀 못 실음, 관절이 빠진 느낌, 감각 이상이나 저림, 시간이 지나도 심해지는 통증, 머리·목 관련 증상. 이 중 하나라도 있으면 판단하지 말고 넘긴다. 넘기는 것은 실력 부족이 아니라 절차다.",
   ["변형·체중 불가·감각 이상·악화·머리목","하나라도 있으면 넘긴다","넘기는 것이 절차다"],
   {at:"넘긴 뒤에도 기록은 우리가 남긴다 — 언제 무엇을 보고 왜 넘겼는지.",coach:"스태프가 '넘기자'고 하면 그 판단을 경기 상황으로 흔들지 마라."},
   "현장 스태프가 '넘긴다'는 결정을 내리는 것은?",["능력 부족","정해진 절차의 일부","최후의 수단","의료인만 할 수 있는 판단"],1,
   "분류하고 넘기는 것이 현장 스태프의 핵심 역량이다.")
 ]});

mod({id:"t1-rehab",track:"at",level:1,area:"rehab",ko:"재활은 단계다 — 통증이 아니라 기능으로 넘어간다",en:"Stages, not days",src:["fifamed","ypd"],
 flow:"팀 › 선수단 상태를 재활로 두고, 일정 › 세션에서 그 선수가 할 수 있는 부분만 넣는다",
 why:"'며칠이면 돼요?'는 답할 수 없는 질문이다. 재활은 날짜가 아니라 단계를 통과하는 일이고, 각 단계에는 넘어가도 되는 조건이 있다. 조건 없이 날짜로 밀면 재발한다.",
 links:{},
 lessons:[
  L("t1-rehab-1",
    "재활 — 조직 회복과 기능을 함께 확인",
    "Criteria, not calendar",
    "재활 단계는 달력 하나나 통증 하나만으로 정하지 않는다. 손상 종류·조직 회복 시간·증상·기능과 활동 반응을 함께 본다.\n\n통증이 줄어도 고속 동작이나 경기 요구에 준비되지 않았을 수 있다. 반대로 정해진 날짜가 됐다는 이유만으로 자동 진행하지 않는다.\n\n의료진이 정한 제한과 진행 조건을 공유하고 활동 뒤 반응에 따라 재평가한다.",
    ["조직 회복·기능·활동 반응과 의료진의 조건을 함께 확인한다"],
    "가벼운 달리기 뒤 당일·다음날 반응을 확인하고 의료진의 다음 단계 조건을 충족했는지 검토한다.",
    "통증이 줄었고 예상 복귀 날짜가 됐다. 다음 단계 판단은?",
    ["통증이 없으면 언제나 전력 질주한다","조직 회복·기능·활동 반응과 의료진의 조건을 함께 확인한다","달력의 날짜만 맞으면 복귀한다","회복 시간은 전혀 고려하지 않는다"],
    1,
    "조직 회복·기능·활동 반응과 의료진의 조건을 함께 확인한다"),
  L("t1-rehab-2",
    "허용된 활동과 필요한 휴식을 함께 계획한다",
    "Always something to do",
    "부상 뒤 활동 범위는 진단·회복 단계와 의료진 계획에 따른다. 상체·반대쪽·심폐 활동도 모든 부상에서 자동으로 허용되는 것은 아니다.\n\n필요한 휴식은 재활의 일부다. 쉬는 시간을 낭비로 부르거나 소속감을 이유로 훈련장·원정 참여를 강요하지 않는다.\n\n선수의 의사와 상태에 맞춰 미팅·소통을 이어 가고, 가능한 활동과 중단 기준을 명확히 정한다.",
    ["의료진이 허용한 활동·휴식과 선수의 상태·의사다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "부상 선수에게 다른 운동을 시키기 전에 확인할 것은?",
    ["다친 부위만 안 쓰면 어떤 운동도 가능하다","의료진이 허용한 활동·휴식과 선수의 상태·의사다","아무것도 안 하는 시간은 모두 손실이다","소속감을 위해 모든 미팅과 원정에 의무 참석시킨다"],
    1,
    "의료진이 허용한 활동·휴식과 선수의 상태·의사다"),
  L("t1-rehab-3",
    "돌아오는 길에 축구가 있어야 한다",
    "Rehab ends on the pitch",
    "체육관에서 다 나았다고 경기로 바로 돌아가면 그 사이가 비어 있다.\n\n체육관에서 되는 것과 경기에서 되는 것은 다른 과제다(분석 교과서의 대표성과 같은 이야기다). 체육관에는 상대도, 예측 불가능한 방향 전환도, 판단해야 할 순간도 없다.\n\n그래서 복귀는 계단이어야 한다.\n\n- 체육관 → 훈련장 → 팀 훈련 → 경기\n\n그리고 마지막 단계는 실제 축구 동작과 상황이어야 한다.\n\n- 방향 전환\n\n- 상대와의 접촉\n\n- 결정 속도\n\n이 셋이 들어가야 경기에서 만날 부하를 미리 만난 것이 된다.\n\n그리고 이 절의 핵심 경고 — 이 구간을 건너뛰면 경기 요구를 견디는지 확인할 기회를 놓칠 수 있다.\n\n직선 달리기는 되는데 급하게 방향을 바꾸다, 혼자서는 되는데 상대와 부딪히다 다시 다치는 것이 전형적인 패턴이다.\n\n그래서 복귀 첫 경기 출전 시간을 미리 정해 두고 그대로 지킨다. 경기 중에 정하면 상황이 정하게 된다.",
    ["체육관 → 훈련장 → 팀 훈련 → 경기 · 마지막 단계는 축구 동작과 접촉."],
    "복귀 첫 경기 출전 시간을 미리 정해 두고 그대로 지켜라. 경기 중에 정하면 스코어가 정하게 된다. 복귀 예정인 선수의 마지막 단계에 방향 전환·접촉·결정이 들어 있는지 확인해 보라. 없으면 그 단계를 하나 더 넣는다.",
    "체육관 단계를 마친 뒤, 경기 전 마지막 단계에 반드시 들어가야 하는 훈련은?",
    ["체육관에서 무게만 더 늘리는 운동","실제 축구 동작·접촉·결정이 있는 훈련","직선으로 같은 속도 달리기 반복","혼자 하는 볼 리프팅"],
    1,
    "경기로 돌아가려면 경기와 닮은 마지막 단계가 필요하다.")
 ]});

mod({id:"t1-rtp",track:"at",level:1,area:"rtp",ko:"복귀는 합의된 결정이다",en:"Return to play is a shared decision",src:["fifamed","concussion","uefa"],
 flow:"팀 › 선수단 상태를 재활 → 조절 → 정상으로 단계적으로 바꾸고, 그 결정을 세션 메모에 남긴다",
 why:"복귀는 트레이너 혼자, 코치 혼자, 선수 혼자의 결정이 아니다. 의료 · 스태프 · 선수 셋이 각각 답해야 하는 질문이 다르고, 셋이 맞아야 안전한 복귀다.",
 links:{},
 lessons:[
  L("t1-rtp-1",
    "세 사람의 질문이 다르다",
    "Three questions",
    "복귀는 한 사람의 결정이 아니다. 세 사람이 각각 다른 질문에 답한다.\n\n- 의료 — 조직이 나았나\n\n- 스태프 — 축구 동작을 할 수 있나\n\n- 선수 — 나는 준비됐다고 느끼나\n\n하나라도 '아니오'면 복귀는 이르다.\n\n여기서 가장 자주 빠지는 것이 세 번째다. 의료 소견과 기능 검사는 챙기면서 선수 본인의 준비 정도는 안 묻는다.\n\n그런데 두려움과 자신감은 복귀 과정에서 평가할 정보다. 특정 선수의 재발을 그것만으로 예측하지 않는다. 무시할 항목이 아니다.\n\n이유는 이해하기 쉽다. 두려운 선수는 몸을 사린다. 움직임 회피가 보이면 이유를 묻고 기능·증상·심리 상태를 함께 평가한다.\n\n그래서 묻는 자리가 중요하다. \"준비됐어?\"를 명단 발표 자리에서 묻지 않는다.\n\n그 자리에서는 다 된다고 한다. 모두가 보고 있고, 아니라고 하면 자리를 잃는 것처럼 느껴지기 때문이다. 따로, 조용히, 답이 자유로운 자리에서 묻는다.",
    ["의료: 나았나 / 스태프: 되는가 / 선수: 느끼는가 — 하나라도 아니오면 이르다."],
    "'준비됐어?'를 명단 발표 자리에서 묻지 마라 — 그 자리에서는 다 된다고 한다. 따로, 조용히 묻는다. 최근 복귀한 선수에게 지금 어느 동작이 아직 무서운지 물어보라. 답이 있으면 그것이 다음 단계의 과제다.",
    "복귀 판단에서 자주 빠지는 항목은?",
    ["의료진의 소견","선수 본인의 준비 정도","기능 검사 결과","팀의 일정"],
    1,
    "선수의 심리적 준비는 재발과 연결되는 실제 항목이다."),
  L("t1-rtp-2",
    "단계적 복귀와 변경 기준",
    "Graded return",
    "복귀는 허용된 활동에서 팀 훈련·경기 참여로 점진적으로 이어지는 과정이다. 부상별 조직 회복·기능·증상과 선수의 준비를 함께 평가한다.\n\n출전 범위와 중단 기준을 경기 전에 정하고 승패 때문에 늘리지 않는다. 새 통증이나 악화가 있으면 예정된 시간 전에도 중단하고 재평가한다.\n\n뇌진탕 뒤에는 별도의 단계적 복귀를 따른다. 재충격·충돌·낙상 위험이 있는 활동 전에 의료 승인이 필요하며 단계별 최소 24시간은 전체 회복 기간의 보장이 아니다.",
    ["참여를 중단·조절하고 의료진과 상태 및 계획을 다시 확인한다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "복귀 경기에서 예정된 출전 시간이 남았지만 통증이 새로 생겼다. 어떻게 하나?",
    ["미리 정한 시간이므로 끝까지 뛰게 한다","참여를 중단·조절하고 의료진과 상태 및 계획을 다시 확인한다","중요한 경기면 출전 시간을 늘린다","훈련을 마쳤으니 증상 확인은 필요 없다"],
    1,
    "참여를 중단·조절하고 의료진과 상태 및 계획을 다시 확인한다"),
  L("t1-rtp-3",
    "복귀 승인 범위를 확인한다",
    "The weeks after",
    "복귀 승인은 허용 활동과 조건을 구체적으로 확인해야 한다. 팀 훈련 허가, 제한된 경기 참여와 정상 경기 복귀는 서로 다를 수 있다.\n\n복귀 뒤 부하·증상·기능과 선수의 반응을 살피고 의료진과 계획을 조절한다. 팀 평균과 부하가 같다는 이유만으로 위험하거나 안전하다고 단정하지 않는다.\n\n기록에는 실제 허용 범위와 다음 확인 시점을 남긴다. 앱의 상태 표시만으로 의료적 준비를 판정하지 않는다.",
    ["허용 활동·제한·중단 기준과 다음 확인 시점이다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "복귀 승인 문구를 받았을 때 확인할 것은?",
    ["승인이라는 말은 언제나 정상 경기 출전 허가다","허용 활동·제한·중단 기준과 다음 확인 시점이다","팀 평균보다 낮으면 무조건 안전하다","선수 상태는 앱의 색상만 보면 된다"],
    1,
    "허용 활동·제한·중단 기준과 다음 확인 시점이다")
 ]});

mod({id:"t1-record",track:"at",level:1,area:"record",ko:"남기지 않으면 없었던 일이 된다",en:"If it is not written, it did not happen",src:["fifamed","uefa"],
 flow:"팀 › 선수단 상태 · IDP › 면담 기록 · 경기 › 결과·기록의 메모 — 세 곳이 한 선수의 이야기를 이룬다",
 why:"기록은 책임 회피용 서류가 아니다. 다음 사람이 읽을 자료이고, 같은 선수의 다음 부상을 예측하는 유일한 근거다. 팀 스태프가 바뀌어도 선수의 이야기는 남아야 한다.",
 links:{},
 lessons:[
  L("t1-record-1",
    "초기 상황을 빠짐없이 기록한다",
    "Five lines",
    "발생 시각·부위·상황·증상·조치와 다음 계획은 현장 기록의 기본 항목이다. 짧은 메모는 초기 전달을 돕지만 필요한 의료 기록 전체를 대체하지 않는다.\n\n관찰한 사실과 선수의 표현을 구분하고 기록자·시각을 남긴다. 모르는 진단을 추측해 적지 않는다.\n\n상세 건강 정보는 승인된 보관 장소에서 필요한 담당자만 열람하게 한다. 일반 경기 메모에는 운영에 필요한 최소 정보만 남기고 의료 정보의 공유 범위와 보관 기준을 따른다.",
    ["사실·증상·조치·다음 계획을 기록하고 필요한 범위로 보호해 공유한다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "초기 부상 메모를 남기는 적절한 방법은?",
    ["다섯 줄이면 모든 의료 기록을 대신한다","사실·증상·조치·다음 계획을 기록하고 필요한 범위로 보호해 공유한다","상세 병력을 팀 전체 경기 메모에 공개한다","정확하지 않은 진단도 기억에 의존해 확정한다"],
    1,
    "사실·증상·조치·다음 계획을 기록하고 필요한 범위로 보호해 공유한다"),
  L("t1-record-2","보호자와 선수에게 같은 말을 한다","One message",
   "스태프·코치·보호자가 서로 다른 말을 하면 선수가 가장 혼란스럽다. 상태·계획·다음 확인 시점을 한 문장으로 정해 세 곳에 같이 전한다. 특히 어린 선수는 어른들의 말이 갈리면 몰래 뛴다.",
   ["상태 · 계획 · 다음 확인 시점","세 곳에 같은 문장","어른의 말이 갈리면 아이는 숨긴다"],
   {at:"보호자에게 보내는 문장을 코치와 먼저 맞춰라.",coach:"보호자 문의에 스태프와 다른 말을 하지 마라 — 궁금하면 먼저 확인하라."},
   "선수·보호자·코치에게 전할 메시지에서 가장 중요한 것은?",["의학적 상세함","세 곳이 같은 내용을 받는 것","빠른 전달","좋은 소식"],1,
   "말이 갈리는 순간 선수는 가장 편한 말을 고른다."),
  L("t1-record-3",
    "기록에서 반복을 찾아 확인하기",
    "Count at the end",
    "날짜·활동·증상·조치·이후 반응을 일관되게 기록하면 반복을 살필 수 있다. 반복되는 연관성이 곧 원인이라는 뜻은 아니다.\n\n누락된 정보는 없었던 사건으로 세지 않는다. 기억으로 채운 내용은 뒤늦게 작성했다는 점을 표시한다.\n\n패턴이 보이면 노출과 다른 요인을 함께 확인하고 담당자와 계획을 조정한다.",
    ["확인할 단서로 삼고 노출·다른 요인·의료 평가를 함께 검토한다"],
    "훈련 종류와 시간뿐 아니라 경기 출전·개인 활동·증상 시작 시점을 함께 살펴 담당자와 논의한다.",
    "기록에서 특정 훈련 다음날 통증이 반복됐다. 어떻게 해석하나?",
    ["그 훈련이 원인이라고 확정한다","확인할 단서로 삼고 노출·다른 요인·의료 평가를 함께 검토한다","기록이 없던 날은 통증이 전혀 없었다고 본다","패턴이 보이면 진단 없이 치료한다"],
    1,
    "확인할 단서로 삼고 노출·다른 요인·의료 평가를 함께 검토한다")
 ]});

/* ═══════════════════════ 피지컬 · 2 기본 ═══════════════════════ */
mod({id:"f2-grow",track:"physical",level:2,area:"grow",ko:"성숙도로 나눠 본다 — 바이오 밴딩",en:"Bio-banding",src:["ypd","ioc","dfb"],
 flow:"팀 › 선수단의 조(A팀·B팀)를 성숙도로 한 번 짜 보면, 오늘 훈련 인원 화면이 그 조로 갈린다",
 why:"같은 나이로만 묶으면 큰 아이는 힘으로 이기고 작은 아이는 피하는 법만 배운다. 성숙도가 비슷한 아이끼리 붙여 보는 시도를 여러 협회가 쓰는 이유가 여기 있다 — 둘 다 다른 것을 배운다.",
 links:{},
 lessons:[
  L("f2-grow-1",
    "일찍 성숙한 선수도 개인별로 본다",
    "The early developer loses too",
    "성숙 시기는 신체적 조건에 영향을 주지만 기술·판단·장기 잠재력을 결정하지 않는다. 일찍 큰 선수는 기술을 덜 배운다거나 늦게 큰 선수는 결국 더 잘한다는 고정관념을 피한다.\n\n체격이 다른 환경에서 다양한 해결책을 연습할 기회를 마련한다. 성숙도를 고려한 그룹도 안전·경험·기술과 선수의 반응을 함께 검토해 사용한다.\n\n현재 체격만으로 평가하지 않고 여러 시점의 행동·경험과 선수의 의견을 기록한다.",
    ["체격으로 능력을 단정하지 않고 개인의 기술·경험·발달 기회를 함께 본다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "성숙 시기가 다른 선수를 지도할 때 적절한 관점은?",
    ["큰 선수는 모두 판단 능력이 부족하다","체격으로 능력을 단정하지 않고 개인의 기술·경험·발달 기회를 함께 본다","늦게 자란 선수는 모두 성인기에 더 잘한다","성숙도만으로 선발과 잠재력을 결정한다"],
    1,
    "체격으로 능력을 단정하지 않고 개인의 기술·경험·발달 기회를 함께 본다"),
  L("f2-grow-2",
    "성장기 통증은 평가하고 활동을 조절한다",
    "Growth-related pain",
    "성장기에는 무릎·발뒤꿈치 주변의 통증을 경험할 수 있지만, 위치와 나이만으로 성장 관련 문제라고 진단할 수 없다. 다른 손상이나 질환도 고려해야 한다.\n\n통증이 있는 채로 계속 뛰는 것을 기본 답으로 삼지 않는다. 선수의 증상과 기능을 확인하고 의료 평가 및 개별 계획에 따라 활동을 조절한다.\n\n절뚝임·붓기·심해지는 통증이나 야간 통증 등은 확인이 필요한 신호다. 체중을 싣지 못하거나 전신 상태가 좋지 않으면 신속한 평가로 연결한다.",
    ["성장기라는 이유로 통증을 정상화하지 않는다 — 평가와 개별 계획에 따라 활동 조절."],
    "“크는 중이라 그래”라고 넘기지 않고 발생 시점과 동작을 기록해 보호자·의료진에게 전달한다.",
    "급성장기 선수가 무릎이 아프고 절뚝인다. 적절한 대응은?",
    ["성장통이므로 참고 계속 뛴다","활동을 중단하고 증상을 확인해 의료 평가로 연결한다","점프 횟수만 줄이면 진단 없이 계속할 수 있다","두 주가 지날 때까지 보고하지 않는다"],
    1,
    "성장기라는 이유로 통증을 정상화하지 않는다 — 평가와 개별 계획에 따라 활동 조절."),
  L("f2-grow-3",
    "같은 훈련 안에서도 다른 요구를 설계하기",
    "Different, not less",
    "성숙도는 개인화에 참고할 정보 중 하나다. 체격만으로 기술·판단 능력이나 필요한 과제를 정하지 않는다.\n\n경험·현재 수행·건강·자신감을 보고 공간·상대·규칙·역할과 훈련 양을 조절할 수 있다. 필요하면 강도나 양을 낮추는 것도 적절하다.\n\n같은 훈련의 과제를 나누는 방법과 별도 지도가 모두 가능하다. 실행 시간·감독·안전을 함께 계획한다.",
    ["개인의 수행·건강·경험을 보고 과제와 양·강도를 조절한다"],
    "같은 게임에서 한 선수는 압박 거리, 다른 선수는 지원 각도를 조절하고 각자의 실제 반응을 확인한다.",
    "성숙도와 경험이 다른 선수의 과제는 어떻게 정하나?",
    ["덜 자랐으면 무조건 강도를 낮추면 안 된다","개인의 수행·건강·경험을 보고 과제와 양·강도를 조절한다","작은 선수는 몸싸움에서 아무것도 못 배운다","개인화에는 추가 지도 시간이 전혀 필요 없다"],
    1,
    "개인의 수행·건강·경험을 보고 과제와 양·강도를 조절한다")
 ]});

mod({id:"f2-load",track:"physical",level:2,area:"load",ko:"주간 부하를 경기 기준으로 짠다",en:"Building the week around the match",src:["rpe","fifamed"],
 flow:"일정 › 주간의 세션 강도(RPE)와 요약의 강도 분포를 보면 그 주가 실제로 어떤 모양이었는지 나온다",
 why:"주간 계획은 요일이 아니라 경기와의 거리로 짜인다. 경기 다음 날은 회복, 경기에서 가장 먼 날이 가장 세고, 경기 직전은 짧고 날카롭게 — 이 모양이 반복되면 몸이 리듬을 배운다.",
 links:{},
 lessons:[
  L("f2-load-1",
    "경기와의 거리로 계획을 읽는다",
    "MD-3, MD-1, MD+1",
    "MD는 경기일, MD-3은 경기 3일 전, MD+1은 경기 다음 날이다. 표기는 일정의 위치를 뜻하며 그날의 강도를 자동으로 정하지 않는다.\n\n한 경기 주간에는 경기에서 떨어진 날 주요 자극을 배치하고 경기 가까이는 준비·회복을 조절할 수 있다. 실제 배치는 이전 경기, 출전 시간, 훈련 기회와 개인 반응에 따라 달라진다.\n\n경기 날짜가 바뀌면 단순히 주간표를 통째로 옮기지 않는다. 앞선 일정과 회복 간격까지 다시 확인한다. 비출전 선수의 훈련 요구도 별도로 본다.",
    ["MD 표시는 경기와의 거리다. 강도는 일정 전체·출전 노출·개인 반응으로 정한다."],
    "화요일 경기 전 월요일이 이전 경기의 다음 날이기도 하다면 두 일정의 요구를 함께 확인해 계획을 바꾼다.",
    "토요일 경기가 화요일로 옮겨졌다. 계획을 어떻게 고치는가?",
    ["MD-3은 항상 최고 강도이므로 그대로 옮긴다","앞선 경기와 회복 간격까지 확인해 훈련 배치를 다시 조정한다","요일만 바꾸고 선수 상태는 보지 않는다","MD+1에는 모든 선수가 반드시 같은 회복 훈련을 한다"],
    1,
    "MD 표시는 경기와의 거리다. 강도는 일정 전체·출전 노출·개인 반응으로 정한다."),
  L("f2-load-2",
    "개인별 참여 계획을 세우고 갱신한다",
    "Individual ceilings",
    "복귀 선수, 최근 노출이 크게 달라진 선수, 증상이나 피로가 있는 선수는 개인별 참여 계획을 확인한다. “복귀 4주”는 모든 손상의 공통 기준이 아니다.\n\n주 시작 전에 활동 종류·양·강도와 조절 조건을 합의하면 현장에서 일관되게 대응하기 쉽다.\n\n계획을 정했다고 당일 판단이 없어지는 것은 아니다. 참여 전·중·후의 증상과 반응에 따라 재평가하며, 의료진이 정한 제한을 경기 상황 때문에 넘기지 않는다.",
    ["개인 계획은 미리 정하고 매번 반응에 맞춰 갱신한다."],
    "주간 계획에 “통증·수행 저하가 나타나면 중단하고 확인”이라는 조건과 연락할 담당자를 함께 적는다.",
    "주간 계획상 허용된 훈련인데 당일 통증이 새로 나타났다. 어떻게 하는가?",
    ["주 시작 전에 정했으므로 반드시 그대로 한다","참여를 조절하고 상태를 확인해 계획을 재평가한다","복귀 4주가 지났으면 통증과 무관하게 제한을 해제한다","팀 평균만 보고 추가 훈련을 시킨다"],
    1,
    "개인 계획은 미리 정하고 매번 반응에 맞춰 갱신한다."),
  L("f2-load-3",
    "가벼운 구간도 목적에 맞게 계획한다",
    "Planned down weeks",
    "훈련과 회복의 배치는 시즌 목적, 경기 일정, 선수 상태를 함께 반영한다. 3~4주 훈련 뒤 한 주를 가볍게 하는 방식은 사용할 수 있는 예시이지 공통 생리 법칙은 아니다.\n\n회복 기회를 계획하고 피로·수행·증상을 살핀다. 정해진 가벼운 주를 넣지 않았다는 이유만으로 부상이나 번아웃이 반드시 생긴다고 말할 수 없다.\n\n부하를 낮추는 방법에는 시간·반복·강도·충격 노출의 조절이 있다. 무엇을 유지하고 줄일지 목적에 맞춰 정하고 반응을 기록한다.",
    ["가벼운 구간의 시점과 폭은 일정·목적·반응에 맞춰 정한다."],
    "경기가 몰린 주에는 이미 노출이 다르므로 비출전 선수와 많이 뛴 선수의 다음 주 계획을 나눠 검토한다.",
    "팀에 가벼운 주를 배치할 때 기준은?",
    ["모든 선수에게 정확히 4주마다 동일하게 적용한다","경기 일정과 선수의 피로·수행·증상, 훈련 목적을 함께 본다","한 주를 줄이면 부상 위험이 사라진다","쉬는 구간이 없으면 반드시 번아웃이 온다"],
    1,
    "가벼운 구간의 시점과 폭은 일정·목적·반응에 맞춰 정한다.")
 ]});

mod({id:"f2-move",track:"physical",level:2,area:"move",ko:"힘을 붙이는 순서 — 몸무게에서 바깥 무게로",en:"Adding strength in order",src:["ypd","fifamed"],
 flow:"보관함의 웜업 항목을 단계별로 만들어 두고, 일정 › 세션의 웜업 칩으로 그 주 단계를 고른다",
 why:"유소년 근력 훈련은 위험한 것이 아니라 순서를 건너뛸 때 위험하다. 자세 → 자기 체중 → 가벼운 외부 부하 → 속도. 이 순서를 지키면 근력 훈련은 가장 잘 검증된 부상 예방 수단 중 하나가 된다.",
 links:{},
 lessons:[
  L("f2-move-1",
    "근력 훈련 — 기술과 적절한 저항",
    "Technique before load",
    "자격을 갖춘 지도 아래 개인에 맞게 설계한 유소년 저항 훈련은 유익할 수 있다. 어떤 운동도 위험이 전혀 없다는 뜻은 아니다.\n\n체중·외부 저항·보조 동작 중 제어 가능한 과제를 고르고 기술·피로·통증과 준비 상태를 확인한다. 체중 운동이 항상 가장 쉬운 단계는 아니다.\n\n수행이 흔들리면 쉬거나 과제를 조절한다. 자세가 무너질 때까지 반복해 본 횟수를 그대로 처방으로 정하지 않는다.",
    ["제어 가능한 기술과 개인의 준비 상태·회복·반응이다"],
    "가벼운 저항으로 제어 가능한 반복을 관찰하고 피로가 누적되기 전에 쉬며 다음 세트 조건을 정한다.",
    "저항이나 반복 수를 높일 때 확인할 것은?",
    ["나이가 특정 기준을 넘었는지뿐이다","제어 가능한 기술과 개인의 준비 상태·회복·반응이다","자세가 무너질 때까지 센 횟수만이다","선수가 원하면 다른 조건은 필요 없다"],
    1,
    "제어 가능한 기술과 개인의 준비 상태·회복·반응이다"),
  L("f2-move-2",
    "도약과 착지 — 힘을 만들고 제어하기",
    "Jump and land",
    "점프 과제는 도약과 착지, 이어지는 움직임을 함께 다룬다. 손상이 착지 때만 생기는 것은 아니며 자세 하나로 다음 손상을 예측할 수 없다.\n\n낮은 난도에서 제어를 익히고 개인 준비에 맞춰 속도·높이·방향 선택과 접촉 상황을 더한다.\n\n훈련 관찰은 유용하지만 통증이나 기능 문제가 있으면 적절한 평가가 필요하다. 관찰만으로 모든 문제가 보인다고 가정하지 않는다.",
    ["도약·착지의 제어와 개인 반응을 확인해 점진적으로 바꾼다"],
    "낮은 점프 뒤 균형과 불편감을 확인하고 안정되면 방향을 선택하는 과제를 추가한다.",
    "점프 과제의 난도를 올릴 때 적절한 기준은?",
    ["점프 높이만 높으면 된다","도약·착지의 제어와 개인 반응을 확인해 점진적으로 바꾼다","부상은 착지 때만 생긴다","무릎 방향 하나로 미래 부상을 예측한다"],
    1,
    "도약·착지의 제어와 개인 반응을 확인해 점진적으로 바꾼다"),
  L("f2-move-3",
    "빠른 달리기는 점진적으로 준비한다",
    "Touch top speed",
    "경기에서 요구되는 빠른 달리기를 준비하려면 속도 훈련과 실제 노출을 확인한다. 빈도·거리·목표 속도는 나이, 훈련 경험, 부상 이력과 일정에 맞춘다.\n\n“주 1회 최고 속도”가 모두에게 같은 예방 처방은 아니다. 정기적 노출이 필요할 수 있지만 그 자체로 햄스트링 손상을 막는다고 보장하지 않는다.\n\n충분히 준비된 상태에서 점진적으로 요구를 높이고 통증·피로·달리기 질을 확인한다. 작은 게임만으로 원하는 속도에 도달하지 못하면 넓은 공간이나 별도 달리기를 계획할 수 있다.",
    ["속도·빈도·거리를 개인과 일정에 맞춰 점진적으로 준비하고 실제 노출을 확인한다."],
    "복귀 선수에게 팀과 같은 스프린트를 바로 주지 않고, 의료 계획과 이전 속도 노출을 확인해 다음 과제를 정한다.",
    "작은 게임에서 최고 속도 노출이 부족하다. 적절한 대응은?",
    ["전원에게 피로와 무관하게 같은 전력 질주를 추가한다","선수의 준비 상태에 맞춰 넓은 공간 또는 별도 속도 과제를 계획한다","주 1회만 뛰면 햄스트링 손상은 예방된다","경기에서 처음 빠르게 달리게 둔다"],
    1,
    "속도·빈도·거리를 개인과 일정에 맞춰 점진적으로 준비하고 실제 노출을 확인한다.")
 ]});

mod({id:"f2-design",track:"physical",level:2,area:"design",ko:"축구 체력은 간헐적이다",en:"Football fitness is intermittent",src:["knvb","ypd","rpe"],
 flow:"보관함 › 훈련 만들기에서 코트 크기·인원·시간을 정해 저장하고, 일정 › 세션의 훈련 칩으로 불러 쓴다",
 why:"축구 선수는 길게 일정하게 뛰지 않는다. 짧고 세게, 쉬고, 다시. 그래서 체력 훈련도 그 리듬을 닮아야 하고, 그 리듬은 경기 형태 안에서 가장 정확하게 만들어진다.",
 links:{},
 lessons:[
  L("f2-design-1","일하는 시간과 쉬는 시간","Work and rest",
   "같은 4v4라도 4분 하고 1분 쉬는 것과 1분 하고 1분 쉬는 것은 전혀 다른 자극이다. 짧게-충분히 쉬면 속도가 유지되고, 길게-덜 쉬면 버티는 능력이 자극된다. 무엇을 기르려는지 정하고 시간을 정한다.",
   ["짧게+충분한 휴식 = 속도","길게+짧은 휴식 = 버티기","목적을 정하고 시간을 정한다"],
   {physical:"세션 계획에 '몇 분 하고 몇 분 쉬는지'를 적어라 — 이게 빠지면 강도가 우연이 된다.",coach:"게임 시간을 눈대중으로 끊지 마라. 시계를 두고 같은 길이로."},
   "속도를 유지한 채 반복하는 능력을 기르려면?",["길게 하고 짧게 쉰다","짧게 하고 충분히 쉰다","계속 이어서 한다","쉬지 않는다"],1,
   "속도는 회복이 있어야 반복된다."),
  L("f2-design-2","포지션마다 요구가 다르다","Positions demand differently",
   "측면 선수는 최고 속도와 반복 스프린트가, 중앙 미드필더는 총 거리와 방향 전환이, 센터백은 가속과 공중 경합이 상대적으로 많다. 팀 체력 훈련 위에 자리별 보충을 조금 얹으면 훨씬 정확해진다.",
   ["측면 — 최고 속도·반복 스프린트","중앙 — 거리·방향 전환","수비 중앙 — 가속·경합"],
   {physical:"팀 세션 뒤 5분을 자리별 보충으로 쓰라.",coach:"팀 › 게임모델 › 포지션별 기준의 '신체' 칸과 같은 말로 적어라."},
   "측면 공격수에게 상대적으로 더 중요한 체력 요소는?",["총 이동 거리","최고 속도와 반복 스프린트","공중 경합","저강도 지구력"],1,
   "자리마다 경기에서 요구되는 것이 다르다."),
  L("f2-design-3","시즌 안에서 오르내린다","Periodisation, simply",
   "프리시즌에 바탕을 쌓고, 시즌 중에는 유지하며 경기에 맞추고, 대회 앞에서는 줄이고 날을 세운다. 복잡한 이론보다 지금이 어느 구간인지 팀이 아는 것이 먼저다.",
   ["프리시즌 — 바탕 쌓기","시즌 중 — 유지·경기 맞춤","대회 전 — 줄이고 날 세우기"],
   {physical:"연간 달력에 구간 이름을 칠해 두고 매달 그 구간을 확인하라.",coach:"월간 요약의 강도 분포로 그 구간이 계획대로 갔는지 본다."},
   "대회 직전 주에 일반적으로 하는 것은?",["훈련량을 최대로","양을 줄이고 강도는 날카롭게","완전 휴식","평소와 동일"],1,
   "줄이되 무뎌지지 않게 — 그것이 날을 세우는 일이다.")
 ]});

mod({id:"f2-recover",track:"physical",level:2,area:"recover",ko:"경기 뒤 72시간을 설계한다",en:"The 72 hours after",src:["fifamed","rpe"],
 flow:"일정 › MD+1·MD+2 세션의 강도와 IDP › 컨디션 체크인이 같은 화면에서 만난다",
 why:"경기 다음 이틀은 몸이 가장 크게 흔들리는 구간이다. 이 시간을 계획하지 않으면 다음 경기 준비가 아니라 회복 지연을 안고 다음 주를 시작한다.",
 links:{},
 lessons:[
  L("f2-recover-1",
    "경기 다음 날도 개인별로 계획한다",
    "Move to recover",
    "경기 다음 날에는 실제 출전 시간, 경기 강도와 현재 증상·수면·피로를 확인한다. 많이 뛴 선수와 비출전 선수의 요구가 다를 수 있다.\n\n걷기·가벼운 자전거 같은 활동은 선택 가능한 회복 방법이다. 완전 휴식보다 항상 낫거나 일정 출전 시간만 넘으면 모두에게 맞는 방법은 아니다.\n\n비출전 선수도 이전 훈련과 다음 일정을 함께 보고 필요한 자극을 계획한다. “60분” 같은 숫자는 팀 운영의 예시이며 공통 회복 경계가 아니다.",
    ["출전 시간과 실제 상태를 함께 보고 회복·보충 훈련·휴식을 개별 선택한다."],
    "같은 출전 시간이어도 통증이 있는 선수는 평가가 우선이고, 다른 선수는 개별 회복·훈련 계획을 따를 수 있다.",
    "두 선수가 모두 60분을 뛰었다. 다음 날 계획도 같아야 하는가?",
    ["60분은 공통 기준이므로 반드시 같은 활동을 한다","아니다. 실제 경기 노출·증상·피로와 다음 일정까지 함께 확인한다","가벼운 운동은 언제나 휴식보다 낫다","비출전 선수는 상태와 무관하게 최고 강도로 훈련한다"],
    1,
    "출전 시간과 실제 상태를 함께 보고 회복·보충 훈련·휴식을 개별 선택한다."),
  L("f2-recover-2","이동과 잠을 계획에 넣는다","Travel and sleep",
   "원정 이동은 그 자체로 부하다. 늦은 귀가는 잠을 가져가고, 잠을 잃은 다음 날은 판단과 부상 위험에 먼저 나타난다. 이동 시간·도착 시간·다음 날 시작 시간을 일정에 함께 적어 두면 그 주가 달라진다.",
   ["이동은 부하다","늦은 귀가는 다음 날을 가져간다","이동·도착·다음 날 시작을 함께 적는다"],
   {physical:"원정 다음 날 시작 시간을 한 시간 늦춰 보라.",coach:"일정 › 세션 카드의 시간을 원정 다음 날만 다르게 잡아라."},
   "늦은 원정 귀가 다음 날에 가장 먼저 조정할 것은?",["훈련 주제","훈련 시작 시간과 강도","전술 미팅","경기 명단"],1,
   "잠을 못 잔 몸에 평소 시간표를 그대로 씌우면 그 주를 잃는다."),
  L("f2-recover-3","회복 여부는 물어서 확인한다","Ask, then decide",
   "회복이 됐는지는 장비 없이도 꽤 잘 알 수 있다 — 잠, 근육통, 피로감, 기분. 매일 같은 네 가지를 묻고 평소와 다른 사람을 찾는 것이 핵심이다. 팀 평균이 아니라 개인의 평소가 기준이다.",
   ["잠·근육통·피로·기분 네 가지","팀 평균이 아니라 그 사람의 평소","다른 사람을 찾는 도구"],
   {physical:"체크인이 3일 연속 나쁜 선수를 따로 만나라 — 숫자보다 대화가 정확하다.",coach:"팀 › 오늘 훈련 인원에서 '조절'로 옮길 근거로 쓰라."},
   "매일 컨디션 체크인의 목적은?",["팀 평균 관리","평소와 다른 개인을 찾아내는 것","선수 평가","기록 보관"],1,
   "기준은 팀 평균이 아니라 그 사람의 평소다.")
 ]});

mod({id:"f2-measure",track:"physical",level:2,area:"measure",ko:"현장 테스트를 고르고 해석한다",en:"Field tests that mean something",src:["ypd","rpe"],
 flow:"팀 › 평가표의 신체 항목과 IDP › 평가 › 자리 요구가 같은 언어를 쓴다 — 측정은 그 요구를 확인하는 도구다",
 why:"테스트는 많을수록 좋은 것이 아니다. 바꿀 수 있는 것을 재고, 그 변화가 의미 있는지 판단할 수 있어야 한다. 셋이면 충분하고, 셋을 6개월마다 같은 방법으로 재는 것이 열 개를 한 번 재는 것보다 낫다.",
 links:{},
 lessons:[
  L("f2-measure-1",
    "측정 조건과 오차를 함께 관리한다",
    "Same protocol, same conditions",
    "같은 방법·장비·출발 절차·신발·바닥·워밍업과 피로 상태를 기록해야 변화를 해석하기 쉽다.\n\n조건이 달라졌다면 기록을 버리는 대신 차이를 표시하고 직접 비교의 한계를 설명한다. 특정 조건 변화가 모든 선수에게 정확히 0.1초 영향을 준다고 가정하지 않는다.\n\n일정만 고정해도 조건이 모두 같아지지는 않는다. 장비의 정확성·측정자·반복 신뢰도와 당일 상황을 함께 관리한다.",
    ["변경 조건과 오차를 기록하고 같은 조건의 재측정으로 확인한다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "달리기 기록이 좋아졌지만 바닥과 측정 장비가 바뀌었다. 어떻게 하나?",
    ["기록이 좋아졌으니 실제 향상이라고 확정한다","변경 조건과 오차를 기록하고 같은 조건의 재측정으로 확인한다","조건만 같으면 장비 오차는 전혀 없다","날짜가 같으면 모든 조건도 같다고 본다"],
    1,
    "변경 조건과 오차를 기록하고 같은 조건의 재측정으로 확인한다"),
  L("f2-measure-2",
    "작은 차이는 오차와 비교한다",
    "Noise and signal",
    "작은 기록 변화는 실제 변화와 측정 변동이 섞여 있을 수 있다. 작은 차이를 언제나 무의미하다고 하거나 모두 향상이라고 단정하지 않는다.\n\n같은 프로토콜의 반복 신뢰도와 전형적 오차, 선수에게 의미 있는 변화 크기를 함께 검토한다. 장비와 종목마다 기준이 다르다.\n\n여러 시점의 변화와 다른 지표를 확인한다. 세 번 같은 방향이라는 이유만으로 훈련의 인과 효과까지 증명되지는 않는다.",
    ["해당 측정의 오차와 조건, 반복 변화와 실제 의미다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "달리기 기록이 0.02초 빨라졌다. 먼저 확인할 것은?",
    ["작은 차이는 언제나 진짜 차이가 아니다","해당 측정의 오차와 조건, 반복 변화와 실제 의미다","0.02초라도 반드시 능력이 향상된 것이다","세 번 좋아지면 특정 훈련의 효과가 증명된다"],
    1,
    "해당 측정의 오차와 조건, 반복 변화와 실제 의미다"),
  L("f2-measure-3","결과를 선수에게 돌려준다","Give it back",
   "측정 결과가 코치 노트에만 남으면 선수는 왜 뛰었는지 모른다. 자기 기록과 지난번, 그리고 다음에 무엇을 할지 한 줄이 함께 가야 측정이 훈련으로 이어진다.",
   ["기록 + 지난번 + 다음 할 일","코치 노트에만 남기지 않는다","비교 대상은 팀이 아니라 자신"],
   {physical:"결과지를 개인별 한 장으로 만들어 그 날 안에 나눠 줘라.",coach:"IDP › 성장 › 분기 목표에 그 한 줄을 옮겨 적게 하라."},
   "측정 결과를 선수에게 돌려줄 때 반드시 함께 갈 것은?",["팀 순위","지난 기록과 다음에 할 일","다른 선수와의 비교","합격·불합격"],1,
   "다음 행동이 없으면 측정은 그냥 시험이다.")
 ]});

/* ═══════════════════════ 분석 · 2 기본 ═══════════════════════ */
mod({id:"a2-see",track:"analysis",level:2,area:"see",ko:"무엇을 셀지 먼저 정한다",en:"Define before you count",src:["process","fifa","bepro"],
 flow:"팀 › 게임모델 › 국면의 원칙을 그대로 관찰 항목으로 옮긴다 — 우리가 정한 것만 센다",
 why:"세다 보면 셀 수 있는 것만 남는다. 분석은 우리 게임모델이 요구하는 행동을 세는 것이지, 세기 쉬운 것을 세는 것이 아니다.",
 links:{},
 lessons:[
  L("a2-see-1",
    "질문에서 관찰 지표로",
    "From principle to indicator",
    "관찰 항목은 답하려는 질문과 연결돼야 한다. 게임모델 실행, 상대 특성, 경기 결과와 안전 등 목적이 출발점이 될 수 있다.\n\n질문을 눈에 보이는 행동과 셀 수 있는 정의로 바꾼다. 하나의 질문에 여러 지표가 필요할 수 있으며 표준 지표도 목적에 맞으면 유용하다.\n\n정의·기회 수·관찰 범위와 기록 비용을 확인한다. 지표 이름 하나가 팀 원칙을 전부 설명하지 않는다.",
    ["답하려는 질문과의 관련성, 정의·기회 수와 관찰 가능성이다"],
    "골킥의 짧은 첫 패스 횟수와 함께 시도 기회·상대 압박·이후 전진을 살펴 해석한다.",
    "관찰 지표를 고르는 기준은?",
    ["원칙마다 지표는 반드시 하나다","답하려는 질문과의 관련성, 정의·기회 수와 관찰 가능성이다","널리 쓰이는 지표는 우리 팀에 항상 무의미하다","도구에서 나오는 수치는 전부 수집한다"],
    1,
    "답하려는 질문과의 관련성, 정의·기회 수와 관찰 가능성이다"),
  L("a2-see-2","같은 것을 같게 센다","Consistent coding",
   "'전진 패스'가 무엇인지 두 사람이 다르게 세면 두 경기를 비교할 수 없다. 항목마다 포함·제외 기준을 한 줄씩 적어 두면 다음 사람도, 석 달 뒤의 나도 같게 센다.",
   ["항목마다 포함·제외 기준 한 줄","두 사람이 같게 세는지 한 번 맞춰 본다","기준이 없으면 비교가 불가능"],
   {analysis:"같은 5분을 둘이 따로 세어 결과를 맞춰 보라 — 다르면 기준을 고친다.",coach:"분석 담당이 바뀌어도 기준 문서는 남게 하라."},
   "두 분석가의 같은 경기 기록이 크게 다르다. 원인으로 가장 가능성이 큰 것은?",["집중력","항목의 포함·제외 기준이 없다","영상 화질","경기 난이도"],1,
   "정의가 없으면 사람마다 다른 것을 센다."),
  L("a2-see-3","숫자 옆에 장면을 남긴다","Keep the clip",
   "'전진 패스 12회'는 다음 주에 아무 의미가 없다. 그 12회 중 대표 장면 두 개가 함께 있어야 코치와 선수가 같은 것을 떠올린다. 분석의 결과물은 표가 아니라 표 + 장면이다.",
   ["숫자만으로는 아무것도 못 바꾼다","대표 장면 1~2개를 함께 남긴다","표 + 장면이 결과물"],
   {analysis:"항목마다 잘된 장면 하나, 안된 장면 하나를 링크해 둬라.",coach:"보고서를 받을 때 장면이 없으면 다시 요청하라."},
   "분석 보고서에서 숫자와 반드시 함께 가야 하는 것은?",["그래프","대표 장면","상대 통계","선수 평점"],1,
   "장면이 없으면 숫자는 기억되지 않는다.")
 ]});

mod({id:"a2-cause",track:"analysis",level:2,area:"cause",ko:"반복되는 실수에는 구조가 있다",en:"Repeated errors have structure",src:["process","jordet"],
 flow:"IDP › 평가 › 항목별 관찰 문장과 경기 › 국면 평가에 같은 언어로 적는다",
 why:"한 선수가 같은 실수를 반복하면 그것은 그 선수만의 문제가 아닐 때가 많다. 어디서·언제·누구와 반복되는지 모으면 개인 뒤의 구조가 보인다.",
 links:{},
 lessons:[
  L("a2-cause-1",
    "실수 위치는 원인의 단서다",
    "Map the errors",
    "실수가 한 구역에 모이면 그 구역의 지원 거리, 패스 선택지, 상대 압박을 살필 단서가 된다. 위치가 같다고 구조 문제로 확정되지는 않는다.\n\n실수가 흩어져 있어도 공통된 역할 지시나 피로 같은 팀 조건이 원인일 수 있다. 흩어짐을 개인 문제의 증거로 단정하지 않는다.\n\n장면의 위치·상대 압박·동료 지원·선수 행동을 함께 적고 반복 양상을 비교한다. 원인을 가설로 적은 뒤 바꿀 조건과 확인할 결과를 정한다.",
    ["실수 분포는 단서 — 구조·개인 원인은 장면으로 검증"],
    {"현장에서":"지원 구조, 상대 압박, 개별 실행과 반복 조건을 함께 비교한다. 위치 분포만으로 구조·개인 원인을 확정하지 않는다."},
    "같은 구역에서 실수가 반복됐다. 가장 타당한 해석은?",
    ["구조 문제로 확정한다","그 구역의 구조와 실행 조건을 함께 살펴볼 단서다","선수 한 명의 문제로 확정한다","다른 구역은 분석할 필요가 없다"],
    1,
    "지원 구조, 상대 압박, 개별 실행과 반복 조건을 함께 비교한다. 위치 분포만으로 구조·개인 원인을 확정하지 않는다."),
  L("a2-cause-2",
    "몸의 방향이 다음 선택을 정한다",
    "Body shape decides",
    "받기 전 몸 방향은 볼 수 있는 정보와 첫 터치 선택에 영향을 준다. 그러나 닫힌 자세면 전진이 불가능하고 열린 자세면 세 방향이 항상 가능하다는 고정 규칙은 아니다.\n\n등을 지고 받아도 회전·원터치 연결·동료 지원으로 전진할 수 있다. 열린 자세에서도 압박과 패스 각도 때문에 뒤로 주는 선택이 적절할 수 있다.\n\n몸 방향, 사전 확인, 상대 거리, 지원 각도와 받은 공의 질을 함께 비교한다. 소극적인 성격이나 자세 하나로 원인을 확정하지 않는다.\n\n훈련에서는 받는 각도와 압박 조건을 조절해 다른 선택이 가능한지 관찰하고 선수에게 본 정보를 묻는다.",
    ["몸 방향은 선택에 영향을 준다. 압박·정보·지원 각도와 함께 판단한다."],
    {"분석관":"등을 진 공격수가 원터치로 지원 동료에게 연결해 전진한 장면과, 열린 자세지만 압박 때문에 뒤로 준 장면을 함께 본다."},
    "뒤로 패스가 반복되는 선수의 장면을 분석하는 방법은?",
    ["닫고 받았으니 전진은 불가능했다고 확정한다","몸 방향·스캐닝·압박·지원 각도를 함께 비교한다","성격이 소극적이라고 진단한다","열고 받으라고만 반복한다"],
    1,
    "몸 방향은 중요한 단서지만 원인 전체를 설명하지 않는다."),
  L("a2-cause-3",
    "사람을 바꿔도 반복되면 조건을 살핀다",
    "Behind the individual",
    "같은 자리에서 선수를 바꿔도 실수가 반복되면 지원 거리·역할 지시·압박과 같은 공통 조건을 살필 이유가 있다.\n\n그러나 선수 교체만으로 구조가 유일한 원인임이 증명되지는 않는다. 다른 조건도 변하고, 두 선수에게 공통된 실행 어려움이 있을 수 있다.\n\n개인 행동과 팀 지원을 나눠 기록한 뒤 한 조건을 조절하고 여러 장면을 다시 본다. 원인은 확인할 가설로 유지한다.",
    ["공통된 팀 조건과 개인 실행을 함께 검토할 단서다"],
    "성공·실패 장면을 같은 포함 기준으로 모으고 상대·점수·기회 수와 보이지 않는 정보를 함께 적는다. 다음 관찰에서 가설을 다시 확인한다.",
    "선수를 바꿔도 같은 자리에서 실수가 반복됐다. 타당한 결론은?",
    ["구조만이 유일한 원인임이 증명됐다","공통된 팀 조건과 개인 실행을 함께 검토할 단서다","선수는 어떤 원인도 될 수 없다","두 선수의 태도가 나쁘다고 확정한다"],
    1,
    "공통된 팀 조건과 개인 실행을 함께 검토할 단서다")
 ]});

mod({id:"a2-struct",track:"analysis",level:2,area:"struct",ko:"빌드업과 압박은 한 장면의 앞뒤다",en:"Build-up and press are one picture",src:["process","rfef"],
 flow:"경기 › 상대 분석의 국면 보드에 상대 압박을 배치하고, 게임모델 › 공격 조직 원칙과 나란히 본다",
 why:"빌드업을 우리 것만 보면 왜 막혔는지 알 수 없다. 상대의 첫 압박선과 그 뒤에 생기는 그림자를 함께 봐야 전진의 진짜 계기가 보인다.",
 links:{},
 lessons:[
  L("a2-struct-1","커버 섀도 — 막히는 것은 선수가 아니라 선","Cover shadow",
   "압박하러 나오는 선수는 등 뒤에 하나의 패스 길을 함께 지운다. 그래서 눈앞의 상대만 세면 왜 그 패스가 안 갔는지 설명이 안 된다. 누가 어느 길을 지우고 있는가를 그려야 한다.",
   ["압박은 사람과 길을 동시에 막는다","등 뒤에 지워진 길을 그린다","그 길을 되살리는 것이 해법"],
   {analysis:"정지 화면에 지워진 패스 길을 점선으로 그려라.",coach:"그 그림 그대로를 훈련 조건으로 옮겨라."},
   "상대 공격수가 우리 중앙 미드필더 앞에 서서 압박한다. 이때 함께 막히는 것은?",["측면 패스","그 선수 등 뒤로 가는 패스 길","백패스","롱볼"],1,
   "압박은 사람과 길을 함께 지운다."),
  L("a2-struct-2","압박을 부르고 넘긴다","Invite, then break",
   "일부러 낮게, 천천히 잡아 상대를 끌어올린 뒤 그 뒤 공간으로 넘기는 방식은 현대 빌드업의 흔한 형태다. 이때 중요한 것은 배짱이 아니라 타이밍과 지원 각도 — 언제 끌고 언제 넘기는지가 정해져 있어야 한다.",
   ["끌어올린 뒤 그 뒤를 친다","배짱이 아니라 타이밍과 각도","신호가 팀에 공유되어야 한다"],
   {analysis:"성공·실패 장면을 각각 다섯 개 모아 '넘긴 순간'의 차이를 찾아라.",coach:"게임모델 › 공격 조직 원칙에 그 신호를 한 줄로 적어라."},
   "압박 유도 빌드업에서 성패를 가르는 것은?",["골키퍼의 발기술","끌어올린 뒤 넘기는 타이밍과 지원 각도","선수들의 용기","롱볼 정확도"],1,
   "언제 넘기는지가 정해져 있지 않으면 위험만 남는다."),
  L("a2-struct-3",
    "세 번째 선수",
    "The third man",
    "두 사람 사이만 보면 막혀 있는데, 세 번째 선수를 거치면 열린다.\n\n이유는 앞 절에서 본 커버 섀도에 있다. 압박하는 선수는 하나의 길을 지운다. 그런데 다른 사람을 거쳐 가면 그 길을 쓰지 않고 도달할 수 있다.\n\n그래서 세 번째 선수(서드맨, third man)의 핵심은 이 한 줄이다 — 받는 사람이 아니라 그 다음 받는 사람을 미리 보는 것.\n\n패스를 주는 선수가 A에게 준다고 생각하면 그 패스는 A에서 끝난다. A를 거쳐 B에게 간다고 생각하면, 그 순간부터 B가 언제 뛰어야 하는지가 보인다.\n\n그리고 이 장면이 나온다는 것에는 진단적 의미가 있다. 세 명이 동시에 같은 그림을 봐야 나오는 플레이라, 이 장면이 나오면 팀이 같은 그림을 공유하고 있다는 뜻이다.\n\n반대로 아무리 좋은 선수가 있어도 이 장면이 안 나왔다면 기회·압박·연결 조건과 팀의 이해를 함께 확인한다.\n\n훈련으로 만들기도 쉽다 — 론도에 '세 번째 선수에게 가면 2점' 같은 조건을 걸면 저절로 찾기 시작한다.",
    ["둘 사이가 막히면 셋으로 푼다 · 다음 받는 사람을 미리 본다."],
    "론도에 '세 번째 선수에게 가면 2점' 같은 조건을 걸어 보라. 말로 설명하기 어려운 개념이 조건 하나로 나온다. 우리 팀 경기에서 세 번째 선수 장면이 몇 번 나오는지 세어 보라. 0에 가깝다면 공유가 아직 안 된 것이다.",
    "'세 번째 선수' 개념의 핵심은?",
    ["패스를 두 번 이상 연결하는 것","받는 사람이 아니라 그다음 받는 사람을 미리 보는 것","세 명이 삼각형을 만드는 것","측면을 거쳐 중앙으로 가는 것"],
    1,
    "다음의 다음을 보는 것이 이 개념의 전부다.")
 ]});

mod({id:"a2-oppo",track:"analysis",level:2,area:"oppo",ko:"상대 보고서 한 장",en:"The one-page report",src:["process","fa"],
 flow:"경기 › 경기 준비 › 상대 분석 카드와 게임플랜 네 줄 — 보고서의 결론이 그대로 옮겨진다",
 why:"보고서는 길수록 좋은 것이 아니라 선수가 기억하는 만큼만 값을 한다. 한 장에 담기지 않으면 아직 정리가 안 된 것이다.",
 links:{},
 lessons:[
  L("a2-oppo-1","한 장의 구조","What goes on the page",
   "상대의 기본 형태와 두 전환에서의 습관, 우리가 막을 것 하나, 노릴 곳 하나, 위험 하나, 그리고 세트피스. 이 여섯 칸이면 한 장이 채워지고, 그 이상은 다른 문서로 뺀다.",
   ["형태 · 두 전환 습관 · 막을 것 · 노릴 곳 · 위험 · 세트피스","한 장을 넘기면 다른 문서로","선수용과 코치용을 나눈다"],
   {analysis:"보고서 양식을 한 장으로 고정하고 매번 같은 자리에 같은 항목을 넣어라.",coach:"미팅에서 이 여섯 칸 순서대로 말하라 — 순서가 같으면 선수가 예측한다."},
   "상대 보고서가 길어질 때 옳은 조치는?",["그대로 전달","선수용 한 장과 코치용 상세를 나눈다","항목을 지운다","미팅 시간을 늘린다"],1,
   "전달용과 근거용은 다른 문서다."),
  L("a2-oppo-2",
    "세트피스는 따로 본다",
    "Set pieces separately",
    "세트피스는 흐름과 별개로 반복되고, 준비한 루틴이 상당 부분 그대로 나온다.\n\n이 성질 때문에 세트피스는 상대 분석에서 수익률이 높은 항목이다. 흐름 속 플레이는 상대·날씨·컨디션에 따라 달라지지만, 세트피스는 연습한 루틴이 크게 바뀌지 않고 나온다.\n\n두 경기에서도 단서를 얻을 수 있지만 출현 기회가 적으면 더 많은 표본이 필요하다.\n\n볼 것도 정해져 있다.\n\n- 누가 어디에 서는가\n\n- 어디로 뛰는가(첫 움직임 방향)\n\n특히 첫 움직임이 반복성이 높다. 루틴의 시작 동작이라 거의 매번 같다. 그리고 그것만 알아도 수비 담당이 한 발 먼저 움직일 수 있다.\n\n그런데 이 분석이 쓸모 있으려면 조건이 하나 있다 — 우리 쪽에 받을 사람이 있어야 한다.\n\n우리 세트피스 담당을 한 명 정하는 것이 그 조건이다. 담당이 없으면 상대 분석이 아무리 좋아도 매번 즉흥이 되고, 즉흥은 준비된 상대를 못 이긴다.",
    ["세트피스는 흐름과 별개로 반복된다 · 서는 자리와 첫 움직임 · 두 경기면 보인다."],
    "우리 세트피스 담당을 한 명 정해라 — 없으면 매번 즉흥이 된다. 분석보다 담당이 먼저다. 다음 상대의 코너킥 두 개를 보고 첫 움직임 방향을 그려 보라. 두 번이 같으면 그것이 루틴이다.",
    "상대 세트피스 분석에서 가장 반복성이 높은 정보는?",
    ["키커의 발 각도","서는 자리와 첫 움직임 방향","득점 위치","공의 궤적"],
    1,
    "세트피스는 준비된 루틴이 반복된다. 루틴의 시작 동작은 거의 매번 같다."),
  L("a2-oppo-3",
    "원칙을 유지할 때와 조정할 때",
    "How far we adapt",
    "팀 원칙은 반복 학습의 기준이지만, 어떤 상황에도 고칠 수 없는 약속은 아니다. 상대·선수 가용성·안전과 지속적인 경기 증거를 함께 본다.\n\n한 장면만으로 모델을 뒤집지는 않는다. 우선 실행과 조건을 확인하고, 필요하면 시즌 중에도 원칙과 역할을 수정할 수 있다.\n\n바꾼 이유, 유지할 부분과 새 행동을 선수에게 설명하고 재관찰한다. 변화 자체보다 근거와 전달 과정이 중요하다.",
    ["반복 근거와 선수·경기 조건에 따라 수정하고 이유와 새 역할을 공유할 수 있다"],
    "성공·실패 장면을 같은 포함 기준으로 모으고 상대·점수·기회 수와 보이지 않는 정보를 함께 적는다. 다음 관찰에서 가설을 다시 확인한다.",
    "시즌 중에도 팀 원칙을 바꿀 수 있는가?",
    ["원칙은 시즌 사이에만 바꿀 수 있다","반복 근거와 선수·경기 조건에 따라 수정하고 이유와 새 역할을 공유할 수 있다","상대에 맞춘 변화는 언제나 항복이다","한 번 실패하면 원칙을 모두 바꾼다"],
    1,
    "반복 근거와 선수·경기 조건에 따라 수정하고 이유와 새 역할을 공유할 수 있다")
 ]});

mod({id:"a2-toTrain",track:"analysis",level:2,area:"toTrain",ko:"한 주의 훈련으로 옮긴다",en:"Into the training week",src:["process","knvb"],
 flow:"일정 › 주간의 세션 주제와 보관함의 훈련이 분석 결론에서 나온다 — 주제 배분이 그 증거다",
 why:"분석 하나가 훈련 하나로 끝나면 바뀌지 않는다. 같은 문제를 한 주 동안 다른 형태로 세 번 만나야 몸에 남는다.",
 links:{},
 lessons:[
  L("a2-toTrain-1",
    "주간의 초점과 반복 기회",
    "One problem a week",
    "중요한 문제를 좁히면 여러 세션에서 관련 행동을 반복할 기회를 만들기 쉽다. 다만 한 주에 한 문제만 다뤄야 한다는 법칙은 아니다.\n\n여러 목표를 함께 다룰 때는 선수의 현재 수준·시간·회복을 보고 우선순위와 반복 기회를 확보한다. 한 번의 경험이 전부 사라지는 것도, 세 번이면 반드시 바뀌는 것도 아니다.\n\n주제 배분은 계획을 보는 자료이며 실제 행동 변화는 훈련과 경기 장면에서 다시 확인한다.",
    ["중요한 행동의 반복·피드백 기회를 확보하기 위해서다"],
    "전진 패스 뒤 지원을 이번 주 우선 행동으로 정하고 서로 다른 게임에서 쓸 기회를 만든다.",
    "주간의 초점을 좁히는 실용적인 이유는?",
    ["세 번 반복하면 반드시 습득되기 때문이다","중요한 행동의 반복·피드백 기회를 확보하기 위해서다","다른 목표는 어떤 상황에서도 함께 다룰 수 없기 때문이다","주제 배분이 한쪽이면 학습이 증명되기 때문이다"],
    1,
    "중요한 행동의 반복·피드백 기회를 확보하기 위해서다"),
  L("a2-toTrain-2",
    "같은 문제, 다른 형태",
    "Same problem, three forms",
    "같은 문제를 다루되 형태는 바꾼다. 세 단계로 만난다.\n\n- 좁은 형태 — 요소를 익힌다\n\n- 중간 형태 — 다른 것과 붙인다\n\n- 경기 형태 — 확인한다\n\n순서에 이유가 있다. 좁은 곳에서는 반복 밀도가 높아 요소를 빨리 익힌다. 중간에서는 맥락이 붙는다. 그리고 경기 형태에서 실제로 나오는지를 본다.\n\n마지막은 언제나 경기에 가깝게 두는 것이 핵심이다. 좁은 형태로 끝내면 그 형태에서만 되는 것을 배우고 끝난다(1부의 대표성).\n\n그리고 판정 기준이 아주 명확해진다 — 세 번째에서 안 나오면 아직 안 된 것이다.\n\n좁은 형태에서 100% 성공했어도, 경기 형태에서 안 나오면 기회와 압박 조건을 확인하고 이후의 유지·전이도 점검한다. 이 기준이 없으면 코치는 \"오늘 잘했다\"로 마무리하고, 다음 경기에 아무것도 안 나오는 것을 보게 된다.\n\n그래서 세션 마지막 게임에서 그 행동이 나왔는지만 보면 된다. 그것이 그 날의 답이다.",
    ["좁게 → 중간 → 경기 형태 · 마지막은 언제나 경기에 가깝게."],
    "세션 마지막 게임에서 그 행동이 나왔는지만 보라 — 그게 그 날의 답이다. 앞의 두 형태가 아무리 잘돼도 마지막이 답이다. 이번 주 세션의 마지막 게임에서 목표 행동이 몇 번 나왔는지 세어 보라. 숫자가 그 주의 성적이다.",
    "훈련 세 형태 중 마지막이 경기 형태여야 하는 이유는?",
    ["선수들이 재미있어하니까","경기에서 나오는지 확인하는 자리이기 때문","체력 부하를 마무리하려고","경기 감각을 유지하려고"],
    1,
    "확인하지 않으면 훈련했다는 사실만 남는다."),
  L("a2-toTrain-3",
    "다음 경기에서 다시 본다",
    "Check it in the match",
    "PROCESS의 마지막 단계는 재관찰이다.\n\n이번 주에 다룬 그 행동이 다음 경기에서 몇 번 나왔는지와 실행 기회를 함께 보면 훈련 효과를 검토할 단서를 얻는다. 상대와 조건의 차이도 확인한다.\n\n이 단계가 있어야 순환이 닫힌다.\n\n- 경기에서 문제를 본다\n\n- 가설을 세운다\n\n- 훈련한다\n\n- 다음 경기에서 다시 센다 ← 여기\n\n그리고 결과에 따라 다음이 갈린다.\n\n- 나왔으면 → 다음 문제로\n\n- 안 나왔으면 → 가설부터 다시\n\n두 번째가 중요하다. 안 나왔을 때 훈련을 더 하는 것이 첫 반응이기 쉬운데, 먼저 볼 것은 가설과 대표성이다(1부 a1-toTrain-2·3에서 본 것과 같다). 가설이 틀렸으면 훈련을 열 번 더 해도 안 나온다.\n\n재관찰은 기록이 있어야 가능하다. 이 앱의 경기 › 국면 평가에 그 항목을 남기면, 다음 주와 같은 기준으로 비교할 수 있다.",
    ["다음 경기에서 그 행동을 센다 · 나왔으면 다음 문제로, 안 나왔으면 가설부터."],
    "경기 › 국면 평가에 그 항목을 남겨 다음 주와 비교하라. 기록이 없으면 재관찰은 기억 대결이 되고, 기억은 대개 낙관적이다. 지난주 훈련 주제를 다음 경기에서 몇 번 봤는지 세어 보라. 세어 본 적이 없다면 그 순환은 아직 안 닫힌 것이다.",
    "훈련한 행동이 다음 경기에 안 나왔다. 가장 먼저 다시 볼 것은?",
    ["훈련 반복 횟수","원인 가설과 훈련의 대표성","선수의 이해도","상대의 대응"],
    1,
    "행동이 안 나오면 훈련보다 가설을 먼저 의심한다.")
 ]});

mod({id:"a2-report",track:"analysis",level:2,area:"report",ko:"개인 클립과 팀 미팅을 나눈다",en:"Individual clips, team meeting",src:["process","uefa","bepro"],
 flow:"경기 › 경기 리뷰의 팀 리뷰와 선수별 개인 피드백 — 두 곳이 서로 다른 일을 한다",
 why:"팀 미팅에서 개인을 지적하면 그 선수는 배우지 않고 방어한다. 팀에는 구조를, 개인에게는 행동을 — 자리를 나누는 것만으로 전달이 달라진다.",
 links:{},
 lessons:[
  L("a2-report-1","팀에는 구조, 개인에게는 행동","Structure to the team",
   "팀 미팅에서는 '우리가 어떻게 서 있었나'를 다루고, 개인 피드백에서는 '너는 그때 무엇을 볼 수 있었나'를 다룬다. 이 둘을 섞으면 팀은 지루하고 개인은 창피하다.",
   ["팀 = 구조 · 개인 = 행동","섞으면 둘 다 실패한다","개인 지적은 팀 앞에서 하지 않는다"],
   {analysis:"클립을 팀용·개인용 두 폴더로 나눠 만들어라.",coach:"개인 피드백은 짧게, 따로, 그 날 안에."},
   "팀 미팅에서 개인 실수를 지적하면?",["경각심이 생긴다","그 선수는 방어하고 학습이 멈춘다","팀이 배운다","효율적이다"],1,
   "방어 상태에서는 배우지 못한다."),
  L("a2-report-2","질문으로 넘긴다","Ask, don't tell",
   "장면을 보여 주고 답을 말해 주면 선수는 그 답만 기억한다. '그때 뭐가 보였어?', '다른 방법이 있었을까?'로 넘기면 스스로 그림을 만든다. 시간이 조금 더 걸리지만 남는 것이 다르다.",
   ["보여 주고 묻는다","답을 먼저 말하지 않는다","스스로 만든 그림이 남는다"],
   {analysis:"클립마다 질문 한 줄을 함께 적어 코치에게 넘겨라.",coach:"미팅에서 첫 30초는 코치가 말하지 않는다고 정해 보라."},
   "영상 미팅에서 코치가 답을 먼저 말하면?",["시간이 절약된다","선수는 그 답만 기억하고 스스로 보는 힘이 안 는다","이해가 빠르다","권위가 선다"],1,
   "스스로 만든 답이 오래 남는다."),
  L("a2-report-3","다음에 무엇을 볼지로 끝낸다","End with what to watch",
   "미팅의 마지막 문장은 정리가 아니라 다음 과제여야 한다. '다음 경기에서 이것 하나만 다시 보자.' 그러면 다음 경기의 관찰 항목이 저절로 정해지고, 그것이 PROCESS 의 재관찰이다.",
   ["마지막은 정리가 아니라 다음 과제","다음 관찰 항목이 거기서 나온다","한 번에 하나"],
   {analysis:"미팅 끝의 그 한 줄을 다음 주 관찰 항목 목록의 첫 줄로 옮겨라.",coach:"경기 리뷰 › 다음 행동 칸에 그 한 줄을 적어라."},
   "영상 미팅을 끝내는 가장 좋은 방법은?",["요약 정리","다음 경기에 다시 볼 것 하나를 정하는 것","질문 받기","격려"],1,
   "다음에 볼 것이 정해져야 순환이 이어진다.")
 ]});

/* ═══════════════════════ AT · 2 기본 ═══════════════════════
   ⚠ 교육용 정리다. 진단·치료 지시가 아니며 판단이 필요한 순간에는 의료인에게 보낸다. */
mod({id:"t2-risk",track:"at",level:2,area:"risk",ko:"위험을 미리 나눠 둔다",en:"Screening and risk groups",src:["fifamed","ypd","rpe"],
 flow:"팀 › 선수단의 상태와 일정의 세션 강도가 만나는 곳 — 위험군은 그 주 시작 전에 정해 둔다",
 why:"모두를 똑같이 보면 아무도 제대로 못 본다. 위험이 높은 소수를 주 시작 전에 골라 두면 그 주의 눈이 그쪽으로 간다.",
 links:{},
 lessons:[
  L("t2-risk-1",
    "필요한 선수 모두에게 확인 계획을 세운다",
    "Three groups",
    "최근 복귀, 빠른 성장, 이전 부상과 현재 증상은 추가 확인의 단서다. 이 셋만으로 모든 위험을 설명할 수 없고, “복귀 4주”를 공통 경계로 쓰지도 않는다.\n\n명단의 인원수를 맞추려고 필요한 선수를 제외하지 않는다. 확인할 선수가 많으면 담당자·관찰 방법·훈련 계획을 조정한다. 새로운 통증이나 급격한 기능 변화도 놓치지 않는다.\n\n누가 무엇을 언제 확인할지 적고 매 세션 현재 반응을 갱신한다. “조절” 표시는 그 결정을 전달하는 수단이며 그 자체가 의학적 위험 등급은 아니다.",
    ["관찰 대상 수를 제한하지 않고 필요에 맞춰 담당자·확인 주기·참여 계획을 정한다."],
    "여러 선수가 불편함을 보고하면 인원을 삭제하는 대신 훈련을 조정하고 스태프별 확인 대상을 나눠 기록한다.",
    "추가 관찰이 필요한 선수가 팀의 절반이다. 어떻게 하는가?",
    ["명단을 세 명으로 줄인다","필요한 선수를 모두 포함하고 확인·훈련 운영 방식을 조정한다","최근 부상 이력이 없는 선수의 증상은 무시한다","명단이 길므로 관찰을 중단한다"],
    1,
    "관찰 대상 수를 제한하지 않고 필요에 맞춰 담당자·확인 주기·참여 계획을 정한다."),
  L("t2-risk-2",
    "간단한 검사는 현재 기능을 확인하는 도구",
    "A short screen",
    "균형, 한 발 동작, 발목 움직임 범위는 현재 기능을 살피는 자료가 될 수 있다. 통증이나 제한이 있으면 검사를 밀어붙이지 않고 적절한 평가로 연결한다.\n\n좌우 차이에는 원래의 특성, 이전 손상, 측정 오차가 섞인다. 차이가 큰 쪽이 다음에 다친다고 예측하거나, 대칭이라는 이유로 안전하다고 보장하지 않는다.\n\n검사의 목적과 조건을 기록하고 평소 자료·증상·과제 수행과 함께 해석한다. 선별검사 점수 하나로 진단하거나 출전 여부를 결정하지 않는다.",
    ["기능 검사와 좌우 차이는 참고 정보 — 부상 예측·진단·복귀 허가를 대신하지 않는다."],
    "지난 측정과 같은 조건인지 확인한 뒤 차이가 반복되는지 살핀다. 통증이 있으면 검사 점수보다 증상에 먼저 대응한다.",
    "한 발 균형 검사에서 좌우 차이가 나타났다. 옳은 해석은?",
    ["차이가 큰 쪽은 다음 경기에서 반드시 다친다","측정 조건·평소 차이·증상과 다른 기능 자료를 함께 확인한다","차이만으로 부상명을 진단한다","좌우가 같아질 때까지 모든 선수를 무기한 제외한다"],
    1,
    "기능 검사와 좌우 차이는 참고 정보 — 부상 예측·진단·복귀 허가를 대신하지 않는다."),
  L("t2-risk-3","부하와 부상은 사람마다 다르게 만난다","Load meets the person",
   "같은 부하도 준비된 몸에는 자극이고 준비 안 된 몸에는 손상이다. 그래서 부하만 보지 말고 그 사람의 최근 몇 주를 함께 본다 — 얼마나 쌓았고, 얼마나 쉬었고, 지금 어떤 상태인지.",
   ["같은 부하도 사람마다 다르다","최근 몇 주를 함께 본다","부하 숫자 하나로 판단하지 않는다"],
   {at:"위험군 선수만 주간 부하를 따로 그려 보라.",coach:"부하가 높다고 무조건 빼지 말고, 스태프와 그 선수의 최근 몇 주를 같이 보라."},
   "같은 훈련 부하가 선수마다 다르게 작용하는 주된 이유는?",["체중","최근 몇 주 동안 쌓아 온 준비 상태","포지션","나이"],1,
   "몸은 오늘이 아니라 지난 몇 주를 기억한다.")
 ]});

mod({id:"t2-emerg",track:"at",level:2,area:"emerg",ko:"응급 계획을 종이로 만든다",en:"Write the emergency plan",src:["fifamed","concussion"],
 flow:"팀 › 설정과 경기 › 경기 준비에 연락처·동선을 붙여 두면 원정에서도 같은 종이를 본다",
 why:"응급 상황에서 사람은 아는 것의 절반도 못 한다. 미리 적어 둔 종이와 정해진 역할만이 그때 작동한다.",
 links:{},
 lessons:[
  L("t2-emerg-1","역할을 이름으로 정해 둔다","Names, not roles",
   "'누가 119 부르지?'를 그 자리에서 묻지 않으려면 이름으로 정해 둬야 한다 — 부르는 사람, 문 여는 사람, 다른 선수를 물리는 사람, 보호자에게 연락하는 사람. 네 명이면 대부분 돌아간다.",
   ["부르는 사람 · 문 여는 사람 · 선수를 물리는 사람 · 보호자 연락","이름으로 적는다","경기마다 그 자리에 있는 사람으로"],
   {at:"홈·원정용 응급 카드를 각각 만들어 가방과 벤치에 둬라.",coach:"시즌 첫 미팅에서 이 네 역할을 정해 공유하라."},
   "응급 계획에서 가장 자주 빠지는 것은?",["병원 위치","역할을 이름으로 정해 두는 것","구급함","연락처"],1,
   "역할이 사람 이름에 붙어 있지 않으면 그 자리에서 아무도 움직이지 않는다."),
  L("t2-emerg-2",
    "더위 속 훈련과 열질환에 대응한다",
    "Heat and hydration",
    "더위 속 어지럼·메스꺼움·이상 피로가 나타나면 활동을 멈추고 상태를 확인한다. 혼란, 비정상 행동, 쓰러짐은 열사병을 의심해야 할 응급 신호다.\n\n응급 신호가 있으면 즉시 119를 요청하며 신속한 냉각을 시작한다. 안전한 냉수 침수 등을 준비된 인력이 시행하고 기도와 호흡을 살핀다. 의식이 흐린 사람에게 물을 억지로 먹이지 않는다.\n\n“먼저 냉각”은 준비된 현장 의료 체계에서 이송과 조율하는 원칙이다. 적절한 인력·장비 없이 이송을 임의로 지연하지 말고 119 지시에 따르며 가능한 냉각을 이어간다.\n\n예방은 시간대뿐 아니라 열환경, 적응 상태, 휴식·수분 접근, 강도·시간 조절을 함께 다룬다. 위험이 크면 취소·연기한다. 물은 강제로 과량 마시게 하지 않는다.",
    ["혼란·쓰러짐은 119와 신속한 냉각. 예방은 시간·환경·적응·휴식·수분을 함께 조절."],
    "현장 냉각 담당자와 119 연락 담당자가 동시에 움직인다. 냉각 방법과 이송은 현장 의료진·구급대와 조율한다.",
    "더운 훈련 중 선수가 혼란스러워하며 쓰러졌다. 먼저 할 일은?",
    ["물을 억지로 많이 먹인다","119를 요청하며 안전한 신속 냉각과 호흡 확인을 시작한다","훈련 시간만 옮기고 그대로 둔다","장비가 준비될 때까지 응급 연락을 미룬다"],
    1,
    "혼란·쓰러짐은 119와 신속한 냉각. 예방은 시간·환경·적응·휴식·수분을 함께 조절."),
  L("t2-emerg-3",
    "머리 부상 뒤 단계적 복귀",
    "Graded return after head injury",
    "뇌진탕이 의심되면 경기에서 제외하고 의료진의 평가를 받는다. 스포츠 복귀는 증상과 검사 결과에 따라 의료진이 단계적으로 결정한다.\n\nAmsterdam 합의문의 단계는 ① 증상이 허용하는 일상 활동 → ② 가벼운·중등도 유산소 → ③ 개인 종목 운동 → ④ 비접촉 훈련 → ⑤ 완전 접촉 훈련 → ⑥ 경기로 진행한다.\n\n초기에는 상대적 휴식 후 허용 범위의 활동을 시작한다. 각 단계는 통상 최소 24시간이지만 이는 최단 진행 간격이지 “일주일이면 회복”이라는 복귀 기한이 아니다.\n\n충돌·낙상·머리 재충격 위험이 있는 단계에 들어가기 전에 의료적 승인이 필요하다. 3단계 개인 운동에도 우발적 충격 위험이 있으면 그 전에 확인한다. 이후 단계로 가기 전 운동 중·후 증상과 임상 소견의 회복을 평가한다.\n\n초기 1~3단계에서 허용되는 가볍고 짧은 증상 악화를 넘으면 중단하고 의료진과 다음 진행을 정한다. 4~6단계에서 증상이 재발하면 이전 활동 단계로 돌아가 재평가한다. 선수나 코치가 임의로 단계를 올리지 않는다.\n\n학생 선수는 학업 복귀와 운동 복귀를 함께 관리한다. 제한 없는 스포츠 복귀 전에는 학업 복귀를 마쳐야 한다. 지역·대회의 더 엄격한 규정도 확인한다.",
    ["단계별 최소 시간은 복귀 기한이 아니다. 재충격 위험 단계 전 의료 승인 · 제한 없는 운동 전 학업 복귀."],
    {"현장에서":"“비접촉”이라는 훈련 이름만 보고 허용하지 않는다. 선수 간 충돌이나 낙상 가능성을 의료진과 확인한다.","스스로":"각 단계의 활동·증상·의료진 확인을 기록하고, 경기 날짜가 정해져 있어도 기준을 건너뛰지 않는다."},
    "3단계 개인 종목 운동에도 우발적 머리 충격 위험이 있다면?",
    ["접촉 훈련인 5단계 전까지 확인을 미룬다","그 활동에 들어가기 전에 의료적 승인을 확인한다","선수가 괜찮다고 하면 진행한다","24시간이 지났으면 자동으로 진행한다"],
    1,
    "활동 이름보다 실제 재충격 위험이 중요하다. 위험이 있으면 3단계 전에도 의료적 승인이 필요하다.")
 ]});

mod({id:"t2-assess",track:"at",level:2,area:"assess",ko:"자주 만나는 부위를 안다",en:"The common ones",src:["fifamed"],
 flow:"팀 › 선수단 선수 카드의 상태·메모에 부위와 경과를 남긴다 — 다음 시즌의 예방 자료가 된다",
 why:"축구에서 흔한 부위는 정해져 있다. 자주 만나는 몇 가지에 대해 무엇을 보고 언제 넘기는지만 알아도 현장의 판단이 크게 안정된다.",
 links:{},
 lessons:[
  L("t2-assess-1","발목 — 가장 흔한 인대 손상","Ankle",
   "안쪽으로 접질리는 형태가 가장 흔하다. 붓기 위치, 체중을 실을 수 있는지, 특정 뼈 부위를 눌렀을 때 아픈지를 본다. 체중을 못 싣거나 뼈 부위 압통이 뚜렷하면 넘긴다. 복귀 전 균형과 방향 전환이 반드시 회복되어야 재발이 준다.",
   ["체중을 실을 수 있는가","뼈 부위 압통이 있는가","복귀 전 균형·방향 전환 회복"],
   {at:"발목 복귀 전 한 발 균형 좌우 비교를 마지막 관문으로 두라.",coach:"발목은 가볍게 보기 쉽지만 재발이 많은 부위다."},
   "발목 손상 복귀 전 반드시 회복되어야 하는 것은?",["근력만","균형과 방향 전환","달리기 속도","점프 높이"],1,
   "균형이 안 돌아오면 같은 부위를 다시 접질린다."),
  L("t2-assess-2",
    "햄스트링 통증 — 평가와 단계적 복귀",
    "Hamstring",
    "전력 질주 중 뒤쪽 허벅지 통증은 햄스트링 손상 등을 의심할 단서다. 다른 발생 양상도 있으므로 현장 관찰만으로 진단하지 않는다.\n\n활동을 멈추고 발생 상황·걷기와 일상의 불편을 의료 담당자에게 전달한다. 자격이 없는 사람이 통증을 확인하려고 강한 스트레칭이나 힘 검사를 시키지 않는다.\n\n통증 감소만으로 최고 속도와 경기 요구에 준비됐다고 판단하지 않는다. 의료·기능 평가와 단계적 운동, 충분한 교체 준비와 이후 반응을 함께 확인한다.",
    ["활동을 멈추고 증상·발생 상황을 기록해 의료 평가로 연결한다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "달리다 뒤 허벅지를 잡고 멈춘 선수에게 적절한 대응은?",
    ["강하게 늘려 통증이 나는지 시험한다","활동을 멈추고 증상·발생 상황을 기록해 의료 평가로 연결한다","천천히 뛰면 괜찮으니 즉시 전력 질주를 시킨다","통증이 줄면 평가 없이 정상 경기로 복귀시킨다"],
    1,
    "활동을 멈추고 증상·발생 상황을 기록해 의료 평가로 연결한다"),
  L("t2-assess-3",
    "무릎 손상 — 활동 중단과 평가 신호",
    "Knee red flags",
    "무릎을 다친 뒤 심한 통증·빠른 부종·변형·체중을 싣기 어려움·잠김이나 불안정감이 있으면 활동을 중단하고 신속히 의료 평가를 받는다. 특정 신호가 두 개 이상일 때만 의뢰하는 규칙은 없다.\n\n걸을 수 있다는 이유로 큰 손상을 배제하지 않는다. 비전문가가 관절을 억지로 움직이거나 현장 검사로 진단하려 하지 않는다.",
    ["활동을 중단하고 신속히 의료 평가를 받게 한다"],
    "비틀린 뒤 무릎이 붓는 선수를 뛰게 하지 않고 손상 시점과 관찰한 증상을 담당자에게 전달한다.",
    "손상 뒤 무릎이 크게 붓고 체중을 싣기 어렵다. 적절한 대응은?",
    ["다른 신호가 두 개 더 생길 때까지 기다린다","활동을 중단하고 신속히 의료 평가를 받게 한다","걸음을 조금 걸으면 복귀시킨다","무릎을 강제로 굽혀 확인한다"],
    1,
    "활동을 중단하고 신속히 의료 평가를 받게 한다")
 ]});

mod({id:"t2-rehab",track:"at",level:2,area:"rehab",ko:"단계마다 통과 조건을 적는다",en:"Write the criteria",src:["fifamed","ypd"],
 flow:"팀 › 선수단 상태(재활 → 조절 → 정상)가 곧 단계 표시다 — 그 옆 메모에 통과 조건을 적는다",
 why:"재활이 흔들리는 이유는 대부분 조건이 적혀 있지 않아서다. 적혀 있으면 코치도 선수도 보호자도 같은 것을 기다린다.",
 links:{},
 lessons:[
  L("t2-rehab-1",
    "재활 단계에는 개별 통과 기준이 필요하다",
    "Four stages",
    "재활을 증상 관리, 기본 기능, 종목 동작, 팀 훈련으로 나누면 현재 목표를 설명하기 쉽다. 실제 단계와 진행 기준은 부상과 선수에 따라 의료진이 정한다.\n\n통과 기준은 어떤 동작을 어떤 조건에서 평가하는지 분명히 적는다. 한 발 균형 30초나 최고 속도 80%는 문장을 설명하기 위한 예시이며 모든 손상의 복귀 기준이 아니다.\n\n동작 수행뿐 아니라 증상, 운동 뒤 반응, 조직 회복과 심리적 준비를 함께 확인한다. 숫자 한 개를 채웠다고 다음 단계로 자동 이동하지 않는다.",
    ["단계 기준은 부상별로 정하고 수행·증상·운동 후 반응을 함께 확인한다."],
    "계획서에는 “평가 동작·허용 범위·다음날 확인·다시 평가할 조건”을 적고 담당 의료진과 맞춘다.",
    "한 발 균형 30초를 마쳤다. 모든 부상에서 다음 단계로 가도 되는가?",
    ["30초는 모든 부상의 공통 기준이다","아니다. 의료진이 정한 부상별 기준과 운동 후 반응을 함께 본다","통증만 참으면 넘어간다","정해진 날짜만 기다리면 기능 확인은 필요 없다"],
    1,
    "단계 기준은 부상별로 정하고 수행·증상·운동 후 반응을 함께 확인한다."),
  L("t2-rehab-2",
    "좌우 비교에 평소 능력과 경기 요구를 더한다",
    "Close the side-to-side gap",
    "부상과 활동 감소 뒤에는 힘과 기능이 달라질 수 있다. 좌우 비교는 참고가 되지만 반대쪽도 약해졌거나 원래 비대칭일 수 있다.\n\n대칭만으로 충분한 회복을 판정할 수 없다. 부상 전 기록, 절대적 능력, 동작의 질, 종목 요구와 증상을 함께 확인한다. 차이가 있다고 재발을 확정하지도 않는다.\n\n어떤 검사와 기준을 쓸지는 손상에 따라 달라진다. 통증을 유발하는 점프나 힘 검사를 현장에서 임의로 시키지 않고 의료진의 계획을 따른다.",
    ["대칭은 복귀의 충분조건이 아니다 — 평소 능력·절대 수행·종목 요구도 함께."],
    "좌우 비율이 좋아져도 양쪽 힘이 모두 줄었을 수 있어 이전 기록과 현재 경기 과제를 함께 확인한다.",
    "재활 뒤 양쪽 점프 거리가 같지만 양쪽 모두 부상 전보다 낮다. 옳은 해석은?",
    ["양쪽이 같으므로 즉시 제한 없이 복귀한다","대칭만으로 회복을 확정하지 않고 전체 능력과 경기 요구를 평가한다","반대쪽은 언제나 정상 기준이다","차이가 없으므로 추가 평가할 내용이 없다"],
    1,
    "대칭은 복귀의 충분조건이 아니다 — 평소 능력·절대 수행·종목 요구도 함께."),
  L("t2-rehab-3",
    "재활 중 소속감과 선택권",
    "Keep them in the game",
    "부상 선수도 팀과의 관계를 유지할 기회가 필요할 수 있다. 다만 모든 모임·원정 참여가 회복에 도움이 되는 것은 아니다.\n\n선수의 의사·치료 일정·이동 부담과 의료 제한을 확인하고 미팅 참여, 원격 연락, 동료와의 대화 등 가능한 방식을 함께 정한다.\n\n쉬고 싶다는 선택을 의지 부족으로 보지 않는다. 역할을 맡길 때도 강요하지 않고 부담과 도움이 되는지를 다시 묻는다.",
    ["선수의 의사와 치료·회복 조건에 맞는 참여 방식을 함께 고른다"],
    "원정 이동이 힘든 선수에게 참여 여부를 묻고 짧은 영상 미팅이나 동료 연락 중 편한 방식을 고르게 한다.",
    "재활 중인 선수의 팀 참여는 어떻게 정하나?",
    ["모든 원정에 반드시 동행시킨다","선수의 의사와 치료·회복 조건에 맞는 참여 방식을 함께 고른다","혼자 쉬는 시간을 전혀 허용하지 않는다","부상 기간에는 팀 연락을 끊는다"],
    1,
    "선수의 의사와 치료·회복 조건에 맞는 참여 방식을 함께 고른다")
 ]});

mod({id:"t2-rtp",track:"at",level:2,area:"rtp",ko:"복귀 기준을 미리 문서로 만든다",en:"Agree the criteria in advance",src:["fifamed","concussion","uefa"],
 flow:"경기 › 경기 준비 › 명단과 팀 › 선수단 상태 — 복귀 기준은 명단을 짜기 전에 이미 적혀 있어야 한다",
 why:"복귀 논쟁은 대개 중요한 경기 앞에서 일어난다. 그 자리에서 기준을 만들면 이긴 쪽은 언제나 경기다. 기준은 조용할 때 만들어 둔다.",
 links:{},
 lessons:[
  L("t2-rtp-1",
    "복귀 절차 — 미리 합의하고 개별 적용",
    "Decide when it is quiet",
    "시즌 전에 평가·연락·의사결정 담당자와 기록 방식을 정하면 급박한 복귀 압력을 줄이는 데 도움이 된다.\n\n구체적인 의학적 복귀 기준은 적절한 의료진이 손상·치료·선수 상태에 맞게 정하고 갱신한다. 코치가 부위별 기준표만 만들어 모든 선수에게 적용하지 않는다.\n\n진행 조건·중단 신호·재확인 시점과 필요한 정보를 공유한다. 사전 합의나 서명이 당일의 새 증상 평가를 대신하지 않는다.",
    ["역할과 절차는 미리 합의하고 의료 기준은 선수 상태에 맞게 적용·갱신한다"],
    "진행 조건을 충족했던 선수에게 새 통증이 생기면 사전 계획을 멈추고 의료진과 재평가한다.",
    "사전 복귀 절차와 개별 복귀 기준의 관계는?",
    ["코치가 만든 부위별 표로 모두 복귀시킨다","역할과 절차는 미리 합의하고 의료 기준은 선수 상태에 맞게 적용·갱신한다","서명했으면 새 증상은 무시한다","중요한 경기 직전에 기준을 낮춘다"],
    1,
    "역할과 절차는 미리 합의하고 의료 기준은 선수 상태에 맞게 적용·갱신한다"),
  L("t2-rtp-2",
    "복귀는 횟수보다 기준으로 정한다",
    "Train first, play second",
    "경기 복귀는 통증이 사라졌다는 한 조건이나 접촉 훈련 횟수만으로 결정하지 않는다. 부상 특성, 기능, 종목 요구와 선수의 준비를 함께 평가한다.\n\n접촉 훈련 한두 번을 마치면 누구나 출전할 수 있다는 보편적 기준은 없다. 필요한 노출과 회복 확인은 의료진·선수·코치가 부상별 계획에 따라 정한다.\n\n참여 복귀, 종목 복귀, 원래 수행 수준 회복을 구분한다. 다음날의 반응도 확인하며 계획을 조절한다.",
    ["경기 복귀 — 고정 훈련 횟수 대신 부상별 기준"],
    {"현장에서":"횟수만으로 결정하지 않는다. 부상별 의료·기능 기준, 경기 요구와 선수 준비, 훈련 후 반응을 함께 평가한다."},
    "접촉 훈련을 두 번 마친 선수의 경기 복귀를 어떻게 결정하는가?",
    ["정해진 횟수나 기간만 채우면 관리가 끝난다","횟수만으로 결정하지 않는다. 부상별 의료·기능 기준, 경기 요구와 선수 준비, 훈련 후 반응을 함께 평가한다.","선수 의지만 확인한다","통증 보고를 기록하지 않는다"],
    1,
    "횟수만으로 결정하지 않는다. 부상별 의료·기능 기준, 경기 요구와 선수 준비, 훈련 후 반응을 함께 평가한다."),
  L("t2-rtp-3",
    "복귀 뒤에도 반응을 확인한다",
    "Watch after the return",
    "복귀는 관리의 끝이 아니다. 운동 노출이 늘면서 통증·기능·피로가 어떻게 변하는지 확인한다.\n\n모든 부상에 같은 “최소 4주” 위험 기간을 적용하지 않는다. 부상 종류, 중증도, 이전 이력과 복귀 과정에 따라 관찰 기간과 부하 계획이 달라진다.\n\n출전 시간과 훈련 노출을 기록하고 계획한 반응에서 벗어나면 의료진과 재평가한다. 구체적인 기간과 증가 폭은 개별 계획에 적는다.",
    ["복귀 후 관리 — 부상별 계획과 실제 반응으로 조절"],
    {"현장에서":"모든 부상에 같은 기간을 적용하지 않고 부상 특성·이력·노출과 회복 반응에 따라 개별 계획을 세우고 재평가한다."},
    "복귀 뒤 관리 기간과 부하를 어떻게 정하는가?",
    ["정해진 횟수나 기간만 채우면 관리가 끝난다","모든 부상에 같은 기간을 적용하지 않고 부상 특성·이력·노출과 회복 반응에 따라 개별 계획을 세우고 재평가한다.","선수 의지만 확인한다","통증 보고를 기록하지 않는다"],
    1,
    "모든 부상에 같은 기간을 적용하지 않고 부상 특성·이력·노출과 회복 반응에 따라 개별 계획을 세우고 재평가한다.")
 ]});

mod({id:"t2-record",track:"at",level:2,area:"record",ko:"부상을 세면 팀이 보인다",en:"Injury surveillance",src:["fifamed","uefa"],
 flow:"팀 › 선수단 상태의 변화와 경기 › 결과·기록의 메모가 쌓여 시즌 리포트가 된다",
 why:"부상을 세는 목적은 누구를 탓하기 위해서가 아니라 우리 팀에서 반복되는 패턴을 찾기 위해서다. 세지 않으면 매년 같은 시기에 같은 부상을 다시 겪는다.",
 links:{},
 lessons:[
  L("t2-record-2-1",
    "기록의 정의와 변경 이력을 남긴다",
    "Define an injury",
    "건강 문제 전체, 의료 처치가 필요한 손상, 시간손실 손상은 집계 범위가 다르다. 무엇을 기록하고 결석·제한 참여를 어떻게 세는지 명시한다.\n\n당일 중단 후 다음 날 완전히 복귀하면 시간손실 일수가 0일일 수 있다. 증상이나 조절 참여를 기록에서 자동 삭제하지 않는다.\n\n정의가 부적절하면 시즌 중에도 수정할 수 있다. 변경 날짜·이유·기준 버전을 남기고 이전 자료와의 비교 가능성을 확인한다.",
    ["정의와 변경 이력을 남기고 기존 자료와 비교할 수 있는지 확인한다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "시즌 중 손상 기록 기준을 수정해야 한다면?",
    ["일관되기만 하면 어떤 부상 정의든 정확하다","정의와 변경 이력을 남기고 기존 자료와 비교할 수 있는지 확인한다","오류가 있어도 시즌 끝까지 수정하면 안 된다","기준이 바뀌어도 설명 없이 이전 값과 합친다"],
    1,
    "정의와 변경 이력을 남기고 기존 자료와 비교할 수 있는지 확인한다"),
  L("t2-record-2-2",
    "시기와 상황을 함께 적는다",
    "When and how",
    "부위만 세면 '햄스트링 5건'에서 멈춘다. 그 숫자로는 무엇을 바꿔야 할지 알 수 없다.\n\n두 가지를 함께 적으면 그 5건이 이야기가 된다.\n\n- 언제 — 프리시즌 · 시즌 초 · 대회 주간\n\n- 어떤 상황 — 훈련인지 경기인지, 접촉인지 비접촉인지\n\n예를 들어 \"햄스트링 5건 중 4건이 프리시즌 3주차, 전부 비접촉\"이라면 이건 완전히 다른 정보다. 그 시기의 부하 곡선을 봐야 한다는 뜻이고, 비접촉이라는 사실만으로 준비 부족을 원인으로 확정하지 않는다.\n\n반대로 \"5건이 시즌 내내 흩어져 있고 대부분 접촉\"이라면 다른 이야기다.\n\n시기와 상황은 가능한 설명을 검토할 출발점이다. 노출 시간과 다른 요인도 확인한다.\n\n그리고 실행 하나 — 대회 주간에 부상이 몰리면 그 주 계획을 다시 봐야 한다.\n\n대회 주간은 부하·이동·잠이 모두 흔들리는 구간이라(피지컬 교과서 3부), 부상이 몰리는 것이 이상하지 않다. 그런데 세어 보지 않으면 그 사실을 모른다.",
    ["부위 + 시기 + 상황 · 훈련인지 경기인지 · 접촉인지 비접촉인지."],
    "대회 주간에 부상이 몰리면 그 주 계획을 다시 봐야 한다. 부하·이동·잠이 모두 흔들리는 구간이라 몰릴 이유가 충분하다. 지난 시즌 부상에 시기와 상황을 붙여 보라. 이야기가 되는 것이 하나쯤 나온다.",
    "'햄스트링 5건'만으로 알 수 없는 것은?",
    ["어느 부위인지","언제·어떤 상황에서 났는지","몇 건인지","어느 시즌인지"],
    1,
    "시기와 상황은 가능한 설명을 검토할 출발점이다. 노출 시간과 다른 요인도 확인한다."),
  L("t2-record-2-3","시즌 리포트 한 장","One page at season end",
   "시즌이 끝나면 부위·시기·상황을 한 장으로 정리해 코치와 함께 읽는다. 여기서 나온 두세 줄이 다음 시즌 프리시즌 계획과 예방 프로그램의 첫 자료가 된다. 읽히지 않는 기록은 기록이 아니다.",
   ["시즌 끝에 한 장","코치와 함께 읽는다","다음 프리시즌의 첫 자료"],
   {at:"리포트 마지막에 '다음 시즌에 바꿀 것 세 줄'을 반드시 넣어라.",coach:"프리시즌 첫 회의에 이 한 장을 안건으로 올려라."},
   "시즌 부상 리포트가 값을 하는 순간은?",["작성될 때","다음 시즌 계획을 바꿀 때","보고할 때","보관될 때"],1,
   "다음 행동으로 이어지지 않는 기록은 서랍에서 끝난다.")
 ]});

/* ═══════════════════════ 피지컬 · 3 심화 ═══════════════════════ */
mod({id:"f3-grow",track:"physical",level:3,area:"grow",ko:"다 자란 뒤에 남는 차이",en:"After maturation",src:["ypd","ioc","dfb"],
 flow:"IDP › 평가 › 유형 지도와 팀 › 게임모델 › 포지션별 기준의 신체 칸이 같은 선수를 두 각도에서 말한다",
 why:"성숙도가 정리되고 나면 남는 차이는 진짜 개인차다. 이때부터는 '누가 먼저 자랐나'가 아니라 '이 선수의 몸이 어떤 축구를 할 수 있게 하는가'가 질문이 된다.",
 links:{},
 lessons:[
  L("f3-grow-1",
    "늦게 성숙한 선수의 기회를 지킨다",
    "What late developers bring",
    "성숙 시기는 신체적 조건에 영향을 주지만 기술·판단·장기 잠재력을 결정하지 않는다. 일찍 큰 선수는 기술을 덜 배운다거나 늦게 큰 선수는 결국 더 잘한다는 고정관념을 피한다.\n\n체격이 다른 환경에서 다양한 해결책을 연습할 기회를 마련한다. 성숙도를 고려한 그룹도 안전·경험·기술과 선수의 반응을 함께 검토해 사용한다.\n\n현재 체격만으로 평가하지 않고 여러 시점의 행동·경험과 선수의 의견을 기록한다.",
    ["체격으로 능력을 단정하지 않고 개인의 기술·경험·발달 기회를 함께 본다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "성숙 시기가 다른 선수를 지도할 때 적절한 관점은?",
    ["큰 선수는 모두 판단 능력이 부족하다","체격으로 능력을 단정하지 않고 개인의 기술·경험·발달 기회를 함께 본다","늦게 자란 선수는 모두 성인기에 더 잘한다","성숙도만으로 선발과 잠재력을 결정한다"],
    1,
    "체격으로 능력을 단정하지 않고 개인의 기술·경험·발달 기회를 함께 본다"),
  L("f3-grow-2","자리마다 다른 몸","Position profiles",
   "성인 단계에서는 자리마다 요구되는 몸의 모양이 갈린다. 같은 팀 안에서도 센터백과 윙어에게 필요한 것이 다르므로 모두에게 같은 체력 프로그램을 주는 것 자체가 비효율이 된다.",
   ["자리마다 요구가 갈린다","같은 프로그램은 이 단계에서 비효율","팀 기준 + 자리 보충 + 개인 보충"],
   {physical:"팀 프로그램 위에 자리별 보충 두 가지씩만 정해 두라.",coach:"게임모델 › 포지션별 기준의 신체 칸을 그 보충과 같은 말로 적어라."},
   "성인 단계 체력 프로그램의 구조로 적절한 것은?",["전원 동일","팀 기준 + 자리별 보충 + 개인 보충","개인별 완전 개별","포지션별 완전 분리"],1,
   "공통 위에 층을 얹는 구조가 현실적이다."),
  L("f3-grow-3","몸을 이유로 자리를 바꿀 때","Changing position for the body",
   "몸의 특성 때문에 자리를 옮기는 결정은 선수의 정체성을 건드린다. 그래서 근거를 숫자와 장면으로 함께 보여 주고, 선택지를 함께 만드는 것이 필요하다. 통보로 하면 그 선수는 다음 자리에서도 자기 것이 아니라고 느낀다.",
   ["자리 변경은 정체성을 건드린다","숫자와 장면으로 근거를 보인다","통보가 아니라 함께 만든다"],
   {physical:"자리 변경 제안 전에 그 선수의 강점 세 가지를 먼저 정리하라.",coach:"IDP › 면담에 그 대화를 기록으로 남겨라."},
   "몸의 특성 때문에 포지션 변경을 제안할 때 가장 중요한 것은?",["빠른 결정","근거를 함께 보고 선수와 함께 정하는 것","코치의 확신","즉시 시행"],1,
   "설득되지 않은 이동은 다음 자리에서도 뿌리내리지 못한다.")
 ]});

mod({id:"f3-load",track:"physical",level:3,area:"load",ko:"시즌을 통째로 그린다",en:"Planning the season",src:["rpe","fifamed","ypd"],
 flow:"일정 › 연간의 요약(훈련·경기·휴식)과 월간 강도 분포가 그 계획이 실제로 굴러갔는지 보여 준다",
 why:"주간 계획을 아무리 잘 짜도 시즌 전체 모양이 없으면 어디서 올리고 어디서 내릴지 알 수 없다. 심화 단계의 일은 한 해의 지형을 먼저 그리는 것이다.",
 links:{},
 lessons:[
  L("f3-load-1","구간을 먼저 나눈다","Blocks first",
   "프리시즌·시즌 전반·중간 휴식·시즌 후반·대회·오프. 구간을 먼저 나누고 각 구간의 목적을 한 줄로 적으면, 그 안의 주간 계획은 거의 자동으로 나온다. 구간 없이 주간만 쌓으면 시즌 중반에 방향을 잃는다.",
   ["구간 → 목적 한 줄 → 주간","구간 없이 주간만 쌓으면 방향을 잃는다","오프와 중간 휴식도 구간이다"],
   {physical:"연간 달력에 구간 색을 먼저 칠하고 목적을 한 줄씩 적어라.",coach:"일정 › 연간에서 그 구간이 실제 훈련·경기·휴식 수와 맞는지 확인하라."},
   "시즌 계획을 세우는 순서로 알맞은 것은?",["주간부터 쌓아 올린다","구간을 먼저 나누고 목적을 정한 뒤 주간을 짠다","경기 일정만 본다","작년 계획을 복사한다"],1,
   "지형이 있어야 길이 정해진다."),
  L("f3-load-2",
    "경기 밀집 주간도 개인 노출에 맞춘다",
    "Congested periods",
    "경기가 잦으면 회복 시간과 추가 훈련 부하를 신중히 조절한다. 팀 일정만으로 모든 선수의 부하가 같아지지는 않는다.\n\n많이 뛴 선수와 적게 뛰거나 결장한 선수는 요구가 다르다. 실제 출전·이동·증상·회복을 보고 보충 훈련과 휴식을 개별로 계획한다.\n\n경기가 두 번이라는 이유로 새 훈련을 모두 금지하거나 모든 선수에게 같은 회복 세션을 주지 않는다.",
    ["실제 노출·상태·다음 일정을 보고 필요한 보충 훈련과 회복을 정한다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "주 2경기 동안 출전이 거의 없었던 선수의 계획은?",
    ["팀이 두 경기 했으니 모두 같은 부하로 본다","실제 노출·상태·다음 일정을 보고 필요한 보충 훈련과 회복을 정한다","출전 여부와 관계없이 모든 훈련을 없앤다","출전이 없으면 최대 강도 훈련을 무조건 추가한다"],
    1,
    "실제 노출·상태·다음 일정을 보고 필요한 보충 훈련과 회복을 정한다"),
  L("f3-load-3",
    "개인 부하 모델을 만든다",
    "Individual models",
    "같은 팀 안에서도 사람마다 견디는 폭이 다르다. 이건 성실함의 문제가 아니라 몸의 특성이다.\n\n그런데 이 폭을 미리 알 방법은 없다. 훈련 이력·증상·검사·선수와의 대화 등 여러 정보를 함께 살핀다. 기록은 그중 중요한 자료다.\n\n몇 달 쌓인 기록이 있으면 이런 문장이 만들어진다 — \"이 선수는 이 정도에서 흔들린다.\"\n\n그 문장이 생기면 개인 기준선이 생긴 것이고, 그때부터 계획이 사람에 맞춰진다.\n\n이것이 왜 큰 변화인가. 그 전까지는 팀 규칙 하나로 모두를 관리했다 — \"복귀 시 개별 제한을 확인\", \"급성장기는 충격 동작을 줄인다\" 같은 일반 규칙. 규칙은 유용하지만 그 선수에 대해서는 아무것도 모른다.\n\n개인 기준선이 생기면 규칙 대신 그 사람의 실제 이력으로 결정한다. 이것이 부하 관리의 다음 단계다.\n\n조건은 하나뿐이다 — 몇 달 이상 끊기지 않은 기록. 개인 기준선은 시간이 만든다. 빈 칸이 많은 기록으로는 만들어지지 않는다.",
    ["사람마다 견디는 폭이 다르다 · 몇 달의 기록이 개인 기준선을 만든다."],
    "그 기준선을 명단·출전 시간 결정의 근거로 함께 쓰라. \"이 선수는 3주 연속 풀타임 뒤에 흔들렸다\"는 감이 아니라 이력이다. 지금까지 쌓인 기록에서 한 선수의 기준선을 한 문장으로 써 볼 수 있는지 시도해 보라. 안 써진다면 기록이 아직 부족한 것이다.",
    "개인 부하 기준선을 만들 수 있게 되는 조건은?",
    ["정밀한 측정 장비","몇 달 이상 끊기지 않은 기록","선수의 자기 보고","의무 스태프의 평가"],
    1,
    "개인 기준선은 시간이 만든다. 빈 칸이 많은 기록으로는 만들어지지 않는다.")
 ]});

mod({id:"f3-move",track:"physical",level:3,area:"move",ko:"약점을 골라 프로그램을 만든다",en:"Individual programmes",src:["ypd","fifamed"],
 flow:"IDP › 평가의 신체 항목과 팀 › 평가표의 자리 요구 차이가 그 선수의 프로그램이 된다",
 why:"모두에게 같은 보강을 주는 단계를 지나면, 그 선수의 자리 요구와 지금 사이의 차이를 메우는 것이 훈련이 된다. 그 차이를 찾는 것이 이 단계의 기술이다.",
 links:{},
 lessons:[
  L("f3-move-1","요구와 지금의 차이","The gap",
   "그 자리가 요구하는 것과 그 선수가 지금 할 수 있는 것을 나란히 놓으면 차이가 보인다. 모든 차이를 다 메울 수는 없으니 경기력에 가장 크게 걸리는 하나를 고른다. 하나를 제대로 메우는 것이 셋을 조금씩 건드리는 것보다 낫다.",
   ["요구 vs 지금을 나란히 놓는다","가장 크게 걸리는 하나를 고른다","하나를 제대로가 셋을 조금씩보다 낫다"],
   {physical:"선수마다 '이번 분기의 하나'를 정해 적어라.",coach:"IDP › 성장 › 분기 목표에 그 하나를 같이 적게 하라."},
   "개인 보강 항목을 고르는 기준으로 가장 적절한 것은?",["가장 약한 항목","경기력에 가장 크게 걸리는 하나","가장 재기 쉬운 항목","선수가 원하는 것"],1,
   "약점이 모두 중요한 것은 아니다. 경기에 걸리는 것이 중요하다."),
  L("f3-move-2","보강은 훈련 안에 붙인다","Attach, don't append",
   "따로 시간을 내는 개인 보강은 오래 못 간다. 팀 훈련 전후 10분에 붙이고, 그 자리에 코치가 서 있으면 지속된다. 지속되지 않는 프로그램은 설계가 잘못된 것이지 선수가 게으른 것이 아니다.",
   ["팀 훈련 앞뒤 10분에 붙인다","코치가 그 자리에 서 있어야 지속된다","안 지켜지면 설계를 의심한다"],
   {physical:"개인 보강을 웜업 뒤 5분·정리 전 5분으로 고정하라.",coach:"그 10분에 코치가 함께 서라 — 그 자체가 프로그램의 절반이다."},
   "개인 보강 프로그램이 지속되지 않을 때 먼저 의심할 것은?",["선수의 의지","프로그램의 설계(시간·자리·감독)","운동의 난이도","장비"],1,
   "지속성은 설계의 문제다."),
  L("f3-move-3","좋아졌는지 어떻게 아는가","Did it work",
   "프로그램을 시작할 때 무엇이 어떻게 변하면 성공인지를 함께 정한다. 정하지 않으면 몇 달 뒤 아무도 답할 수 없고, 프로그램은 습관으로만 남는다.",
   ["시작할 때 성공 기준을 정한다","기준이 없으면 습관만 남는다","기간도 함께 정한다"],
   {physical:"프로그램 카드에 목표·기간·성공 기준 세 줄을 넣어라.",coach:"분기 리뷰에서 그 세 줄을 함께 읽어라."},
   "개인 프로그램을 시작할 때 반드시 함께 정해야 하는 것은?",["운동 종류","무엇이 어떻게 변하면 성공인지","횟수","장소"],1,
   "성공 기준이 없으면 끝을 알 수 없다.")
 ]});

mod({id:"f3-design",track:"physical",level:3,area:"design",ko:"체력과 전술을 한 계획으로",en:"One plan, not two",src:["knvb","ypd","rpe"],
 flow:"일정 › 주간의 세션 주제와 강도가 한 줄에 같이 있는 이유가 여기 있다 — 두 계획이 아니라 하나다",
 why:"체력 계획과 전술 계획이 따로 돌면 선수는 두 개의 주간을 산다. 심화 단계의 일은 하나의 주간 안에서 둘이 서로를 방해하지 않게 배치하는 것이다.",
 links:{},
 lessons:[
  L("f3-design-1",
    "전술과 체력의 요구를 한 계획에서 조정한다",
    "Do not stack",
    "전술 훈련에도 신체 부하가 있고 체력 훈련에도 경기 목적이 있다. 두 계획이 같은 선수에게 어떤 요구를 더하는지 함께 확인한다.\n\n강한 전술·체력 자극을 같은 날 배치하면 반드시 둘 다 나빠진다는 법칙은 없다. 의도적으로 높은 부하를 모으거나 나누는 방식 모두 일정·회복·과제의 목적에 따라 검토할 수 있다.\n\n주요 목표, 순서, 총량과 개인 제한을 코치·피지컬·의료 담당자가 맞춘다. 계획한 자극과 실제 수행이 다르면 조절 이유를 남긴다.",
    ["같은 날의 총 요구·순서·회복을 함께 설계한다. 큰 자극 하나만 가능하다는 고정 규칙은 없다."],
    "높은 부하를 같은 날에 모으기로 했다면 다음날 회복과 개별 제한까지 포함해 합의하고 실제 반응을 확인한다.",
    "강한 전술 훈련과 근력 훈련을 같은 날 계획했다. 먼저 할 일은?",
    ["같은 날이면 언제나 실패하므로 무조건 분리한다","두 활동의 목적·총 요구·순서·회복과 개인 제한을 함께 검토한다","각 담당자가 따로 계획하고 선수에게 맡긴다","전술 훈련의 신체 부하는 계산하지 않는다"],
    1,
    "같은 날의 총 요구·순서·회복을 함께 설계한다. 큰 자극 하나만 가능하다는 고정 규칙은 없다."),
  L("f3-design-2",
    "게임 과제와 별도 체력 과제를 함께 고른다",
    "Intensity by design",
    "공간·인원·규칙·운동과 휴식 시간을 바꾸면 축구 과제의 요구가 달라진다. 의도한 자극이 실제로 나오는지 선수별 반응을 확인한다.\n\n축구 과제만으로 모든 체력 요소와 개인 필요를 충족하는 것은 아니다. 부족한 속도·근력 등은 별도 과제로 보완할 수 있다.\n\n별도 달리기나 저항 훈련이 축구와 분리된 쓸모없는 몸을 만든다고 단정하지 않는다. 경기 목적, 선수의 부족한 요소와 주간 부하 안에서 과제의 역할을 정한다.",
    ["축구 과제로 만드는 자극과 부족한 요소의 별도 보완을 함께 설계한다."],
    "공을 쓰는 과제의 장점을 유지하면서 부족한 고속 달리기나 근력을 적절한 별도 과제로 보완하고 합계 부하를 확인한다.",
    "게임 과제에서 필요한 힘·속도 자극이 충분하지 않다. 어떻게 하는가?",
    ["공 없는 훈련은 축구에 도움이 되지 않으므로 배제한다","실제 노출과 개인 요구를 확인하고 별도 과제로 보완할 수 있다","게임만 하면 모든 체력이 자동으로 충족된다","부족한 항목을 확인하지 않고 시간을 두 배로 늘린다"],
    1,
    "축구 과제로 만드는 자극과 부족한 요소의 별도 보완을 함께 설계한다."),
  L("f3-design-3","스태프가 같은 표를 본다","One table, one staff",
   "코치·피지컬·의무가 각자 다른 계획표를 보면 같은 선수에게 서로 다른 요구가 간다. 한 장의 주간표에 주제·강도·부상 상태·개인 상한이 함께 있어야 한다. 도구가 아니라 합의가 핵심이다.",
   ["한 장의 주간표를 함께 본다","주제·강도·상태·상한이 한곳에","도구보다 합의"],
   {physical:"주 시작 회의를 15분만 정례로 만들어라.",coach:"일정 › 주간 화면을 그 회의의 유일한 자료로 쓰라."},
   "스태프가 각자 다른 계획표를 볼 때 생기는 문제는?",["효율적 분업","같은 선수에게 상충하는 요구가 간다","의사소통 증가","문제없음"],1,
   "선수는 스태프의 불일치를 그대로 몸으로 받는다.")
 ]});

mod({id:"f3-recover",track:"physical",level:3,area:"recover",ko:"회복을 시스템으로",en:"Recovery as a system",src:["fifamed","ioc"],
 flow:"IDP › 컨디션 체크인 · 팀 › 오늘 훈련 인원 · 일정 › 휴식 — 세 화면이 한 시스템으로 돈다",
 why:"회복이 개인의 성실함에 달려 있으면 팀마다 편차가 커진다. 심화 단계의 일은 회복을 팀의 절차로 만드는 것이다 — 누가 언제 무엇을 하는지가 정해져 있게.",
 links:{},
 lessons:[
  L("f3-recover-1",
    "경기 후 절차를 고정한다",
    "A fixed post-match routine",
    "회복을 시스템으로 만드는 첫걸음은 순서를 고정하는 것이다.\n\n경기 종료부터 귀가까지의 순서를 정해 두면 매번 같은 회복이 일어난다.\n\n- 정리\n\n- 수분 · 식사\n\n- 짧은 정리 대화\n\n- 이동\n\n순서가 없으면 매번 다른 것이 빠진다. 그리고 현장에서 가장 자주 빠지는 것은 대개 식사다 — 미팅이 길어지거나, 버스가 기다리거나, 정리가 늦어지면 밀려나는 것이 늘 그것이다.\n\n왜 하필 식사가 빠지나. 가장 유연해 보이기 때문이다. \"집에 가서 먹으면 되지\"라는 생각이 매번 이긴다. 그런데 2부에서 본 대로 회복 섭취는 일찍 준비하되 특정 날이나 시각에 회복 가능성이 닫히는 것으로 설명하지 않는다.\n\n그래서 실행은 하나로 요약된다 — 경기 후 미팅을 짧게 하고 절차를 지켜라.\n\n고정된 절차만이 반복된다. 매번 상황에 맞춰 정하면 매번 상황이 이긴다.",
    ["종료부터 귀가까지 순서를 고정 · 순서가 없으면 매번 다른 것이 빠진다."],
    "경기 뒤 필요한 안전 확인·수분·식사·이동·수면을 확보하고, 리뷰 시간은 선수 상태와 일정에 맞게 정한다. 24시간 뒤만 가능한 것은 아니다.",
    "경기 후 회복 절차를 고정하는 이유는?",
    ["선수들을 통제하기 위해","매번 같은 회복이 일어나게 하려고","귀가 시간을 앞당기려고","스태프 업무를 줄이려고"],
    1,
    "고정된 절차만이 반복된다. 매번 정하면 매번 상황이 이긴다."),
  L("f3-recover-2",
    "대회 일정 — 출전과 회복을 함께",
    "Travel and tournaments",
    "짧은 간격의 경기가 이어지면 수면·식사·수분·이동과 출전 시간을 함께 계획한다. 중요한 경기가 언제인지에 대한 가정만으로 선수를 계속 기용하지 않는다.\n\n많이 뛴 선수는 회복이 우선일 수 있고, 출전이 적은 선수는 적절한 보충 활동이 필요할 수 있다. 대회 중 훈련을 전원에게 일괄 금지하거나 부여하지 않는다.",
    ["개인의 상태와 다음 일정을 보고 필요한 보충 활동을 정한다"],
    "경기 뒤 선수별 출전 시간과 불편감을 확인해 다음날 회복·보충·팀 활동을 나눈다.",
    "연속 경기 대회에서 출전 시간이 거의 없는 선수는?",
    ["대회 중에는 모두 무조건 쉰다","개인의 상태와 다음 일정을 보고 필요한 보충 활동을 정한다","많이 뛴 선수와 똑같은 부하를 준다","마지막 경기까지 확인하지 않는다"],
    1,
    "개인의 상태와 다음 일정을 보고 필요한 보충 활동을 정한다"),
  L("f3-recover-3",
    "무엇이 통했는지 남긴다",
    "Record what worked",
    "회복 방법은 팀마다 · 사람마다 반응이 다르다. 어떤 팀에서 잘 통한 방법이 우리 팀에서 아무 차이를 못 만드는 일은 흔하다.\n\n그래서 필요한 것이 우리 기록이다.\n\n- 무엇을 했는지\n\n- 다음 날 컨디션이 어땠는지\n\n이 둘을 기록하면 반응을 검토할 수 있다. 다만 경기 노출·수면·일정 같은 다른 요인이 있어 관찰 기록만으로 효과의 원인을 확정하지 않는다.\n\n그리고 여기에 방법론 하나가 필요하다 — 한 번에 하나만 바꾼다.\n\n이유는 단순하다. 회복 절차를 세 개 동시에 바꾸고 다음 날 컨디션이 좋아졌다면, 무엇이 통했는지 영원히 모른다. 그리고 셋 다 계속하게 된다 — 그중 둘은 아무 효과가 없는데도.\n\n마지막으로 순서에 대한 조언 하나. 새 회복 장비를 들이기 전에 잠·식사 기록부터 보라. 대개 가장 큰 개선 여지가 그 둘에 있고, 그 둘은 돈이 들지 않는다.\n\n유행하는 방법보다 우리 기록이 낫다.",
    ["한 것과 다음 날 컨디션을 함께 남긴다 · 한 번에 하나만 바꾼다 · 유행보다 우리 기록."],
    "새 회복 장비를 들이기 전에 잠·식사 기록부터 보라. 가장 큰 개선 여지가 대개 거기에 있고, 그건 돈이 들지 않는다. 이번 달에 회복 절차 하나만 바꿔 보고 다음 날 컨디션을 기록해 보라. 하나만 바꿔야 결과를 읽을 수 있다.",
    "회복 방법의 효과를 팀에서 확인하는 방법은?",
    ["여러 방법을 한꺼번에 도입한다","한 번에 하나만 바꾸고 다음 날 컨디션을 기록한다","선수들에게 만족도를 묻는다","다른 팀의 사례를 참고한다"],
    1,
    "한 번에 여러 개를 바꾸면 무엇이 통했는지 영원히 모른다.")
 ]});

mod({id:"f3-measure",track:"physical",level:3,area:"measure",ko:"기록을 결정으로 바꾼다",en:"From data to decisions",src:["rpe","ypd"],
 flow:"팀 › 오늘 훈련 인원 · 일정 › 세션 강도 · 경기 › 출전 기록이 한 선수의 한 주를 이룬다",
 why:"기록이 쌓이기만 하고 결정에 쓰이지 않으면 그것은 일이 아니라 취미다. 심화 단계의 일은 어떤 기록이 어떤 결정에 쓰이는지 미리 정하는 것이다.",
 links:{},
 lessons:[
  L("f3-measure-1","결정 목록을 먼저 적는다","List the decisions",
   "우리가 매주 내리는 결정을 먼저 적는다 — 오늘 강도, 이 선수를 뺄까, 복귀 시점, 명단. 그다음 각 결정에 필요한 기록을 붙인다. 이 순서로 하면 안 쓰는 기록을 만들지 않는다.",
   ["결정 목록 → 필요한 기록","반대 순서로 하면 안 쓰는 기록이 쌓인다","결정에 안 붙는 기록은 지운다"],
   {physical:"지금 모으는 기록 중 어느 결정에도 안 붙는 것을 찾아 지워라.",coach:"기록을 늘리자는 제안에 '어떤 결정에 쓰나'를 물어라."},
   "새로운 측정 항목을 추가할 때 먼저 물어야 할 것은?",["측정이 쉬운가","어떤 결정에 쓰이는가","선수가 좋아하는가","다른 팀도 하는가"],1,
   "결정에 붙지 않는 기록은 일만 늘린다."),
  L("f3-measure-2","한 화면에서 본다","One screen",
   "부하·컨디션·부상 상태·출전 시간이 서로 다른 곳에 있으면 아무도 종합하지 못한다. 한 선수의 한 주가 한 화면에 보이는 것이 시스템의 최소 조건이다.",
   ["한 선수의 한 주를 한 화면에","흩어져 있으면 종합되지 않는다","도구보다 한곳에 모으는 습관"],
   {physical:"주간 회의 전에 위험군 선수의 한 주를 한 장으로 만들어라.",coach:"팀 › 선수단과 일정을 나란히 놓고 보라."},
   "모니터링 시스템의 최소 조건은?",["정밀한 장비","한 선수의 한 주가 한곳에 보이는 것","많은 항목","자동화"],1,
   "흩어진 자료는 결정을 만들지 못한다."),
  L("f3-measure-3",
    "건강 기록과 경기력 판단의 경계",
    "Numbers never decide alone",
    "숫자는 의사결정의 한 근거이며 맥락과 대화를 함께 요구한다. 수치 하나를 자동 선발 규칙으로 쓰지 않는다.\n\n통증·피로의 정직한 보고를 벌점으로 취급하면 보고가 위축될 수 있다. 다만 건강 정보에 따라 안전을 위해 활동이나 출전을 제한하는 판단은 필요할 수 있다.\n\n필요한 담당자만 기록을 보고, 선수에게 수집 목적과 판단 이유를 설명한다.",
    ["불이익을 위한 평가와 안전 판단을 구분하고 필요한 담당자와 활동을 조절한다"],
    "선수가 통증을 말하면 의료진과 확인할 항목 및 가능한 활동 범위를 설명하고 회복 경과를 다시 확인한다.",
    "통증 보고를 받은 코치의 적절한 대응은?",
    ["정직하게 말했으니 절대 출전을 조절하지 않는다","불이익을 위한 평가와 안전 판단을 구분하고 필요한 담당자와 활동을 조절한다","통증 보고를 무조건 선발 감점으로 쓴다","팀 전체에 세부 건강 정보를 공개한다"],
    1,
    "불이익을 위한 평가와 안전 판단을 구분하고 필요한 담당자와 활동을 조절한다")
 ]});

/* ═══════════════════════ 분석 · 3 심화 ═══════════════════════ */
mod({id:"a3-see",track:"analysis",level:3,area:"see",ko:"팀의 분석 체계를 만든다",en:"Building the system",src:["process","fifa","bepro"],
 flow:"팀 › 게임모델 › 국면 원칙 → 관찰 항목 → 경기 › 국면 평가 → 일정 › 국면 배분. 네 화면이 한 고리다",
 why:"한 사람이 잘 보는 것과 팀이 계속 보는 것은 다르다. 심화 단계의 일은 사람이 바뀌어도 같은 것을 보는 체계를 만드는 것이다.",
 links:{},
 lessons:[
  L("a3-see-1",
    "시즌 지표 — 적게 정하고 기준을 남긴다",
    "Five, not fifty",
    "핵심 지표를 적게 정하면 지속해서 기록하고 읽기 쉽다. 다섯 개는 시작 예시이며 팀마다 필요한 수가 다르다.\n\n정의와 집계 방법을 일관되게 유지하되 잘못된 기준이나 새 필요가 확인되면 수정할 수 있다.\n\n수정한 날짜·이유·정의 버전을 남기고 이전 값과 직접 비교할 수 있는지 확인한다. 원자료가 있으면 같은 기준으로 다시 계산하는 방법도 있다.",
    ["변경 시점과 정의를 남기고 이전 값과의 비교 가능성을 확인한다"],
    "성공·실패 장면을 같은 포함 기준으로 모으고 상대·점수·기회 수와 보이지 않는 정보를 함께 적는다. 다음 관찰에서 가설을 다시 확인한다.",
    "시즌 중 지표 정의를 고쳐야 한다면?",
    ["오류를 알아도 시즌이 끝날 때까지 그대로 센다","변경 시점과 정의를 남기고 이전 값과의 비교 가능성을 확인한다","설명 없이 새 값과 옛 값을 같은 것으로 비교한다","반드시 지표 다섯 개를 모두 삭제한다"],
    1,
    "변경 시점과 정의를 남기고 이전 값과의 비교 가능성을 확인한다"),
  L("a3-see-2","맥락 없는 숫자는 없다","Context always",
   "같은 지표도 상대·경기 상황·점수에 따라 다르게 읽힌다. 지고 있을 때 점유율이 오르는 것은 좋은 신호가 아닐 수 있다. 지표 옆에 상황 한 줄이 반드시 붙어야 한다.",
   ["상대·상황·점수가 지표를 바꾼다","지표 옆에 상황 한 줄","숫자만 비교하면 반대 결론이 난다"],
   {analysis:"기록지에 '점수 상황' 칸을 항상 넣어라.",coach:"보고서에서 상황이 빠진 숫자는 되물어라."},
   "지고 있는 상황에서 점유율이 높아진 것을 어떻게 읽나?",["좋은 신호","상황을 함께 봐야 판단할 수 있다","나쁜 신호","무의미"],1,
   "맥락이 없으면 같은 숫자가 반대 결론을 만든다."),
  L("a3-see-3","분석가가 바뀌어도 남는다","Outlive the analyst",
   "정의·기준·양식·지난 기록이 문서로 남아 있어야 사람이 바뀌어도 팀의 눈이 유지된다. 개인의 감각에 의존한 분석은 그 사람이 떠나면 함께 사라진다.",
   ["정의·기준·양식·기록을 문서로","개인 감각은 함께 떠난다","인수인계가 가능한 형태로"],
   {analysis:"분석 매뉴얼 한 권을 만들어 매 시즌 갱신하라.",coach:"분석 담당이 바뀔 때 매뉴얼부터 확인하라."},
   "분석 체계를 문서로 남기는 가장 큰 이유는?",["보고용","사람이 바뀌어도 팀의 눈이 유지되게","평가용","규정 준수"],1,
   "체계는 사람보다 오래 남아야 체계다.")
 ]});

mod({id:"a3-cause",track:"analysis",level:3,area:"cause",ko:"선수 프로파일과 발달 추적",en:"Player profiles over time",src:["process","fifa","jordet"],
 flow:"IDP › 평가 · 성장 · 6주 리뷰와 경기 › 개인 피드백이 한 선수의 시간을 이룬다",
 why:"경기 하나의 분석은 사진이고, 여러 경기를 이은 것은 영상이다. 심화 단계에서는 한 선수가 시간에 따라 어떻게 달라지는지가 분석의 대상이 된다.",
 links:{},
 lessons:[
  L("a3-cause-1","좋은 날과 나쁜 날의 차이","Best day, worst day",
   "한 선수의 가장 좋았던 경기와 가장 안 좋았던 경기를 나란히 놓고 무엇이 달랐는지 찾으면, 그 선수의 조건이 보인다 — 어떤 상대, 어떤 자리, 어떤 동료, 어떤 상태일 때 잘하는가.",
   ["좋은 날과 나쁜 날을 나란히","상대·자리·동료·상태를 비교","조건을 알면 만들어 줄 수 있다"],
   {analysis:"선수마다 최고·최저 경기를 하나씩 지정해 두라.",coach:"그 선수가 잘하는 조건을 만들어 주는 것도 코치의 일이다."},
   "한 선수의 최고·최저 경기를 비교하는 목적은?",["평가","그 선수가 잘하는 조건을 찾기 위해","동기 부여","선발 근거"],1,
   "조건을 알면 그 조건을 만들어 줄 수 있다."),
  L("a3-cause-2",
    "발달의 변화와 불편 신호를 구분한다",
    "Development is not linear",
    "선수의 경기력은 상대·역할·훈련·회복과 성장 등 여러 조건에 따라 흔들릴 수 있다. 한두 경기로 장기 잠재력을 확정하지 않는다.\n\n6주나 분기는 점검 일정의 예시다. 방향은 여러 시점에서 보되 갑작스러운 통증, 기능 저하나 정서적 어려움은 정해진 리뷰 날짜까지 기다리지 않는다.\n\n성장기라는 이유로 모든 하락을 정상으로 간주하지 않는다. 선수의 설명과 상태를 확인하고 필요한 담당자에게 연결한다.",
    ["장기 흐름도 보되 통증과 기능 변화를 바로 확인하고 의료 담당자에게 연결한다"],
    "성공·실패 장면을 같은 포함 기준으로 모으고 상대·점수·기회 수와 보이지 않는 정보를 함께 적는다. 다음 관찰에서 가설을 다시 확인한다.",
    "성장기 선수의 경기력이 갑자기 떨어지고 통증을 말한다. 어떻게 하나?",
    ["성장 중이면 정상이라 6주 기다린다","장기 흐름도 보되 통증과 기능 변화를 바로 확인하고 의료 담당자에게 연결한다","잠재력이 없다고 선발에서 제외한다","기록 수치만 보고 선수에게는 묻지 않는다"],
    1,
    "장기 흐름도 보되 통증과 기능 변화를 바로 확인하고 의료 담당자에게 연결한다"),
  L("a3-cause-3","선수가 자기 경기를 본다","The player analyses",
   "코치가 분석해 주는 것보다 선수가 스스로 자기 경기를 보는 습관이 오래간다. 짧은 클립과 두 개의 질문만 주면 된다 — '무엇이 보였나', '다른 방법은 있었나'. 이것이 PROCESS 를 선수에게 옮기는 방법이다.",
   ["코치의 분석보다 선수의 습관이 오래간다","짧은 클립 + 두 질문","PROCESS 를 선수에게 옮긴다"],
   {analysis:"선수용 클립을 짧게 잘라 질문과 함께 보내라.",coach:"IDP › 성찰에 그 답을 남기게 하라."},
   "선수 스스로 경기를 분석하게 할 때 주는 것으로 알맞은 것은?",["전체 경기 영상","짧은 클립과 두 개의 질문","분석 보고서","통계표"],1,
   "짧고 질문이 있는 자료가 습관을 만든다.")
 ]});

mod({id:"a3-struct",track:"analysis",level:3,area:"struct",ko:"게임모델과 분석을 한 몸으로",en:"Model and analysis as one",src:["process","rfef","knvb"],
 flow:"팀 › 게임모델 › 국면 평가 옆의 '최근 4주 훈련 N회' 가 바로 이 연결이다",
 why:"게임모델은 우리가 하려는 것이고 분석은 실제로 한 것이다. 둘을 나란히 놓지 않으면 모델은 문서로, 분석은 숫자로 따로 산다.",
 links:{},
 lessons:[
  L("a3-struct-1",
    "원칙의 증거와 관찰 기회를 함께 남긴다",
    "Evidence per principle",
    "게임모델의 원칙이 경기에서 어떻게 나타났는지 장면과 횟수를 남긴다. 해당 행동을 할 기회가 있었는지도 함께 본다.\n\n기록이 0이라는 사실만으로 선수가 원칙을 실행하지 않았다고 확정하지 않는다. 기회 부족, 촬영 범위나 태그 누락일 수 있다.\n\n자료가 충분한지 확인한 뒤 훈련·전달·원칙 자체를 검토한다. 유효한 근거를 만들지 않고 숫자만 붙이면 문서가 정확해지지 않는다.",
    ["실행 기회와 관찰·기록 누락 여부, 실제 장면을 확인한다"],
    "성공·실패 장면을 같은 포함 기준으로 모으고 상대·점수·기회 수와 보이지 않는 정보를 함께 적는다. 다음 관찰에서 가설을 다시 확인한다.",
    "원칙의 경기 기록이 계속 0일 때 먼저 볼 것은?",
    ["팀이 안 한다고 확정하고 즉시 지운다","실행 기회와 관찰·기록 누락 여부, 실제 장면을 확인한다","숫자가 0이면 다른 자료는 볼 필요 없다","선수들이 원칙을 무시했다고 단정한다"],
    1,
    "실행 기회와 관찰·기록 누락 여부, 실제 장면을 확인한다"),
  L("a3-struct-2",
    "평가와 배분을 함께 본다",
    "Rating and exposure",
    "국면을 잘하는지(평가)와 그 국면을 얼마나 다뤘는지(훈련 배분)를 나란히 놓으면 결론이 달라진다.\n\n네 경우가 나오는데, 실전에서 중요한 것은 둘이다.\n\n- 낮은데 많이 했다 → 방법을 바꿀 때\n\n- 낮은데 안 했다 → 아직 안 한 것\n\n이 구분이 없으면 정반대 처방을 하게 된다. 낮은 국면을 보면 더 훈련하자는 결론이 자동으로 나오는데, 이미 많이 한 국면이라면 더 하는 것이 답이 아니다. 양으로 안 되면 방법을 바꿔야 한다.\n\n그리고 방법을 바꾼다는 것은 앞에서 배운 것으로 이어진다 — 가설을 다시 세우고(2부), 대표성을 확인하고(1부), 조건을 바꾼다(1부).\n\n반대로 낮은데 안 한 국면은 아주 단순하다. 못하는 것이 당연하고, 이번 주 주제로 넣으면 된다.\n\n이 앱에서는 팀 › 게임모델 국면 카드에 이미 두 숫자가 나란히 있다. 새로 만들 것 없이 그걸로 다음 주를 정하면 된다.",
    ["평가 × 배분을 나란히 · 낮은데 많이 했다 = 방법 / 낮은데 안 했다 = 아직."],
    "팀 › 게임모델 국면 카드에 이미 두 숫자가 나란히 있다 — 그걸로 다음 주를 정하라. 두 숫자를 같이 보는 습관이 처방을 바꾼다. 국면 넷의 평가와 배분을 표로 그려 보라. '낮은데 많이 한' 칸이 있으면 그것이 이번 달의 진짜 과제다.",
    "국면 평가가 낮은데 그 국면을 이미 많이 훈련했다면?",
    ["더 많이 훈련한다","훈련 방법·가설을 바꾼다","그 국면을 포기한다","선수 구성을 바꾼다"],
    1,
    "양으로 안 되면 방법을 바꿔야 한다."),
  L("a3-struct-3",
    "모델과 선수의 적합성을 다시 본다",
    "When to change the model",
    "훈련과 실행 조건을 조절해도 문제가 반복되면 게임모델이 현재 선수와 환경에 맞는지 검토한다.\n\n검토를 시즌 종료까지 미룰 의무는 없다. 부상·선수 구성·일정과 경기 증거에 따라 시즌 중에도 바꿀 수 있다.\n\n유지할 방향과 바꿀 행동을 구분하고, 선수가 이해할 수 있게 설명한다. 이후 장면으로 변화의 효과와 새 위험을 확인한다.",
    ["시즌 중이라도 근거를 검토해 수정하고 새 역할을 공유·재관찰한다"],
    "성공·실패 장면을 같은 포함 기준으로 모으고 상대·점수·기회 수와 보이지 않는 정보를 함께 적는다. 다음 관찰에서 가설을 다시 확인한다.",
    "모델이 선수들과 맞지 않는 근거가 쌓였다. 적절한 대응은?",
    ["시즌 종료 전에는 어떤 변화도 금지한다","시즌 중이라도 근거를 검토해 수정하고 새 역할을 공유·재관찰한다","모델에 맞지 않는 선수의 노력만 탓한다","이유를 설명하지 않고 매 경기 전부 바꾼다"],
    1,
    "시즌 중이라도 근거를 검토해 수정하고 새 역할을 공유·재관찰한다")
 ]});

mod({id:"a3-oppo",track:"analysis",level:3,area:"oppo",ko:"시즌 단위로 상대를 본다",en:"Opponents across a season",src:["process","fa","bepro"],
 flow:"경기 › 목록의 전적(정식·친선 승무패·득실)과 각 경기의 리뷰가 쌓여 시즌의 지도가 된다",
 why:"같은 리그에서는 같은 팀을 두 번 이상 만난다. 지난 맞대결에서 무엇이 통했고 무엇이 읽혔는지 남아 있으면 두 번째 만남이 완전히 다른 경기가 된다.",
 links:{},
 lessons:[
  L("a3-oppo-1","맞대결 노트를 남긴다","The rematch note",
   "경기 뒤 상대에 대해 세 줄만 남긴다 — 통했던 것, 막혔던 것, 다음에 시도할 것. 이 세 줄이 다음 맞대결의 출발점이 되고, 매번 처음부터 분석하는 일이 사라진다.",
   ["통한 것 · 막힌 것 · 다음에 시도할 것","경기 직후에 남긴다","다음 맞대결의 출발점"],
   {analysis:"상대별 폴더를 만들어 세 줄을 계속 쌓아라.",coach:"경기 › 리뷰 › 다음 행동에 그 세 줄을 적어라."},
   "같은 상대를 다시 만날 때 가장 유용한 자료는?",["일반 통계","지난 맞대결의 통한 것·막힌 것·시도할 것","최근 경기 영상","선수 명단"],1,
   "우리와의 경기가 그 상대에 대한 가장 정확한 자료다."),
  L("a3-oppo-2","상대도 우리를 읽는다","They scout you too",
   "두 번째 만남에서 첫 경기와 똑같이 하면 상대는 이미 준비하고 있다. 그래서 우리의 반복 패턴이 무엇인지 우리가 먼저 아는 것이 필요하다 — 우리 경기를 상대의 눈으로 한 번 보는 것.",
   ["우리 패턴을 우리가 먼저 안다","우리 경기를 상대 눈으로 본다","두 번째 만남에는 변형이 필요하다"],
   {analysis:"시즌 중반에 '우리 팀 상대 분석 보고서'를 한 번 써 보라.",coach:"그 보고서를 스태프 회의에서 읽어라 — 가장 불편하고 가장 유용하다."},
   "같은 상대와의 두 번째 경기를 준비할 때 추가로 해야 할 것은?",["상대 분석만 더 깊게","우리 팀의 반복 패턴을 상대의 눈으로 점검","선수 교체","전술 변경"],1,
   "상대도 우리를 분석했다는 전제에서 시작해야 한다."),
  L("a3-oppo-3",
    "결정 마감과 긴급 변경 절차",
    "How the plan gets decided",
    "분석 제출, 스태프 합의와 선수 전달 시점을 경기 일정에 맞춰 정한다. 화·목·금은 주 1경기 팀의 예시일 뿐이다.\n\n늦은 아이디어로 계획을 자주 바꾸면 전달과 연습이 부족해질 수 있으므로 일반적인 변경 마감을 둔다.\n\n다만 갑작스러운 부상·명단·날씨·안전 문제는 예외다. 누가 결정하고 누구에게 어떻게 알릴지 정해 필요한 변경을 신속히 공유한다.",
    ["정한 책임자가 필요한 변경을 결정하고 역할을 명확히 다시 전달한다"],
    "성공·실패 장면을 같은 포함 기준으로 모으고 상대·점수·기회 수와 보이지 않는 정보를 함께 적는다. 다음 관찰에서 가설을 다시 확인한다.",
    "계획 전달 뒤 핵심 선수가 갑자기 출전할 수 없게 됐다. 어떻게 하나?",
    ["마감이 지났으므로 부상 선수도 계획대로 출전시킨다","정한 책임자가 필요한 변경을 결정하고 역할을 명확히 다시 전달한다","누구에게도 알리지 않고 각자 다른 계획을 쓴다","어떤 상황에도 전날 이후 변경은 금지한다"],
    1,
    "정한 책임자가 필요한 변경을 결정하고 역할을 명확히 다시 전달한다")
 ]});

mod({id:"a3-toTrain",track:"analysis",level:3,area:"toTrain",ko:"분석·코치·피지컬이 한 주를 함께 짠다",en:"One week, three desks",src:["process","knvb","rpe"],
 flow:"일정 › 주간 한 화면에 주제·강도·미팅·훈련이 함께 있는 이유 — 세 사람이 같은 표를 본다",
 why:"분석이 문제를 찾고, 코치가 훈련을 짜고, 피지컬이 부하를 맞춘다. 이 셋이 따로 일하면 좋은 분석이 잘못된 날에 잘못된 강도로 훈련된다.",
 links:{},
 lessons:[
  L("a3-toTrain-1",
    "주 시작 회의 15분",
    "Fifteen minutes",
    "주 시작에 셋이 모여 15분이면 한 주가 정리된다. 정할 것은 셋이다.\n\n- 이번 주 문제 하나\n\n- 그 문제를 다룰 세션\n\n- 그 세션의 강도\n\n순서가 중요하다. 문제가 정해져야 나머지가 정해진다. 세션부터 정하면 문제를 나중에 끼워 맞추게 되고(1부에서 본 함정), 가능한 강도와 안전 조건도 목표 선택과 함께 검토해야 한다.\n\n15분이면 충분하다. 그리고 이 15분이 없으면 한 주 내내 어긋난다 — 피지컬 교과서에서 본 것처럼, 각자 정하면 같은 선수에게 상충하는 요구가 간다.\n\n회의 방식에도 요령이 있다 — 일정 › 주간 화면 하나만 띄우고 회의한다.\n\n각자 자기 자료를 가져오면 세 개의 계획이 만들어지고, 한 화면만 보면 하나의 계획이 만들어진다. 그리고 그 화면에 적힌 것이 그 주의 유일한 계획이 된다.\n\n이건 도구의 문제가 아니라 약속의 문제다.",
    ["문제 하나 · 세션 · 강도 · 15분이면 충분하다."],
    "일정 › 주간 화면 하나만 띄우고 회의하라. 각자 자료를 가져오면 세 개의 계획이 나오고, 한 화면이면 하나가 나온다. 다음 주 시작에 15분만 잡아 셋을 정해 보라. 회의가 아니라 정하는 자리로 쓰면 15분에 끝난다.",
    "주 시작 회의에서 가장 먼저 정할 것은?",
    ["이번 주 훈련 강도","이번 주에 다룰 문제 하나","세션 형태","출전 명단"],
    1,
    "문제가 정해져야 나머지가 정해진다."),
  L("a3-toTrain-2",
    "분석 과제를 부하에 맞게 조절한다",
    "When the fix needs the wrong day",
    "분석에서 찾은 문제를 훈련으로 옮길 때 경기 원리를 유지하면서 목표 부하를 함께 정한다.\n\n인원을 줄이고 공간을 좁혔다고 회복용 저강도 훈련이 되는 것은 아니다. 좁은 공간에서는 고속 달리기가 줄어도 경합·가감속·반복 관여가 늘 수 있다.\n\n전체 공간과 1인당 면적, 운동·휴식 시간, 규칙, 역할, 반복 수를 함께 조절한다. RPE와 실제 움직임, 피로 반응으로 의도한 부하인지 확인한다.",
    ["훈련 부하 — 공간·인원·시간·휴식·규칙과 실제 반응"],
    {"현장에서":"고속 달리기와 가감속·경합 부하가 다르게 변하기 때문이다. 시간·휴식·규칙까지 조절하고 실제 반응을 확인한다."},
    "작은 구역에서 3대3으로 바꿨다. 부하를 어떻게 판단하는가?",
    ["인원이 적으니 반드시 저강도다","규칙·운동/휴식과 실제 움직임·RPE를 함께 본다","공간이 좁으니 모든 부하가 줄었다","최고속도가 낮으면 회복 훈련이다"],
    1,
    "고속 달리기와 가감속·경합 부하가 다르게 변하기 때문이다. 시간·휴식·규칙까지 조절하고 실제 반응을 확인한다."),
  L("a3-toTrain-3","한 시즌의 학습 곡선을 그린다","The season as a curriculum",
   "매주 문제 하나를 다루면 한 시즌에 서른 개가 넘는다. 그것들을 미리 큰 덩어리로 묶어 두면 시즌이 하나의 커리큘럼이 된다 — 앞은 기초, 중간은 조합, 뒤는 상황.",
   ["매주 하나가 시즌엔 서른 개","미리 덩어리로 묶는다","앞 기초 · 중간 조합 · 뒤 상황"],
   {analysis:"시즌 시작 전에 다룰 주제를 구간별로 나눠 적어 보라.",coach:"일정 › 연간의 주제 배분이 그 계획과 맞는지 확인하라."},
   "매주 문제를 하나씩 다루되 미리 묶어 두는 이유는?",["계획이 편해서","시즌 전체가 하나의 커리큘럼이 되게","보고를 위해","선수 설득"],1,
   "주간의 합이 저절로 시즌이 되지는 않는다.")
 ]});

mod({id:"a3-report",track:"analysis",level:3,area:"report",ko:"분석이 문화가 되게",en:"Making analysis a habit",src:["process","uefa"],
 flow:"팀 › 커뮤니티와 IDP › 성찰 — 분석의 언어가 팀 전체의 말이 되는 자리",
 why:"분석가 한 명이 잘하는 팀과 모두가 조금씩 분석하는 팀은 다르다. 심화 단계의 목표는 분석을 자기 일로 만드는 사람 수를 늘리는 것이다.",
 links:{},
 lessons:[
  L("a3-report-1","선수가 발표한다","Players present",
   "가끔 선수에게 장면 두 개를 주고 팀 앞에서 설명하게 한다. 설명하려면 보게 되고, 보게 되면 다음 경기에서 다르게 본다. 코치가 백 번 말하는 것보다 한 번 설명해 본 것이 오래간다.",
   ["설명하려면 보게 된다","장면 두 개면 충분","코치의 설명보다 오래 남는다"],
   {analysis:"발표용 클립을 쉬운 장면으로 골라 첫 시도를 성공시켜라.",coach:"첫 발표자는 말이 편한 선수로 — 분위기가 정해진다."},
   "선수가 직접 장면을 설명하게 하는 가장 큰 이유는?",["코치의 시간 절약","설명하려면 스스로 보게 되기 때문","평가를 위해","분위기 전환"],1,
   "가르치는 사람이 가장 많이 배운다."),
  L("a3-report-2","같은 언어를 계속 다듬는다","Keep the language alive",
   "팀 용어는 만들어 두면 끝이 아니라 계속 쓰이고 다듬어져야 산다. 새로 생긴 말은 등록하고, 안 쓰이는 말은 지운다. 살아 있는 사전만 팀을 하나로 만든다.",
   ["만든 뒤에도 계속 다듬는다","새 말은 등록, 죽은 말은 삭제","살아 있는 사전만 작동한다"],
   {analysis:"시즌 중반에 용어 목록을 훑고 안 쓰는 말을 지워라.",coach:"팀 › 공용어를 미팅 화면에 띄워 놓고 그 말만 써라."},
   "팀 공용어 목록을 정기적으로 정리해야 하는 이유는?",["보기 좋아서","안 쓰는 말이 쌓이면 사전이 죽고 아무도 안 본다","규정 때문","기록용"],1,
   "쓰이지 않는 사전은 없는 사전과 같다."),
  L("a3-report-3","분석의 마지막은 재관찰이다","Close the loop",
   "PROCESS 는 전달로 끝나지 않는다. 전달한 것이 다음 경기에서 어떻게 나타났는지 다시 보고, 거기서 다음 문제를 찾는다. 이 고리가 돌기 시작하면 팀은 스스로 나아진다.",
   ["전달 → 재관찰 → 다음 문제","고리가 돌면 스스로 나아진다","한 바퀴의 길이는 대개 한 주"],
   {analysis:"매주 보고서 첫 줄을 '지난주에 다룬 것이 어떻게 나타났나'로 시작하라.",coach:"리뷰 미팅의 첫 문장도 같게 하라 — 순환이 팀의 리듬이 된다."},
   "PROCESS 순환에서 전달 다음에 오는 것은?",["새 분석","재관찰(전달한 것이 어떻게 나타났는지 다시 봄)","훈련","휴식"],1,
   "다시 보지 않으면 순환이 아니라 직선이다.")
 ]});

/* ═══════════════════════ AT · 3 심화 ═══════════════════════
   ⚠ 교육용 정리다. 진단·치료 지시가 아니며 판단이 필요한 순간에는 의료인에게 보낸다. */
mod({id:"t3-risk",track:"at",level:3,area:"risk",ko:"예방 프로그램을 팀에 정착시킨다",en:"Make prevention stick",src:["fifamed","ypd","uefa"],
 flow:"보관함의 웜업을 팀 표준으로 만들어 두고, 일정 › 모든 세션의 웜업 칩에서 그것을 불러 쓴다",
 why:"효과가 검증된 예방 프로그램도 하지 않으면 0이다. 심화 단계의 문제는 무엇을 하느냐가 아니라 어떻게 계속하게 하느냐다.",
 links:{},
 lessons:[
  L("t3-risk-1",
    "담당과 수행 기준을 함께 정한다",
    "Coaches decide adherence",
    "예방 프로그램을 지속하려면 담당자와 대체 담당자, 일정과 수행 기준을 정한다. 코치가 직접 해야만 정착하는 것은 아니다.\n\n교육받은 코치와 스태프가 역할을 나누고 정확한 동작과 진행을 확인한다. 꾸준함을 이유로 안전하지 않은 수행을 허용하지 않는다.\n\n담당자가 없는 날에도 안전하게 할 수 있는 범위와 도움을 요청할 절차를 마련한다.",
    ["교육받은 담당·대체 인력과 수행 기준을 정하고 실행을 점검한다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "예방 프로그램을 지속시키는 적절한 운영은?",
    ["스태프가 진행하면 언제나 실패한다","교육받은 담당·대체 인력과 수행 기준을 정하고 실행을 점검한다","코치가 하면 정확하지 않아도 괜찮다","통증을 말해도 반복 횟수만 채운다"],
    1,
    "교육받은 담당·대체 인력과 수행 기준을 정하고 실행을 점검한다"),
  L("t3-risk-2",
    "경기 요구에 맞춰 웜업을 준비한다",
    "Before matches too",
    "훈련과 경기 웜업은 익숙한 요소를 공유할 수 있지만 목적·시간·부하가 달라 세부 내용이 같아야 하는 것은 아니다.\n\n예방 프로그램은 권장 대상과 실시 빈도·구성을 확인한다. 임의의 5분 축약판이 원래 프로그램과 같은 예방 효과를 낸다고 보장하지 않는다.\n\n경기 전에는 경기 동작에 준비되면서 불필요한 피로를 남기지 않도록 구성한다. 공간·시간이 제한되면 어떤 요소를 조정했는지 기록하고 준비된 대안을 사용한다.",
    ["경기와 훈련의 목적에 맞게 웜업을 조절하고 축약판의 효과를 동일하게 가정하지 않는다."],
    "훈련 중 권장 프로그램을 실시하고 경기 전 웜업은 경기 요구에 맞춰 조절한다. 시간이 부족했던 이유와 조정 내용도 다음 준비에 반영한다.",
    "시간이 부족해 예방 프로그램을 5분으로 줄였다. 옳은 설명은?",
    ["순서만 같으면 예방 효과도 같다","줄인 구성의 효과를 원래 프로그램과 같다고 가정하지 않는다","경기와 훈련의 웜업은 언제나 완전히 같아야 한다","짧아졌으므로 강도를 무조건 두 배 높인다"],
    1,
    "경기와 훈련의 목적에 맞게 웜업을 조절하고 축약판의 효과를 동일하게 가정하지 않는다."),
  L("t3-risk-3",
    "예방 계획 — 연구와 팀 기록을 함께",
    "Persuade with our numbers",
    "연구는 예방 방법의 효과와 적용 조건을 검토하는 근거이고, 팀 기록은 현재 필요와 실행 조건을 이해하는 자료다. 한쪽이 다른 쪽을 대체하지 않는다.\n\n작은 팀에서 특정 시기에 손상이 몰렸다면 노출 시간·기록 누락·우연과 다른 요인을 함께 확인한다. 그 분포만으로 예방 방법의 효과나 손상 원인을 확정하지 않는다.\n\n선수·보호자에게 설명할 때는 개인을 식별할 수 없는 집계로 필요와 계획을 보여 주고, 실제 수행과 결과를 추적한다.",
    ["연구의 효과·적용 조건과 팀의 노출·상황을 함께 검토한다"],
    "훈련 참여 시간과 손상 기록을 함께 정리하고 대상에 맞는 예방 방법의 실행 가능성을 논의한다.",
    "팀 기록과 예방 연구는 어떻게 활용하나?",
    ["팀 사례 하나가 여러 연구보다 언제나 강하다","연구의 효과·적용 조건과 팀의 노출·상황을 함께 검토한다","기록이 없으면 예방을 시작할 수 없다","손상 횟수가 줄면 프로그램 효과가 입증됐다"],
    1,
    "연구의 효과·적용 조건과 팀의 노출·상황을 함께 검토한다")
 ]});

mod({id:"t3-emerg",track:"at",level:3,area:"emerg",ko:"응급 체계를 팀 전체가 익힌다",en:"Train the whole staff",src:["fifamed","concussion"],
 flow:"팀 › 설정에 연락처·역할·동선을 두고, 시즌 시작 회의에서 전원이 함께 읽는다",
 why:"응급 상황에 스태프 한 명만 알고 있으면 그 사람이 없는 날 팀은 무방비다. 체계는 여러 사람이 같은 절차를 아는 상태를 말한다.",
 links:{},
 lessons:[
  L("t3-emerg-1",
    "응급 계획은 실제로 연습하고 갱신한다",
    "Rehearse once",
    "응급 실행 계획은 문서 작성만으로 끝나지 않는다. 실제 장소에서 역할, AED 접근, 연락과 구급차 동선을 함께 연습한다.\n\n“시즌 한 번 5분”은 모든 팀에 충분한 기준이 아니다. 장소·인력·장비 변경과 훈련 결과를 반영해 정기적으로 갱신한다. 교육·반복 연습은 역할 수행을 돕지만 결과를 보장하지 않는다.\n\n현장 동선 연습과 공인 CPR·AED 교육을 구분한다. 가슴압박은 교육용 마네킹으로 연습하며 실제 사람에게 시행하지 않는다. 빠진 역할이나 지연된 지점을 기록하고 다시 확인한다.",
    ["동선 리허설과 CPR·AED 교육을 구분하고 변경 사항에 맞춰 반복 확인한다."],
    "AED를 가져오는 실제 동선을 확인하고 잠긴 문이 있으면 접근 방법을 수정한다. CPR 기술은 공인 교육과 마네킹 실습으로 익힌다.",
    "원정 담당자와 AED 위치가 바뀌었다. 필요한 조치는?",
    ["시즌 초 한 번 연습했으므로 그대로 둔다","역할·접근 동선을 갱신하고 현장에서 다시 확인한다","문서에 이름만 바꾸고 장비 위치는 확인하지 않는다","가슴압박을 동료 선수에게 시험한다"],
    1,
    "동선 리허설과 CPR·AED 교육을 구분하고 변경 사항에 맞춰 반복 확인한다."),
  L("t3-emerg-2","원정에서도 같게","Away days",
   "홈에서만 계획이 있으면 원정에서 무방비다. 원정 갈 때마다 가장 가까운 병원, 구급차 진입로, 그 구장의 응급 담당을 확인하는 것을 절차로 만든다. 도착해서 5분이면 된다.",
   ["원정마다 병원·진입로·담당 확인","도착 후 5분 절차로","홈에만 있는 계획은 절반짜리"],
   {at:"원정 체크리스트에 이 세 가지를 고정으로 넣어라.",coach:"원정 도착 후 첫 5분을 그 확인에 쓰게 허락하라."},
   "원정 경기에서 응급 준비로 가장 먼저 확인할 것은?",["구급함","가장 가까운 병원·구급차 진입로·그 구장 담당","날씨","그라운드 상태"],1,
   "장소가 바뀌면 계획도 다시 확인해야 한다."),
  L("t3-emerg-3",
    "보호자와 미리 합의한다",
    "Agree with parents first",
    "어린 선수의 응급 상황에서 시간을 가장 많이 잡아먹는 것은 처치가 아니다.\n\n연락과 이송 동의다.\n\n보호자 연락처를 찾고, 전화가 안 되면 다른 번호를 찾고, 이송 동의를 받아야 하는 상황에서 연락이 안 되면 — 그 몇 분이 그대로 흘러간다.\n\n먼저 분명히 해 둘 것 — 생명이 걸린 응급에서는 동의를 기다리지 않는다. 119와 처치가 먼저이고, 보호자 연락은 그와 동시에 한다. 미리 받아 두는 이유는 그 외의 상황에서 시간을 잃지 않고, 의료진에게 필요한 정보를 바로 넘기기 위해서다.\n\n해법은 시즌 초에 한 번에 받아 두는 것이다.\n\n- 연락처 (여러 개)\n\n- 기저질환\n\n- 알레르기\n\n- 이송 동의\n\n이 넷이 있으면 그 순간 전화 한 통이면 된다. 그리고 알레르기와 기저질환은 의료진에게 바로 전달할 수 있어 처치가 빨라진다.\n\n실행에서 강한 규칙 하나 — 등록 없이 훈련에 참여시키지 않는 것을 팀 규칙으로 한다.\n\n엄격해 보이지만 이유가 분명하다. 등록되지 않은 선수가 다치면 연락도 정보 전달도 막힌다. 그리고 규칙이 없으면 미루다가 시즌이 끝난다.\n\n그 순간에 받으려 하면 늦는다.",
    ["연락처·기저질환·알레르기·이송 동의 · 시즌 초에 한 번에 · 그 순간엔 전화 한 통."],
    "필요한 정보와 긴급 연락 절차를 미리 확인하고, 동의 확인 때문에 생명을 구하는 응급 대응을 지연하지 않는다. 규칙이 없으면 미루다가 시즌이 끝나고, 그 사이에 사고가 난다. 지금 선수단에서 넷이 다 있는 선수가 몇 명인지 세어 보라. 빠진 선수가 있으면 이번 주에 받는다.",
    "어린 선수의 응급 대비에서 시즌 초에 반드시 받아 둘 것은?",
    ["건강검진 결과","연락처·기저질환·알레르기·이송 동의","보험 증서","학교 확인서"],
    1,
    "그 순간에 받으려 하면 늦는다.")
 ]});

mod({id:"t3-assess",track:"at",level:3,area:"assess",ko:"의료 네트워크와 일한다",en:"Working with the medical network",src:["fifamed","uefa"],
 flow:"팀 › 선수단 선수 카드의 상태·메모가 병원·보호자·코치를 잇는 공통 기록이 된다",
 why:"현장 스태프의 힘은 혼자 다 하는 데서 오지 않고 필요한 사람에게 정확히 넘기는 데서 온다. 넘길 곳이 미리 정해져 있으면 판단이 빨라진다.",
 links:{},
 lessons:[
  L("t3-assess-1","넘길 곳을 미리 정해 둔다","Know where to send",
   "무릎·발목·머리 각각에 대해 어디로 보낼지, 누구에게 연락할지 미리 정해 두면 그 순간 고민이 없다. 급할 때 병원을 찾기 시작하면 이미 늦다.",
   ["부위별로 보낼 곳을 미리 정한다","연락처와 담당자 이름까지","급할 때 찾으면 늦다"],
   {at:"부위별 의뢰처 목록을 만들어 매 시즌 갱신하라.",coach:"그 목록을 스태프 전원이 갖고 있게 하라."},
   "의료 의뢰처를 미리 정해 두는 이유는?",["비용 절감","그 순간에 찾기 시작하면 늦기 때문","관계 유지","기록"],1,
   "미리 정해 둔 경로만 급할 때 작동한다."),
  L("t3-assess-2","넘길 때 무엇을 함께 보내나","What to send with them",
   "'발목을 다쳤어요'만으로는 의료진도 처음부터 시작해야 한다. 발생 상황·시각·그때 증상·현장에서 한 조치·경기 일정을 함께 보내면 판단이 빨라지고 복귀 계획도 현실적으로 나온다.",
   ["발생 상황·시각·증상·조치·일정","현장 정보는 우리만 갖고 있다","보내면 판단이 빨라진다"],
   {at:"의뢰서 양식을 다섯 줄로 만들어 두라.",coach:"보호자가 병원에 갈 때 그 종이를 들려 보내라."},
   "의료 의뢰 시 함께 보내면 가장 유용한 정보는?",["선수 실력","발생 상황·시각·증상·현장 조치","팀 성적","보험 정보"],1,
   "현장 정보는 현장 사람만 갖고 있다."),
  L("t3-assess-3","소견을 현장 언어로 옮긴다","Translate the report",
   "의료 소견서의 말이 그대로 코치에게 가면 아무 결정도 못 한다. 스태프의 일은 그것을 '이번 주에 무엇을 할 수 있고 무엇을 못 하는가' 로 옮기는 것이다.",
   ["소견 → 이번 주 가능/불가능","번역이 스태프의 일","용어를 그대로 전달하지 않는다"],
   {at:"소견을 받으면 '이번 주 할 수 있는 것' 세 줄로 바꿔 코치에게 주라.",coach:"소견서 사본이 아니라 그 세 줄을 요청하라."},
   "의료 소견을 코치에게 전달할 때 스태프가 해야 할 일은?",["원문 그대로 전달","이번 주에 할 수 있는 것·없는 것으로 옮기기","요약만","전달하지 않음"],1,
   "번역되지 않은 소견은 결정을 만들지 못한다.")
 ]});

mod({id:"t3-rehab",track:"at",level:3,area:"rehab",ko:"재활을 팀 훈련과 잇는다",en:"Rehab inside the team week",src:["fifamed","ypd","knvb"],
 flow:"일정 › 세션 카드에 그 선수가 참여하는 부분을 적어 두면, 재활이 팀 주간 안에서 굴러간다",
 why:"재활을 팀 훈련과 떼어 놓으면 선수는 두 개의 세계를 산다. 심화 단계의 일은 재활 단계를 팀 주간 안에 배치해 돌아오는 길이 팀 안에 있게 하는 것이다.",
 links:{},
 lessons:[
  L("t3-rehab-1",
    "참여 범위를 정하고 매번 상태를 확인한다",
    "What they can join",
    "재활 단계별로 가능한 활동과 제한, 다음 확인 시점을 적어 두면 코치와 선수의 예상이 맞춰진다. 단계 번호만으로 활동을 정하지는 않는다.\n\n“2단계는 웜업, 3단계는 기술 훈련” 같은 대응은 팀별 계획의 예시일 뿐이다. 같은 기술 훈련이라도 달리기·접촉·충격 요구가 달라질 수 있다.\n\n미리 정한 계획이 당일 판단을 없애지는 않는다. 참여 전·중·후 증상과 기능을 확인하고 계획에서 벗어나면 중단·조절해 의료진과 재평가한다.",
    ["참여 범위는 미리 합의하되 매 세션 증상과 수행 반응을 확인한다."],
    "“패스는 허용”이어도 오늘 방향 전환에서 통증이 나타나면 해당 활동을 멈추고 기록·상담한다.",
    "계획상 기술 훈련이 가능한 날인데 새 통증이 생겼다. 어떻게 하는가?",
    ["단계표가 허용하므로 그대로 한다","참여를 조절·중단하고 상태를 확인해 의료진과 계획을 다시 맞춘다","단계 번호만 바꾸고 증상은 기록하지 않는다","다음 주까지 확인을 미룬다"],
    1,
    "참여 범위는 미리 합의하되 매 세션 증상과 수행 반응을 확인한다."),
  L("t3-rehab-2",
    "재활과 팀 활동의 총 요구를 함께 보기",
    "Rehab has load too",
    "재활 운동과 팀 활동이 겹치면 각 활동의 종류·시간·강도와 증상 반응을 함께 확인한다. 한쪽 기록만으로 전체 부담을 설명하지 않는다.\n\n세션 RPE×시간은 전체 체감 부담을 보는 한 지표다. 같은 점수라도 조직에 가는 기계적 요구나 고속 달리기 노출은 다를 수 있다.\n\n빈 기록은 0이 아니라 알 수 없음으로 남긴다. 의료·피지컬·코치가 필요한 범위에서 정보를 공유하고 합계 계획을 조정한다.",
    ["종류와 조직별 요구가 다를 수 있어 노출·증상도 함께 본다"],
    "자전거 30분과 고속 달리기의 체감 점수가 같아도 활동 종류와 제한 조건을 따로 적고 다음 계획을 정한다.",
    "재활과 팀 활동의 RPE×시간 합이 같으면 같은 부담인가?",
    ["점수가 같으면 모든 조직의 부담이 같다","종류와 조직별 요구가 다를 수 있어 노출·증상도 함께 본다","기록이 비면 부하는 0이다","재활은 팀 활동 합계에서 무조건 제외한다"],
    1,
    "종류와 조직별 요구가 다를 수 있어 노출·증상도 함께 본다"),
  L("t3-rehab-3",
    "오래 걸리는 부상에는 이정표를 둔다",
    "Milestones for long ones",
    "몇 달짜리 재활에서는 선수가 방향을 잃기 쉽다.\n\n몸의 회복은 느리고, 눈에 보이는 변화는 적고, 팀은 계속 앞으로 간다. 끝이 안 보이는 재활에서 사람이 먼저 지친다.\n\n그래서 필요한 것이 이정표다.\n\n- 개별 계획의 확인 간격에 맞춰 눈에 보이는 이정표를 둔다\n\n- 통과할 때마다 확인해 준다\n\n그러면 긴 시간이 견딜 만한 구간들로 나뉜다. \"6개월\"은 막막하지만 \"2주 뒤 조깅\"은 갈 수 있다. 그리고 그 하나를 통과하면 다음 2주가 생긴다.\n\n이정표의 조건은 앞에서 본 것과 같다 — 눈에 보여야 한다. \"좀 나아지기\"는 이정표가 아니고, \"통증 없이 5분 조깅\"은 이정표다.\n\n그리고 이 방식으로 심리적 준비도 만들어진다. 통과의 경험이 쌓이면 \"나는 나아지고 있다\"는 것이 느낌이 아니라 사실이 된다. 복귀 시점의 두려움(1부에서 본 실제 위험 요인)도 이렇게 줄어든다.\n\n그래서 실행 하나 — 선수가 원할 때 허용된 범위에서 진전을 함께 확인한다. 건강 정보를 팀 앞에 임의로 공개하지 않는다. 팀 안에 있다는 것이 함께 확인된다.",
    ["2주마다 눈에 보이는 이정표 · 통과를 함께 확인 · 긴 시간을 구간으로."],
    "선수가 원하고 공유에 동의한 범위에서 이정표의 진전을 함께 확인한다. 회복이 팀의 일이 되고, 그 선수는 팀 안에 남는다. 장기 재활 선수의 다음 2주 이정표를 하나 정해 함께 적어 보라. 눈으로 확인할 수 있는 것으로.",
    "장기 재활에서 2주 단위 이정표를 두는 이유는?",
    ["복귀를 앞당기기 위해","긴 시간을 견딜 만한 구간으로 나누고 심리적 준비를 만들기 위해","의료진의 요구라서","기록을 남기기 위해"],
    1,
    "끝이 안 보이는 재활에서 사람이 먼저 지친다.")
 ]});

mod({id:"t3-rtp",track:"at",level:3,area:"rtp",ko:"복귀 결정을 함께 내리는 구조",en:"Shared decision making",src:["fifamed","concussion","uefa"],
 flow:"팀 › 선수단 상태 변경과 경기 › 명단이 그 결정의 결과다 — 근거는 메모에 남긴다",
 why:"복귀 결정을 한 사람이 지면 그 사람은 언제나 보수적이거나 언제나 압박받는다. 역할과 순서가 정해진 구조가 사람을 보호하고 결정을 낫게 만든다.",
 links:{},
 lessons:[
  L("t3-rtp-1","누가 무엇에 답하는지 문서로","Who answers what",
   "의료는 조직 상태, 스태프는 기능 수행, 코치는 경기 요구, 선수는 준비 정도. 각자 답하는 질문을 문서로 정해 두면 누구도 혼자 지지 않는다. 이견이 있으면 더 보수적인 쪽을 따른다는 규칙도 함께 적는다.",
   ["역할별로 답하는 질문이 다르다","이견이 있으면 보수적인 쪽","혼자 지지 않는 구조"],
   {at:"복귀 결정표를 만들어 네 칸에 각자 서명하게 하라.",coach:"이견이 있을 때 경기 중요도로 밀어붙이지 마라."},
   "복귀 판단에서 스태프 간 이견이 있을 때의 원칙으로 적절한 것은?",["코치 결정 우선","더 보수적인 판단을 따른다","다수결","선수 의견 우선"],1,
   "되돌릴 수 없는 쪽의 비용이 훨씬 크다."),
  L("t3-rtp-2",
    "선수의 준비를 실제로 확인한다",
    "Check readiness properly",
    "'준비됐어?'를 명단 발표 자리에서 물으면 답은 정해져 있다.\n\n모두가 보고 있고, 아니라고 하면 자리를 잃는 것처럼 느껴진다. 그 자리에서는 거의 모두가 된다고 답한다.\n\n묻는 자리가 답을 정한다.\n\n그래서 방법이 정해진다.\n\n- 조용한 자리에서\n\n- 구체적으로 묻는다\n\n구체적이라는 것이 핵심이다. \"준비됐어?\"는 예/아니오를 요구하지만, 다음 질문들은 실제 상태를 끌어낸다.\n\n- \"그 동작이 아직 무섭니?\"\n\n- \"경기 중에 그 상황이 오면 어떻게 할 것 같아?\"\n\n두 번째 질문이 특히 유용하다. 선수가 머뭇거리거나 회피하는 답을 하면, 준비 상태를 더 물어볼 단서다. 말투 하나로 복귀 불가를 판단하지 않는다. 본인이 \"괜찮다\"고 말하고 있어도 그렇다.\n\n그리고 두려움은 복귀 과정에서 함께 살펴야 할 정보이며 재발을 단독 예측하는 기준은 아니다. 확인하지 않고 넘기는 것은 위험 요인 하나를 안 본 것이다.\n\n팀 앞에서 복귀 여부를 묻지 않는다.",
    ["조용한 자리에서 구체적으로 · '준비됐어?'는 답이 정해진 질문 · 두려움은 실제 위험 요인."],
    "팀 앞에서 복귀 여부를 묻지 마라. 그 자리의 답은 선수의 상태가 아니라 그 자리가 만든 답이다. 복귀 예정 선수에게 \"경기 중에 그 상황이 오면 어떻게 할 것 같아?\"를 물어보라. 답의 머뭇거림이 정보다.",
    "선수의 심리적 준비를 확인하기 좋은 방식은?",
    ["명단 발표 자리에서 전체에게 묻기","조용한 자리에서 구체적인 상황을 놓고 묻기","설문지로 받기","보호자를 통해 확인하기"],
    1,
    "묻는 자리가 답을 정한다."),
  L("t3-rtp-3",
    "결정을 기록으로 남긴다",
    "Record the decision",
    "복귀 결정은 기록으로 남긴다. 넷이면 된다.\n\n- 날짜\n\n- 근거\n\n- 참여한 사람\n\n- 남은 조건\n\n여기서 놓치기 쉬운 것이 있다 — 잘된 복귀에서도 남겨야 한다.\n\n이유가 둘이다.\n\n- 잘된 복귀에서 남기면 같은 판단을 다음에 반복할 수 있다\n\n- 잘못된 복귀에서 남기면 무엇을 놓쳤는지 배울 수 있다\n\n첫 번째가 자주 무시된다. 문제가 없으면 기록할 이유를 못 느낀다. 그런데 잘된 판단이 기록되지 않으면 매번 다시 발명해야 한다.\n\n그리고 남은 조건을 적는 것이 실용적으로 중요하다. \"복귀하되 4주간 출전 시간 60분 이하\"처럼 복귀 시점에 남아 있던 조건을 적어 두면, 3주 뒤에 그 조건이 아직 유효한지 확인할 수 있다.\n\n그래서 실행 하나 — 시즌 말에 복귀 결정 기록을 함께 읽는다. 잘된 것과 아쉬웠던 것을 나란히 보면 다음 시즌의 기준이 다듬어진다.",
    ["날짜·근거·참여자·남은 조건 · 잘된 복귀도 기록한다."],
    "최근 복귀의 날짜·근거·참여 담당자·남은 조건을 기록한다. 확인되지 않은 항목은 없음 대신 미확인으로 표시해 담당자와 확인한다.",
    "성공적인 복귀도 기록으로 남겨야 하는 이유는?",
    ["성과를 증명하기 위해","같은 판단을 다음에 반복할 수 있게","보호자에게 보고하기 위해","보험 처리를 위해"],
    1,
    "잘된 판단이 기록되지 않으면 매번 다시 발명해야 한다.")
 ]});

mod({id:"t3-record",track:"at",level:3,area:"record",ko:"기록으로 다음 시즌을 바꾼다",en:"Change next season with the data",src:["fifamed","uefa","ioc"],
 flow:"팀 › 선수단 · 경기 › 결과·기록 · 일정 › 연간 요약 — 세 곳의 기록이 프리시즌 계획의 근거가 된다",
 why:"부상 기록의 최종 목적은 다음 시즌 계획을 바꾸는 것이다. 바뀌지 않으면 기록은 서랍에서 끝나고, 팀은 매년 같은 자리에서 같은 일을 겪는다.",
 links:{},
 lessons:[
  L("t3-record-1",
    "부상 건수와 노출 시간을 함께 본다",
    "When it happens",
    "부상이 특정 시기에 모이면 일정·환경·훈련과 선수 구성을 더 살펴볼 단서가 된다. 건수가 많은 달이 곧 발생률이 가장 높은 달이라는 뜻은 아니다.\n\n훈련·경기 노출 시간, 부상 정의·중증도와 작은 표본의 불확실성을 함께 본다. 시기적 일치만으로 부하나 회복이 원인이라고 확정하지 않는다.\n\n팀 자료와 기존 연구·전문가 판단을 함께 사용해 조정하고 이후 기록으로 다시 점검한다.",
    ["노출 시간·정의·중증도·선수 구성과 일정 등 맥락이다"],
    "선수에게 현재 상태를 묻고 기존 기록과 비교한다. 확인되지 않은 부분을 남기고 자격을 갖춘 담당자와 다음 활동·확인 시점을 정한다.",
    "한 달의 부상 건수가 늘었다. 먼저 함께 볼 것은?",
    ["건수만으로 그 달이 가장 위험했다고 확정한다","노출 시간·정의·중증도·선수 구성과 일정 등 맥락이다","팀 기록은 모든 연구보다 항상 우월하다","같은 달에 몰렸으면 원인도 하나다"],
    1,
    "노출 시간·정의·중증도·선수 구성과 일정 등 맥락이다"),
  L("t3-record-2",
    "근거가 있는 결론과 모르는 부분을 나눈다",
    "Three lines that change things",
    "시즌 리포트는 실행할 내용이 보이도록 짧게 정리하되, 결론의 개수를 채우려고 단정하지 않는다.\n\n바꿀 점이 세 가지 나오지 않을 수도 있다. 자료가 부족하거나 결과가 불확실하면 그 사실과 다음에 확인할 항목을 적는다. 같은 관찰에서 여러 설명이 가능하다는 점도 구분한다.\n\n결론마다 근거, 담당자, 다시 확인할 시점을 붙인다. 기록 방식과 노출 시간이 달랐다면 비교의 한계도 함께 알린다.",
    ["결론 수를 채우지 않는다 — 확인된 내용·불확실성·다음 확인을 함께 적는다."],
    "“부상 건수는 늘었지만 노출 시간이 없어 발생률 변화는 판단하기 어렵다. 다음 시즌은 노출 시간도 기록한다”라고 적는다.",
    "자료를 검토했지만 개선안 세 가지를 뽑을 근거가 없다. 어떻게 하는가?",
    ["세 가지를 채울 때까지 원인을 단정한다","근거의 한계와 추가로 확인할 항목을 명시한다","자료가 부족해도 예방 효과가 입증됐다고 쓴다","불확실한 결과는 숨긴다"],
    1,
    "결론 수를 채우지 않는다 — 확인된 내용·불확실성·다음 확인을 함께 적는다."),
  L("t3-record-3",
    "숫자가 사람을 다치게 하지 않게",
    "Protect the people in the data",
    "이 트랙의 마지막 절은 기록의 윤리에 대한 것이다.\n\n부상 기록은 선수의 몸에 대한 민감한 정보다.\n\n그래서 정해 둬야 할 것이 셋이다.\n\n- 누가 볼 수 있는지(열람 범위)\n\n- 어디까지 공유하는지(공유 범위)\n\n- 얼마나 보관하는지(보관 기간)\n\n정해 두지 않으면 기록이 선수에게 불이익으로 돌아온다. 부상 이력이 선발이나 계약의 근거로 쓰이는 순간, 그 기록의 성격이 완전히 바뀐다.\n\n그리고 그 결과는 예측 가능하다 — 보호를 위한 기록이 불이익이 되면 아무도 말하지 않게 된다.\n\n1부의 첫 원칙으로 돌아온다. 말할 수 있는 분위기가 예방이다. 그런데 기록이 불이익으로 쓰이면 그 분위기가 무너지고, 무너지면 이 트랙의 모든 것이 작동하지 않는다.\n\n기록은 선수 보호를 위해 수집한 목적과 권한 범위 안에서 사용한다.\n\n그래서 마지막 규칙 — 부상 이력만으로 선수의 가치를 단정하지 않는다. 안전한 참여 결정에는 필요한 건강 정보를 적절한 권한 안에서 사용한다. 그리고 선수에게 그 기록이 어떻게 쓰이는지 알린다. 알아야 정직하게 말한다.",
    ["열람·공유 범위와 보관 기간을 정한다 · 목적은 보호이지 평가가 아니다."],
    "통증 보고 자체를 불이익의 근거로 삼지 않는다. 현재의 의료적 참여 제한과 안전한 역할 조정은 필요한 범위에서 별도로 판단한다. 한 번 그렇게 쓰이면 그 뒤로 아무도 통증을 말하지 않는다. 우리 팀의 열람 범위·공유 범위·보관 기간을 한 줄씩 적어 보라. 그리고 선수들에게 알린다.",
    "부상 기록 관리에서 반드시 정해 둬야 하는 것은?",
    ["기록 양식의 통일","열람·공유 범위와 보관 기간","작성자의 자격","보고 주기"],
    1,
    "보호를 위한 기록이 불이익이 되면 아무도 말하지 않게 된다.")
 ]});

})();
